    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-003', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('19f26af2aa19e96e352286f6f8eec442'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_winey","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":2,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":0,"intensity":4},"dominant_flavors":["bière_maltée","oignon_compoté","bœuf_braisé","aigre_doux"],"aroma_families":["malt","oignon_compoté","pain_d_épices","moutarde"],"target_textures":["viande_fondante","sauce_nappante"],"signature_ingredients":["Bœuf à braiser cru","Bière blonde","Oignon jaune cru","Pain d''épices"],"identity_guardrails":["Sans bière, ce n''est plus une carbonade : le liquide de braisage est l''identité même du plat, et le vin en ferait une daube.","Le pain d''épices tartiné de moutarde lie et adoucit la sauce ; remplacé par de la fécule, il ne reste qu''un ragoût de bœuf à la bière.","Le poids d''oignons compotés approche la moitié de celui de la viande ; réduit à un oignon, la sauce perd son corps et son sucre."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
