  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:IT-003', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('224a17f3b5cba20f155230ce161e3cd4'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":3,"pungency":3,"richness":4,"freshness":2,"intensity":5},"dominant_flavors":["épices chaudes","aromatique","profond"],"aroma_families":["aromates_cuits","matière_grasse_chauffée"],"target_textures":["tendre","contraste_léger"],"signature_ingredients":["Spaghetti secs","Guanciale cru","Jaune d''œuf cru","Œuf cru"],"identity_guardrails":["pas_de_crème","œufs_hors_du_feu","pecorino_ou_parmesan_affiné","guanciale_ou_pancetta"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Spaghetti à la sauce bolognaise', 'spaghetti a la sauce bolognaise', 'France / cuisine domestique internationale', 'France / cuisine domestique internationale',
     'meal', 'pâtes en sauce', 'domestic_standard', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Spaghetti à la sauce bolognaise', 'Spaghettis avec sauce de bœuf haché longuement mijoté avec le soffritto et la tomate', ds.id, 'IT-004',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a6862b00709acfd9f22d2ede4eaca839',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['tomate cuite','viande rissolée','légume compoté']::text[],
    ARRAY['tomate_cuite','oignon_compoté','viande_rissolée','thym']::text[], ARRAY['sauce_nappante','pâtes_fermes','haché_fondant']::text[],
    ARRAY['Spaghetti secs','Bœuf haché cru 15 % MG','Tomate concassée en conserve','Carotte crue','Céleri branche cru']::text[], ARRAY['Sans le trio oignon-carotte-céleri fondu au départ, il reste une sauce tomate à la viande : c''est le soffritto qui donne au plat son sucre et son corps, et cinq à six sources sur huit le portent.','La viande hachée doit rissoler avant d''être mouillée ; pochée directement dans la tomate, elle ne développe rien et la sauce reste plate quelle que soit la durée du mijotage.','La tomate doit être une base longuement réduite, pas un concentré délayé : deux sources font l''inverse et produisent une autre sauce, épaisse et sucrée, qui ne mijote pas.','Les pâtes se terminent dans la sauce avec un peu de leur eau de cuisson ; servies nues avec la sauce posée dessus, le plat se dissocie dans l''assiette.']::text[],
    ARRAY['soffritto','saisie du haché','cuisson du concentré','mijotage','cuisson al dente','enrobage à l''eau de cuisson']::text[], ARRAY['Ragù à l''italienne (une source) : trois viandes — bœuf haché, chair à saucisse et pancetta — déglacées au vin rouge puis mouillées au lait entier, avec romarin et laurier ; ni la chair à saucisse ni la pancetta ne sont au catalogue','Déglaçage au vin rouge avant la tomate (deux sources sur huit)','Deux verres de lait entier en fin de mijotage pour arrondir l''acidité (une source)','Version végétale : une boîte de lentilles et deux gros champignons portobello à la place du bœuf (une source)','Champignons de Paris émincés avec le soffritto (deux sources)','Foie de volaille haché ajouté au bœuf, 160 g pour quatre (une source)','Spaghettis de courgettes à la place des pâtes, 800 g pour quatre (une source)','Pincée de sucre ou carré de sucre pour corriger l''acidité (deux sources)','Basilic frais ciselé en finition plutôt que thym et laurier (deux sources)']::text[], ARRAY['gluten','céleri','lait']::text[],
    'La sauce se garde quatre jours au réfrigérateur dans un récipient fermé et gagne à être faite la veille : la tomate finit de perdre son acidité au froid. Elle se congèle trois mois, sans les pâtes. Réchauffer à feu doux avec une cuillerée d''eau. Les pâtes déjà enrobées ne se conservent pas plus de vingt-quatre heures et ne se congèlent pas : elles rendent leur eau et deviennent farineuses.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
