    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','fromage fondu','basilic']::text[],
