    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:IT-006', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f2c05bcb425fa1ea37991ca685642b53'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"tomato_herbal","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","fromage fondu","basilic"],"aroma_families":["tomate_cuite","oignon_compoté","fromage_gratiné","basilic"],"target_textures":["gnocchi_moelleux","sauce_nappante","croûte_gratinée"],"signature_ingredients":["Gnocchi de pomme de terre frais","Mozzarella","Tomate concassée en conserve","Basilic frais"],"identity_guardrails":["Les trois éléments du nom doivent être là et rester distincts : des gnocchi moelleux, une sauce tomate réduite, une mozzarella fondue en surface. Fondue dans la sauce, elle disparaît et le plat n''est plus qu''un gnocchi à la tomate.","La mozzarella s''égoutte avant de passer au four : son eau de saumure délave la sauce et la rend filandreuse, et c''est la faute qui défait ce plat le plus souvent.","La sauce doit être réduite avant l''assemblage — les gnocchi ne rendent pas d''eau à la cuisson mais n''en absorbent pas non plus, et rien ne rattrapera au four une sauce trop liquide.","Le basilic entre à la sortie du four : passé au gril, il noircit et le plat perd la seule note fraîche qui l''équilibre."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
