  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'IT-007', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Pâte maturée 24 h au froid','légumes grillés']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"IT-007","variants":["Pâte maturée 24 h au froid","légumes grillés"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:IT-007', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('95a14598d632b27842b8068fc66f91d1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"tomato_herbal","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":1,"pungency":2,"richness":3,"freshness":3,"intensity":4},"dominant_flavors":["tomate","herbacé","acidulé"],"aroma_families":["tomate_cuite","basilic"],"target_textures":["dessus_doré","intérieur_fondant_ou_crémeux"],"signature_ingredients":["Farine de blé type 00","Eau","Levure boulangère sèche","Sel fin"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Soupe à l’oignon gratinée', 'soupe a l oignon gratinee', 'France', 'France',
     'meal', 'soupe', 'named_traditional_dish', 'brothy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Soupe à l’oignon gratinée', 'Oignons longuement caramélisés en soupe liée, servie avec croûtons et fromage gratiné', ds.id, 'FR-012',
    'Myko', 'editorial', 6, 20, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '61bf6d2ac9539dc5f2619964b5d89408',
    '{"sweet":3,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":0,"intensity":4}'::jsonb, ARRAY['oignon caramélisé','bouillon de volaille réduit','gruyère gratiné','vin blanc réduit']::text[],
    ARRAY['allium caramélisé','bouillon de volaille','fromage gratiné','pain grillé']::text[], ARRAY['bouillon nappant','oignons fondants','croûte de fromage gratinée','pain imbibé']::text[],
    ARRAY['Oignon jaune cru','Bouillon de volaille','Pain de campagne','Gruyère râpé']::text[], ARRAY['L''oignon doit atteindre une coloration acajou franche : simplement fondu et blond, il donne une soupe d''oignons, pas la soupe à l''oignon gratinée.','Le gratin est le plat autant que le bouillon : sans la tranche de pain couverte de fromage et passée au gril, il ne reste qu''une soupe d''oignons.','Le mouillement doit rester un bouillon clair et peu lié ; la farine ne sert qu''à donner du corps, et une soupe liée comme une sauce cesse d''être ce plat.','Aucune crème n''entre ici : sur les six pages du dossier, pas une n''en met, et la richesse vient du beurre de départ et du fromage fondu.']::text[],
    ARRAY['caramélisation des oignons','roux','déglaçage','mijotage','gratinage']::text[], ARRAY['La trame marmiton au champagne troque le bouillon contre 35 cl de champagne et 3 cl de porto, et lie la soupe de deux jaunes d''œuf battus avant de la passer au gril.','Le comté et le beaufort tiennent le rôle du gruyère sur deux des six pages : le comté sale davantage, le beaufort donne une croûte plus souple et plus grasse.','Deux auteurs de chefsimon relèvent la soupe d''une pincée de quatre-épices ou de muscade râpée ajoutée au bouillon.','Une cuillerée à soupe de sucre jetée sur les oignons en début de cuisson accélère leur coloration, comme le fait une page de chefsimon.','Chef Simon jette une poignée de vermicelles fins dans le bouillon en fin de cuisson, en option, pour épaissir la soupe sans farine.','Une page de chefsimon prend du pain complet ou aux céréales pour les croûtons, ce qui donne un gratin plus rustique et plus dense.']::text[], ARRAY['gluten','lait','sulfites']::text[],
    'Le bouillon d''oignons se garde trois jours au réfrigérateur entre 0 et 4 °C dans un contenant fermé, et se congèle jusqu''à trois mois ; il gagne même à reposer une nuit, la caramélisation continuant de diffuser. Ne jamais conserver la soupe déjà gratinée : le pain se défait en bouillie et le fromage refroidi devient élastique. Gratiner au moment du service, sur du pain séché du jour et une soupe ramenée au frémissement.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
