    VALUES
      ('content', to_jsonb('61bf6d2ac9539dc5f2619964b5d89408'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":3,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":0,"intensity":4},"dominant_flavors":["oignon caramélisé","bouillon de volaille réduit","gruyère gratiné","vin blanc réduit"],"aroma_families":["allium caramélisé","bouillon de volaille","fromage gratiné","pain grillé"],"target_textures":["bouillon nappant","oignons fondants","croûte de fromage gratinée","pain imbibé"],"signature_ingredients":["Oignon jaune cru","Bouillon de volaille","Pain de campagne","Gruyère râpé"],"identity_guardrails":["L''oignon doit atteindre une coloration acajou franche : simplement fondu et blond, il donne une soupe d''oignons, pas la soupe à l''oignon gratinée.","Le gratin est le plat autant que le bouillon : sans la tranche de pain couverte de fromage et passée au gril, il ne reste qu''une soupe d''oignons.","Le mouillement doit rester un bouillon clair et peu lié ; la farine ne sert qu''à donner du corps, et une soupe liée comme une sauce cesse d''être ce plat.","Aucune crème n''entre ici : sur les six pages du dossier, pas une n''en met, et la richesse vient du beurre de départ et du fromage fondu."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Velouté de champignons', 'veloute de champignons', 'France', 'France',
     'meal', 'soupe', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Velouté de champignons', 'Champignons de Paris mixés en velouté sur une base de béchamel, liés à la crème fraîche', ds.id, 'FR-013',
    'Myko', 'editorial', 6, 20, 35, 'facile',
    NULL, NULL,
    'B', 'candidate', '6420b50bea2fb746a3d1b1157eae4aec',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['champignon terreux','lait et crème','beurre','oignon fondu']::text[],
    ARRAY['champignon','lacté','beurre','persil frais']::text[], ARRAY['velouté lisse','nappant','sans fibre','champignons poêlés fermes']::text[],
    ARRAY['Champignon de Paris frais','Lait entier','Crème fraîche liquide entière']::text[], ARRAY['Le champignon doit rester l''ingrédient dominant en masse : dès qu''un autre légume prend le dessus — poireau, pomme de terre, carotte — le velouté change de nom, comme le montrent les deux titres dérivants du dossier.','Le liquide est lacté : remplacer entièrement le lait par de l''eau ou du bouillon donne une soupe de champignons, pas un velouté.','Les champignons doivent avoir rendu puis évaporé leur eau avant le mouillement ; noyés trop tôt, ils bouillent au lieu de concentrer et le velouté reste plat.','La texture doit être entièrement mixée et sans fibre : des lamelles laissées entières en feraient une soupe rustique.']::text[],
    ARRAY['parage','suer','roux blanc','mijotage','mixage','poêlage']::text[], ARRAY['Chef Simon lie le velouté hors du feu de deux jaunes d''œuf battus avec la crème : la texture s''épaissit sans farine supplémentaire, mais toute ébullition est ensuite interdite.','Une page chefsimon déglace les champignons de 10 cl de vin blanc sec avant de mouiller, ce qui apporte une acidité plus franche que le citron.','La version express de marmiton part de 460 g de champignons de Paris en boîte égouttés, remplace le lait par 25 cl de crème liquide et lie au pain sec émietté.','Deux pages se passent de roux et lient le velouté d''une pomme de terre cuite avec les champignons puis mixée avec eux.','750g monte un velouté aux champignons des bois où les champignons de Paris cèdent la place à des sauvages, relevés de poudre de chili, de gingembre râpé et de paprika fumé.','Deux cuillerées à café de madère ajoutées en fin de cuisson, en option chez marmiton.','Une page chefsimon monte le même velouté sur une base de poireaux et de gingembre frais, les champignons n''y étant plus qu''une garniture poêlée avec du bacon grillé.']::text[], ARRAY['gluten','lait']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans un contenant bien fermé — le champignon capte vite les odeurs voisines. Réchauffer à feu doux sans jamais bouillir, la crème tranchant à l''ébullition. Pour la congélation, congeler la base mixée non crémée jusqu''à trois mois et n''incorporer la crème qu''au réchauffage : congelée crémée, elle se déphase et rend le velouté granuleux. Les champignons poêlés de garniture se font au dernier moment, ils ramollissent en quelques heures.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
