DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Croque-monsieur', 'croque monsieur', 'France — cuisine de café parisienne', 'France — cuisine de café parisienne',
     'meal', 'sandwich chaud gratiné', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Croque-monsieur', 'Pain de mie fourré au jambon blanc et gruyère, nappé de béchamel, gratiné au four', ds.id, 'FR-023',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', '349c701460c3a39fc8502b8bc942653f',
    '{"sweet":1,"salty":4,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":3}'::jsonb, ARRAY['fromage_fondu','jambon_cuit','beurre','muscade']::text[],
    ARRAY['beurre','gruyère','pain_grillé','muscade']::text[], ARRAY['croûte_gratinée','mie_moelleuse','cœur_fondant']::text[],
    ARRAY['Pain de mie','Jambon blanc cuit','Gruyère râpé']::text[], ARRAY['Sans pain de mie, ce n''est plus un croque-monsieur : la version montée sur des tranches d''aubergine que porte le dossier est un homonyme, et le nom ne suit pas l''ingrédient.','Le jambon cuit et le fromage fondant vont par paire ; retirer le jambon donne un croque au fromage, qui porte un autre nom et n''a plus la même part de protéine.','La sauce blanche doit napper le pain dessus et dedans : réduite à un filet de lait, le croque sort sec et devient un toast grillé, ce que deux sources assument d''ailleurs comme une recette distincte.']::text[],
    ARRAY['roux blanc','béchamel','montage en sandwich','cuisson au four','gratinage sous le gril']::text[], ARRAY['Croque-monsieur en gratin : pain remplacé par des biscottes, noyées dans un litre de béchamel pour six et gratinées en plat (750g.com)','Croque-monsieur d''aubergines : tranches d''aubergine à la place du pain, avec tomate, crème et moutarde — un homonyme plutôt qu''une variante (marmiton.org)','Crème épaisse étalée à cru à la place de la béchamel, sans roux (marmiton.org) — la crème liquide, elle, n''apparaît que dans le croque d''aubergines','Un simple filet de lait sur le pain, sans sauce — quatre cuillerées à soupe pour deux croques, ou une cuisson à l''airfryer (chefsimon.com, deux sources)','Emmental râpé ou comté râpé à la place du gruyère (trois sources)','Crème de champignons au parmesan en remplacement de la béchamel (chefsimon.com)','Une pointe de moutarde : le dossier ne la porte que dans le croque d''aubergines, où elle est étalée sur le légume et non sur du pain (marmiton.org)','Pain de mie maison à l''ail des ours, et origan ou herbes de Provence sur le fromage (chefsimon.com, marmiton.org)']::text[], ARRAY['gluten','lait']::text[],
    'Se mange en sortant du four : la croûte gratinée retombe en quelques minutes et la mie finit par boire la sauce. Les croques montés crus se gardent vingt-quatre heures au réfrigérateur, à plat et sous film, et se cuisent directement à la sortie du froid, sans repos, en comptant cinq minutes de plus. La béchamel seule tient trois jours au frais, filmée au contact pour l''empêcher de faire une peau, et se détend au fouet avec une cuillerée de lait tiède. Ne pas congeler un croque cuit : le pain rend son eau au réchauffage et la mie devient spongieuse.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
