  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Acheter du pain de mie en tranches carrées épaisses, de celles qui tiennent debout sans plier, et du jambon cuit détaillé à la même largeur que le pain : une tranche qui dépasse brûle au four, une tranche trop petite laisse des coins de pain nus qui se dessèchent. Compter deux tranches de pain et une de jambon par croque.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre le beurre dans une petite casserole à feu doux, verser la farine d''un coup et remuer une bonne minute sans laisser prendre couleur. Ce temps-là n''est pas décoratif : une farine crue donne à la sauce un goût de colle que le fromage ne couvre pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser le lait en trois fois, en fouettant à chaque ajout jusqu''à ce que la sauce redevienne lisse avant la suivante. Laisser épaissir trois à quatre minutes à petit feu, puis saler, poivrer et râper la muscade. La béchamel doit napper le dos d''une cuillère et retomber en ruban lent : trop liquide elle détrempe la mie, trop serrée elle ne s''étale pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Préchauffer le four à 200 °C et passer les tranches de pain au grille-pain sur un réglage doux, une minute à peine, juste pour les raidir sans les colorer. Le pain de mie est une éponge ; sec, il retient la sauce en surface, humide il la boit et le croque s''affaisse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Étaler une cuillerée de béchamel sur la face intérieure de chaque tranche, poser le jambon plié à la taille du pain, répartir la moitié du gruyère par-dessus et refermer en pressant légèrement de la paume pour souder le montage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Napper le dessus des croques du reste de béchamel en allant jusqu''aux bords — c''est la sauce qui protège les angles du pain — puis couvrir du gruyère restant. Poser sur une plaque garnie de papier cuisson, sans que les croques se touchent, pour que la chaleur circule sur les côtés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner dix à douze minutes à 200 °C, puis passer deux à trois minutes sous le gril en surveillant sans quitter le four : le fromage passe du blond au brûlé en quelques secondes. Le croque est prêt quand le gruyère cloque et qu''un liseré doré remonte sur les bords du pain.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Laisser reposer deux minutes hors du four avant de couper en deux en diagonale. Coupé aussitôt sorti, le fromage coule et le croque se vide ; deux minutes suffisent à ce qu''il se tienne à la lame.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'FR-023', 'recipe_family', 'Croque-monsieur',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

