DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gougères au fromage', 'gougeres au fromage', 'France — Bourgogne', 'France — Bourgogne',
     'meal', 'gougères apéritives en pâte à choux', 'named_traditional_dish', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gougères au fromage', 'Petits choux au gruyère soufflés au four, servis chauds en apéritif', ds.id, 'FR-031',
    'Myko', 'editorial', 6, 20, 20, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'ddada49aa8932081ad9bbbcf004c33c6',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":0,"intensity":3}'::jsonb, ARRAY['fromage_affiné','beurre','muscade']::text[],
    ARRAY['beurre','gruyère','pâte_à_choux']::text[], ARRAY['coque_croustillante','intérieur_creux','mie_soufflée']::text[],
    ARRAY['Gruyère râpé','Beurre doux','Œuf cru','Farine de blé T55']::text[], ARRAY['Sans fromage, ce sont des choux salés et non des gougères : les neuf sources en mettent en moyenne 100 g pour 100 g de farine, autant que la farine elle-même.','La panade doit être desséchée sur le feu avant les œufs ; sans ce passage la pâte ne gonfle pas et on obtient des galettes, quelle que soit la température du four.','Le fromage est râpé et incorporé dans la pâte, pas seulement parsemé dessus : la gougère est creuse, et si le goût n''est pas dans la coque il n''est nulle part.']::text[],
    ARRAY['panade','desséchage de la panade','incorporation des œufs à la texture','pochage à la poche','cuisson en pâte à choux','dorure au jaune']::text[], ARRAY['Gougères aux trois fromages : mimolette, gouda et emmental à parts égales à la place du gruyère (marmiton.org)','Parmesan et fromage de chèvre basque, 150 g et 50 g (chefsimon.com)','Comté râpé à la place du gruyère, la source donnant les deux comme équivalents (chefsimon.com)','Moitié eau, moitié lait entier dans la panade, pour une coque plus tendre (750g.com)','Pointe de piment de Cayenne ou de piment d''Espelette à la place du poivre (750g.com, marmiton.org)','Thym ou ciboulette hachée dans la pâte (marmiton.org)','Mélange de graines sur le dessus et pâte pochée en bâtonnets, cuits douze minutes (750g.com)','Beignets de gougères : la même pâte, plus fluide et frite au lieu d''être cuite au four (marmiton.org)']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Meilleures dans l''heure qui suit la cuisson. Deux jours dans une boîte hermétique à température ambiante, jamais au réfrigérateur : l''humidité du froid ramollit la coque en une nuit. Elles retrouvent leur croustillant en cinq minutes à 160 °C, four sec et porte entrouverte à la fin. La pâte crue se poche directement sur une plaque et se congèle telle quelle : les tas pris se rangent ensuite en sac et se cuisent sans décongélation, en ajoutant trois à quatre minutes. Cuites, elles se congèlent aussi trois mois et se réchauffent au four sans être décongelées.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
