     status, confidence_level)
  VALUES
    ('Parmentier de canard', 'parmentier de canard', 'France (Sud-Ouest)', 'France (Sud-Ouest)',
     'meal', 'gratin parmentier', 'named_traditional_dish', 'rich_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Parmentier de canard', 'Confit de canard effiloché recouvert d''une purée de pommes de terre, gratiné au comté', ds.id, 'FR-037',
    'Myko', 'editorial', 6, 40, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', '1869c4a00f61f247411c856724c92956',
    '{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['canard confit','beurre','oignon fondu','fromage gratiné']::text[],
    ARRAY['graisse de canard','oignon compoté','croûte grillée','muscade']::text[], ARRAY['chair filandreuse','purée souple','croûte croustillante']::text[],
    ARRAY['Confit de canard cuit, effiloché','Pomme de terre crue, épluchée','Beurre doux']::text[], ARRAY['Sans confit de canard ce n''est plus qu''un hachis parmentier : la chair effilochée cuite dans sa graisse est le plat lui-même','Deux couches distinctes, garniture dessous et purée dessus — mélangées, c''est une autre préparation','Une croûte dorée au four : un parmentier servi sans gratiner n''est pas fini','Aucune viande hachée crue en remplacement du confit, même à protéines égales']::text[],
    ARRAY['confit tiédi','effilochage','fondue d''oignons','purée au presse-purée','montage en couches','gratinage']::text[], ARRAY['Au potiron vanillé, moitié potiron moitié pomme de terre, la purée mouillée au lait de soja (marmiton)','Aux noisettes concassées dans la garniture et au comté sur le dessus (chefsimon)','Aux petits pois écossés et oignons nouveaux à la place de la purée de pomme de terre (chefsimon)','Aux courgettes et panais mêlés à la purée, finition ciboulette (750g)','Garniture déglacée au madère ou au porto et liée d''un fond de canard, montée sur des tranches de pain (chefsimon)','Purée enrichie de crème fraîche en plus du lait (marmiton, chefsimon)','Une pointe de miel dans le canard effiloché (marmiton)','Dessus de chapelure plutôt que de fromage, éventuellement avec un éclat de foie gras dans la garniture (750g)']::text[], ARRAY['lait']::text[],
    'Se garde 3 jours au réfrigérateur, couvert, et se réchauffe 25 minutes à 170 °C plutôt qu''au micro-ondes, qui détrempe la croûte. Se congèle 2 mois, cru ou cuit, dans son plat filmé : décongeler une nuit au froid avant de cuire ou de réchauffer. Ne pas recongeler un confit déjà décongelé.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
