  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:FR-037', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1869c4a00f61f247411c856724c92956'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"rich_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["canard confit","beurre","oignon fondu","fromage gratiné"],"aroma_families":["graisse de canard","oignon compoté","croûte grillée","muscade"],"target_textures":["chair filandreuse","purée souple","croûte croustillante"],"signature_ingredients":["Confit de canard cuit, effiloché","Pomme de terre crue, épluchée","Beurre doux"],"identity_guardrails":["Sans confit de canard ce n''est plus qu''un hachis parmentier : la chair effilochée cuite dans sa graisse est le plat lui-même","Deux couches distinctes, garniture dessous et purée dessus — mélangées, c''est une autre préparation","Une croûte dorée au four : un parmentier servi sans gratiner n''est pas fini","Aucune viande hachée crue en remplacement du confit, même à protéines égales"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
