      ('sensory_contract', '{"profile":"rich_winey","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":2,"richness":5,"freshness":1,"intensity":5},"dominant_flavors":["umami","rôti","vinique"],"aroma_families":["oignon_compoté","échalote","vin_rouge_réduit","champignon_terreux","beurre","fumé","vin_rouge","lardon"],"target_textures":["blanc_pris_jaune_coulant","sauce_nappante","croûton_croustillant"],"signature_ingredients":[],"identity_guardrails":["jaune_coulant","sauce_au_vin_dominante","pas_de_sauce_crémée"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
