  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-123', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b3eef4dfb642e02fc94300b195eff59f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_acidic","scores":{"sweet":1,"salty":3,"acidic":5,"bitter":1,"umami":2,"heat":1,"pungency":2,"richness":1,"freshness":5,"intensity":3},"dominant_flavors":["frais","acidulé","herbacé"],"aroma_families":["oignon_compoté","feta","aneth","épinard","huile_olive"],"target_textures":["filo_croustillante","farce_fondante"],"signature_ingredients":["Pâte filo","Épinard frais","Feta","Œuf cru"],"identity_guardrails":["épinard_feta_filo","herbes_fraîches","farce_non_aqueuse"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
