     'Huile d''olive vierge extra', 70, 'ml', 'required',
     'assaisonnement', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'boulgour fin cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Boulgour fin cru', 45, 'g', 'required',
     'céréale', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'menthe fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Menthe fraîche', 20, 'g', 'required',
     'herbe', false, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 5, 'g', 'required',
     'assaisonnement', false, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'required',
     'assaisonnement', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Verser le boulgour fin dans un bol et le couvrir tout juste d''eau froide, deux fois son volume et pas davantage. Le laisser gonfler vingt minutes, puis le presser entre les paumes au-dessus de l''évier pour en chasser l''eau. Un boulgour fin ne se cuit pas : il s''attendrit à froid, et gonflé à l''eau bouillante il tourne à la bouillie. Ce sont 45 g pour six, une poignée, et pas un gramme de plus — ici le blé assaisonne le persil, il ne le remplace pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Compter cinq à six bottes de persil plat pour obtenir les 250 g de feuilles déclarés : les tiges pèsent le tiers d''une botte et ne se mangent pas dans ce plat. Laver le persil en le plongeant tête en bas dans une grande eau froide, le secouer, puis le sécher soigneusement au linge ou en essoreuse. Un persil humide se hache en pâte et le taboulé rend son eau au fond du saladier — c''est le séchage qui décide de la texture finale, avant le couteau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Effeuiller le persil, rassembler les feuilles en tas serré sur la planche et les hacher au couteau bien affûté, en allers-retours nets plutôt qu''en écrasant. Ne jamais passer le persil au robot : la lame le meurtrit, il noircit en quelques minutes et son parfum part avec le jus. Effeuiller la menthe de la même façon et la ciseler plus grossièrement, mais seulement au moment de l''assemblage — son huile essentielle s''évapore vite et une menthe hachée trop tôt ne laisse qu''une amertume verte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Couper les tomates en deux, retirer la partie gélatineuse et les graines à la petite cuillère, puis tailler la chair en dés de cinq millimètres. Épépiner n''est pas une coquetterie : c''est l''eau des graines qui délave l''assaisonnement et fait tomber le hachis au fond du plat. Poser les dés dans une passoire avec une pincée de sel et les laisser s''égoutter dix minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Émincer les oignons nouveaux très finement, le blanc et le vert ensemble, puis les frotter du bout des doigts avec une pincée de sel. Ce frottage casse en quelques secondes leur agressivité soufrée, là où un oignon cru laissé tel quel prend le dessus sur les herbes et se sent encore le lendemain.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mélanger le jus de citron, l''huile d''olive, le sel et le poivre dans le fond du saladier, puis y ajouter le boulgour pressé et remuer. Le blé boit le citron avant les herbes et s''assaisonne ainsi de l''intérieur ; versée sur le tout à la fin, la même quantité resterait en flaque au fond. Ajouter ensuite les oignons frottés, les tomates égouttées, le persil puis la menthe, dans cet ordre, et mélanger à deux fourchettes en soulevant plutôt qu''en tournant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Goûter et rectifier, en jugeant le citron avant le sel : un taboulé libanais doit être franchement acide, presque au bord du trop, parce que c''est l''acidité qui tient un hachis d''herbes crues. Le laisser reposer un quart d''heure au frais, pas davantage — le temps que le boulgour finisse de boire, avant que le persil ne commence à faner. Servir frais, étalé dans un plat large plutôt que dressé en dôme, où le poids tasse les herbes et chasse le jus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'REAL-138', 'recipe_family', 'Taboulé libanais',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'REAL-138', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Au quinoa plutôt qu''au boulgour : 80 g pour trois, cuits à l''eau puis refroidis (chefsimon)','Au persil frisé plutôt que plat, deux petits bouquets pour quatre (chefsimon, deux versions)','Version plus chargée en blé : 200 g de boulgour fin pour huit, avec de l''oignon jaune à la place de l''oignon nouveau (chefsimon)','Une cuillerée à soupe de menthe séchée en plus de la menthe fraîche (chefsimon)','Une pincée de piment d''Espelette et une pointe de cannelle, toutes deux données pour facultatives (750g)','Un demi-concombre en petits dés ajouté au moment du service (chefsimon)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"REAL-138","variants":["Au quinoa plutôt qu''au boulgour : 80 g pour trois, cuits à l''eau puis refroidis (chefsimon)","Au persil frisé plutôt que plat, deux petits bouquets pour quatre (chefsimon, deux versions)","Version plus chargée en blé : 200 g de boulgour fin pour huit, avec de l''oignon jaune à la place de l''oignon nouveau (chefsimon)","Une cuillerée à soupe de menthe séchée en plus de la menthe fraîche (chefsimon)","Une pincée de piment d''Espelette et une pointe de cannelle, toutes deux données pour facultatives (750g)","Un demi-concombre en petits dés ajouté au moment du service (chefsimon)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-138', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('961df29e13fc51acbe12b697e57eb758'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_acidic","scores":{"sweet":1,"salty":3,"acidic":5,"bitter":1,"umami":1,"heat":0,"pungency":2,"richness":2,"freshness":5,"intensity":3},"dominant_flavors":["persil","citron","menthe","huile d''olive"],"aroma_families":["herbes fraîches coupées","agrume","menthe","oignon cru"],"target_textures":["hachis fin et aéré","grain de boulgour tendre","dés de tomate fermes"],"signature_ingredients":["Persil plat frais","Boulgour fin cru","Jus de citron frais","Menthe fraîche"],"identity_guardrails":["Le persil est l''ingrédient principal et non l''herbe d''appoint : 250 g de feuilles contre 45 g de boulgour, cinq fois et demie plus","Le boulgour reste minoritaire et jamais cuit, gonflé à l''eau froide — remplacé en volume par de la semoule de couscous, on obtient le taboulé français, qui est un autre plat","Citron abondant, huile mesurée : sans acidité franche, un hachis d''herbes crues n''a plus de colonne","Hachage au couteau seulement : le persil passé au robot noircit et rend son eau, et la texture du plat est perdue","Rien de cuit, rien de tiède dans le saladier"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Baba ganoush', 'baba ganoush', 'Levant', 'Levant',
     'meal', 'purée d aubergine fumée', 'named_traditional_dish', 'smoky_sweet',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Baba ganoush', 'Purée d''aubergines grillées à la flamme, mélangées au tahini, jus de citron et ail', ds.id, 'REAL-139',
    'Myko', 'editorial', 8, 20, 45, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'ad73acc9adaf87a9226a3ef59df65c4e',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":4,"freshness":2,"intensity":5}'::jsonb, ARRAY['fumé','caramélisé','savoureux']::text[],
    ARRAY['ail','agrume','aubergine_fumée','tahini','citron']::text[], ARRAY['crémeux_avec_fibres_légères']::text[],
    ARRAY['Aubergine fraîche','Tahini','Jus de citron frais','Ail cru']::text[], ARRAY['aubergine_vraiment_fumée','tahini','citron','pas_de_purée_neutre']::text[],
    ARRAY['grillade directe','égouttage','écrasement']::text[], ARRAY[]::text[], ARRAY['sésame']::text[],
    '3 jours au réfrigérateur.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'aubergine fraiche' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Aubergine fraîche', 1000, 'g', 'required',
     'base', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'tahini' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Tahini', 100, 'g', 'required',
     'sauce', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'jus de citron frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Jus de citron frais', 70, 'ml', 'required',
     'acidité', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru', 10, 'g', 'required',
     'aromatique', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'huile d olive vierge extra' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Huile d’olive vierge extra', 50, 'ml', 'required',
     'finition', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'persil frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Persil frais', 20, 'g', 'required',
     'herbe', false, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Brûler ou griller les aubergines entières jusqu’à peau noire et chair effondrée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Égoutter la chair pour retirer l’excès d’eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Écraser avec tahini, citron et ail en gardant une légère texture.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Finir à l’huile et aux herbes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'REAL-139', 'recipe_family', 'Baba ganoush',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'REAL-139', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'REAL-139', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-139', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ad73acc9adaf87a9226a3ef59df65c4e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":4,"freshness":2,"intensity":5},"dominant_flavors":["fumé","caramélisé","savoureux"],"aroma_families":["ail","agrume","aubergine_fumée","tahini","citron"],"target_textures":["crémeux_avec_fibres_légères"],"signature_ingredients":["Aubergine fraîche","Tahini","Jus de citron frais","Ail cru"],"identity_guardrails":["aubergine_vraiment_fumée","tahini","citron","pas_de_purée_neutre"]}'::jsonb, 'myko_v3_sensory_contract')
