    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-141', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('ebd8c89e988d2bde7c8d6cb4c4a2edc1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":3,"pungency":3,"richness":4,"freshness":2,"intensity":5},"dominant_flavors":["épices chaudes","aromatique","profond"],"aroma_families":["oignon_compoté","piment","cannelle","agneau","boulgour","pignon"],"target_textures":["croûte_ferme","cœur_juteux","grains_fins"],"signature_ingredients":["Boulgour fin cru","Agneau haché cru","Oignon jaune cru","Pignon de pin"],"identity_guardrails":["boulgour_et_agneau_pétris","farce_centrale","découpe_losanges"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
