  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mettre les pruneaux dénoyautés à gonfler dans de l''eau chaude — non bouillante, juste frémissante — pendant une demi-heure. Le trempage à l''eau détend leur peau sans la crever et les tient entiers dans la sauce : trop court, ils resteraient secs au cœur ; à l''eau bouillante, ils se déferaient avant même d''entrer dans la cocotte. Les égoutter en réservant l''eau de trempage, qui a pris le goût du fruit et servira à mouiller la cocotte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Compter 1,5 kg d''épaule d''agneau avec os pour obtenir les 1,1 kg de chair déclarés : l''os et les parures en pèsent près du tiers. Demander qu''elle soit détaillée en morceaux de la taille d''un gros abricot, os compris — ce sont eux qui donneront du corps à la sauce. Éponger les morceaux et les laisser vingt minutes à température ambiante : une viande sortie du froid refroidit la cocotte et rend son eau au lieu de colorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Mélanger dans un bol la cannelle moulue, le gingembre, le cumin, le poivre, la moitié du sel et le safran écrasé entre les doigts. En frotter les morceaux d''agneau sur toutes leurs faces et les laisser prendre l''odeur le temps d''émincer les oignons. Frotter les épices sur la viande crue plutôt que les jeter dans le liquide les met en contact du gras, qui seul les dissout : sinon la sauce garde ce goût de poudre en suspension qu''on ne rattrape plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Chauffer l''huile d''olive dans un faitout à fond épais et y colorer l''agneau sur toutes ses faces, en deux fournées pour ne pas encombrer le fond — entassés, les morceaux rendent leur eau et bouillent au lieu de dorer. Les réserver, puis faire fondre les oignons émincés dans la graisse restante, dix minutes à feu moyen, en grattant les sucs attachés qui se dissolvent dans leur jus. Ajouter l''ail haché sur la dernière minute, pour qu''il ne brûle pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre la viande dans le faitout avec le bâton de cannelle, mouiller à mi-hauteur de l''eau de trempage des pruneaux complétée d''eau fraîche si nécessaire, et porter à petits frémissements. Couvrir et cuire une heure et demie à feu très doux, en retournant les morceaux deux ou trois fois. La viande est prête quand elle se détache de l''os sans résistance mais tient encore en morceaux : un tajine se sert en pièces entières, il ne s''effiloche pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter les pruneaux égouttés et le miel, puis poursuivre vingt à vingt-cinq minutes à découvert. Le liquide doit réduire jusqu''à napper le dos de la cuillère et prendre une brillance sombre : c''est ce glaçage qui fait le sucré-salé du plat, et il ne s''obtient que couvercle ôté. Remuer en secouant le faitout par les poignées plutôt qu''à la cuillère, pour ne pas crever les pruneaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pendant cette réduction, faire dorer les amandes mondées à sec dans une poêle, à feu moyen, en les remuant sans cesse jusqu''à ce qu''elles blondissent et sentent le grillé ; deux minutes de trop et elles deviennent amères. Les réserver, puis torréfier le sésame dans la même poêle une minute à peine, jusqu''au premier crépitement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Goûter la sauce et finir de saler : elle doit être franchement sucrée mais tenue par le sel, le poivre et le gras de l''agneau, sinon le plat glisse vers le dessert. Laisser reposer dix minutes hors du feu, retirer le bâton de cannelle, puis parsemer amandes et sésame au dernier moment seulement — posés plus tôt, ils boivent la sauce, ramollissent et ne servent plus à rien. Servir avec une semoule ou un pain pour éponger le jus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'REAL-143', 'recipe_family', 'Tajine d’agneau aux pruneaux',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'REAL-143', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Aux fruits secs plutôt qu''aux pruneaux : 600 g d''abricots secs et 250 g de dattes pour six, avec ras el-hanout, gousse de vanille fendue et deux piments de Cayenne émiettés (marmiton)','Sucré au sucre semoule, cinq cuillerées à soupe pour huit, plutôt qu''au miel (marmiton)','En souris d''agneau entières, avec deux poires Williams, du jus et du zeste d''orange à la place du miel (750g)','Curcuma en plus du safran, une demi-cuillerée à café pour six (750g)','Coriandre fraîche ciselée au service, une dizaine de branches (marmiton)','Gingembre frais râpé, 15 g, à la place du gingembre moulu (marmiton)','Sésame en quantité, 100 g de graines pour quatre, servi avec une semoule de couscous grain moyen (750g)','Pruneaux gonflés dans un thé noir léger plutôt que dans de l''eau chaude : le tanin raffermit la peau et empêche le pruneau de se défaire dans la sauce, son amertume légère répondant au miel (marmiton source 1 ; 750g source 5 utilise un thé parfumé)']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"REAL-143","variants":["Aux fruits secs plutôt qu''aux pruneaux : 600 g d''abricots secs et 250 g de dattes pour six, avec ras el-hanout, gousse de vanille fendue et deux piments de Cayenne émiettés (marmiton)","Sucré au sucre semoule, cinq cuillerées à soupe pour huit, plutôt qu''au miel (marmiton)","En souris d''agneau entières, avec deux poires Williams, du jus et du zeste d''orange à la place du miel (750g)","Curcuma en plus du safran, une demi-cuillerée à café pour six (750g)","Coriandre fraîche ciselée au service, une dizaine de branches (marmiton)","Gingembre frais râpé, 15 g, à la place du gingembre moulu (marmiton)","Sésame en quantité, 100 g de graines pour quatre, servi avec une semoule de couscous grain moyen (750g)","Pruneaux gonflés dans un thé noir léger plutôt que dans de l''eau chaude : le tanin raffermit la peau et empêche le pruneau de se défaire dans la sauce, son amertume légère répondant au miel (marmiton source 1 ; 750g source 5 utilise un thé parfumé)"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-143', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('abd693e73edd8097798b12e7d0431d18'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"sweet_spiced","scores":{"sweet":5,"salty":2,"acidic":1,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":1,"intensity":4},"dominant_flavors":["pruneau","miel","cannelle","agneau braisé"],"aroma_families":["cannelle","oignon compoté","fruit sec cuit","agneau mijoté","amande grillée"],"target_textures":["viande qui se détache de l''os","pruneaux gonflés entiers","sauce nappante et brillante","amandes croquantes"],"signature_ingredients":["Épaule d’agneau crue","Pruneau dénoyauté","Miel","Cannelle moulue"],"identity_guardrails":["Sans pruneaux, ce n''est plus ce tajine : remplacés par des abricots secs ou des dattes, on obtient un plat voisin de la même famille et non une variante de celui-ci","Le sucré est assumé mais tenu par le sel, le poivre et le gras de l''agneau — un tajine seulement sucré tombe au dessert","La réduction se fait à découvert en fin de cuisson : sans ce glaçage, la sauce reste un jus et le plat perd sa brillance","L''agneau se sert en morceaux entiers détachables à la cuillère, jamais effiloché ni haché","Amandes et sésame arrivent grillés au dernier moment : incorporés à la cuisson, ils ramollissent et n''apportent plus rien"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Harira', 'harira', 'Maroc', 'Maroc',
     'meal', 'soupe complète', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Harira', 'Soupe de lentilles, pois chiches, tomates, céleri, coriandre et vermicelles fins', ds.id, 'REAL-144',
    'Myko', 'editorial', 8, 35, 90, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '6ad272fe93949086e39e27c3ca41d322',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":3,"pungency":3,"richness":4,"freshness":2,"intensity":5}'::jsonb, ARRAY['épices chaudes','aromatique','profond']::text[],
    ARRAY['oignon_compoté','tomate_cuite','coriandre','gingembre','cannelle','tomate','céleri']::text[], ARRAY['soupe_nappante','légumineuses_tendres','vermicelles']::text[],
    ARRAY['Lentille brune sèche, crue','Pois chiche cuit, égoutté','Agneau cru en petits dés','Tomate concassée en conserve']::text[], ARRAY['liaison_farinaire','herbes_abondantes','lentilles_pois_chiches']::text[],
    ARRAY['suer','mijotage','liaison','cuisson des vermicelles']::text[], ARRAY[]::text[], ARRAY['céleri','gluten']::text[],
    '3 jours au réfrigérateur.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
