  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-155', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('23d30b2858eba2c555fe18cfadcbe364'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"nutty_savory","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":2,"pungency":2,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["oléagineux","toasté","savoureux"],"aroma_families":["oignon_compoté","tomate_cuite","piment","arachide","tomate","bœuf"],"target_textures":["sauce_onctueuse","viande_fondante","légumes_entiers"],"signature_ingredients":["Bœuf à braiser cru","Pâte d’arachide pure","Tomate concentrée","Patate douce crue, épluchée"],"identity_guardrails":["pâte_arachide_non_sucrée","sauce_épaisse","légumes_séquencés"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
