  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-199', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f5e415364d8f163cbff3842f548c0e63'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"brothy_umami","scores":{"sweet":1,"salty":4,"acidic":1,"bitter":1,"umami":5,"heat":1,"pungency":2,"richness":2,"freshness":3,"intensity":4},"dominant_flavors":["bouillon","umami","aromatique"],"aroma_families":["ail","gingembre","soja_fermenté","porc","shaoxing","chou"],"target_textures":["boulette_très_tendre","châtaigne_croquante","bouillon_léger"],"signature_ingredients":["Porc haché cru gras","Châtaigne d’eau","Œuf cru","Fécule de maïs"],"identity_guardrails":["très_grosses_boulettes","braisage","châtaigne_d_eau"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
