  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:REAL-247', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('4d8a21a69f436c3c62d409322f96f769'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":3,"pungency":3,"richness":4,"freshness":2,"intensity":5},"dominant_flavors":["épices chaudes","aromatique","profond"],"aroma_families":["oignon_compoté","coco","cannelle","cardamome","tamarin","cacahuète"],"target_textures":["bœuf_fondant","pommes_de_terre_tendres","sauce_épaisse"],"signature_ingredients":["Bœuf à braiser cru","Lait de coco","Pâte de curry massaman","Pomme de terre crue, épluchée"],"identity_guardrails":["curry_doux_épices_chaudes","tamarin","cacahuète"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
