DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pabellón criollo', 'pabellon criollo', 'Venezuela', 'Venezuela',
     'meal', 'assiette bœuf haricots riz', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pabellón criollo', 'Bœuf effiloché en sofrito, haricots noirs, riz blanc et tranches de plantain frites, servis ensemble', ds.id, 'REAL-287',
    'Myko', 'editorial', 6, 40, 150, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'df53931e10bf648905b37d1ae247f62e',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":1,"pungency":2,"richness":3,"freshness":2,"intensity":4}'::jsonb, ARRAY['bœuf effiloché','tomate et poivron confits','haricot noir','plantain caramélisé']::text[],
    ARRAY['sofrito','oignon compoté','tomate cuite','cumin','banane frite']::text[], ARRAY['filaments de viande en sauce courte','haricots crémeux','riz détaché','plantain fondant à bords croustillants']::text[],
    ARRAY['Bœuf à braiser cru','Haricot noir sec','Riz long blanc cru','Banane plantain mûre']::text[], ARRAY['Quatre éléments dressés séparément — riz, haricots noirs, bœuf effiloché, plantain frit : mélangés en un seul appareil, ce n''est plus un pabellón','Le bœuf se poche puis s''effiloche à la main ; du bœuf haché ou taillé en cubes ne fait pas la carne mechada','Les plantains doivent être mûrs à peau noircie : verts et farineux, ils ne donnent pas le sucre qui répond aux haricots','Aucun autre haricot ne remplace le haricot noir dans ce plat, c''est lui qui fait le noir du drapeau','Le riz reste blanc et neutre, sans sofrito ni tomate : il sépare les trois autres éléments au lieu de se mêler à eux']::text[],
    ARRAY['trempage des légumineuses','pochage','effilochage à la main','sofrito','riz à l''étouffée','friture des plantains','dressage en quartiers']::text[], ARRAY['Version végétale : le bœuf effiloché remplacé par 400 g de fruit du jacquier en saumure égoutté, effiloché de même, relevé de paprika fumé, de piment en poudre et de sauce sriracha (chefsimon)','Câpres égouttées ajoutées à la viande en sauce (marmiton)','Un poireau émincé dans le sofrito, avec les oignons (marmiton)','Riz safrané plutôt que blanc, cuit avec une pointe de safran et une noix de beurre (marmiton)','Bœuf poché au bouillon cube plutôt qu''à l''eau aromatisée, deux cubes pour six (marmiton)','Plantains poudrés d''un voile de fécule avant friture, pour une croûte plus sèche (chefsimon)','Une pincée de cumin sur les plantains à la sortie du bain de friture (chefsimon)']::text[], ARRAY[]::text[],
    'Chaque élément se garde 3 jours au réfrigérateur dans son propre récipient : réunis, le riz absorbe le jus des haricots et durcit. La viande en sauce et les haricots se congèlent 3 mois et gagnent même au repos ; le riz cuit se congèle mal et les plantains frits pas du tout, ils ressortent mous. Réchauffer viande et haricots à la casserole avec une cuillerée d''eau, le riz à la vapeur ou couvert au four avec un filet d''eau, et frire les plantains le jour même du service.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
