     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Chicken paprikash', 'Cuisses de poulet cuites avec des oignons dans une sauce paprika doux hongrois liée à la crème aigre', ds.id, 'REAL-296',
    'Myko', 'editorial', 6, 25, 70, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '11fa0a167679a55d831cfbf89d013a48',
    '{"sweet":1,"salty":3,"acidic":4,"bitter":0,"umami":3,"heat":2,"pungency":2,"richness":4,"freshness":3,"intensity":4}'::jsonb, ARRAY['acidulé','crémeux','épices']::text[],
