  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Rincer les lentilles corail à l''eau claire jusqu''à ce qu''elle sorte limpide. Les couvrir de trois fois leur volume d''eau avec le curcuma et une pincée de sel.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Porter à frémissement, écumer, puis cuire 18 à 20 minutes à découvert : les lentilles doivent se défaire en une purée fluide, encore coulante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, tailler le cabillaud en gros tronçons, les saler légèrement et les laisser 10 minutes au frais avec la moitié du jus de citron.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire chauffer l''huile de colza dans une petite poêle, y jeter les graines de cumin : dès qu''elles crépitent et embaument, ajouter l''oignon émincé, le gingembre et l''ail hachés. Faire blondir 5 minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter la tomate concassée grossièrement et le piment en poudre, laisser compoter 4 minutes, puis verser ce tadka dans les lentilles. Mélanger.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Incorporer les épinards au dal encore chaud : ils tombent en une minute. Rectifier en sel et poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Poser les tronçons de cabillaud dans un panier vapeur au-dessus du dal frémissant, couvrir et cuire 7 à 9 minutes, jusqu''à 55–58 °C à cœur : la chair se sépare en lamelles nacrées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Dresser le dal en creux, poser le poisson dessus, arroser du reste de jus de citron et couvrir de coriandre ciselée.');

