  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:PROT-001', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2a80157eeacfb7490533ce6d3ab500af'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":2,"pungency":3,"richness":2,"freshness":4,"intensity":4},"dominant_flavors":["épices chaudes","agrume","végétal"],"aroma_families":["cumin_grillé","gingembre","ail","coriandre_fraîche","agrume"],"target_textures":["poisson_lamellé","dal_fluide","épinard_fondant"],"signature_ingredients":["Dos de cabillaud cru","Lentille corail sèche, crue","Épinard frais","Cumin en graines"],"identity_guardrails":["poisson_cuit_vapeur_jamais_bouilli","tadka_indispensable","dal_reste_le_feculent_du_plat","pas_de_creme_ni_de_lait_de_coco"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
