     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Morue et pois chiches au four à la portugaise', 'Morue dessalée et pois chiches rôtis au four avec épinards, tomates et huile d''olive', ds.id, 'PROT-002',
    'Myko', 'editorial', 2, 25, 45, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '2df4ddda4062f060fd7455c342b90b61',
    '{"sweet":2,"salty":4,"acidic":3,"bitter":1,"umami":5,"heat":1,"pungency":2,"richness":3,"freshness":3,"intensity":4}'::jsonb, ARRAY['iodé','fumé','olive']::text[],
    ARRAY['morue_dessalée','paprika_fumé','ail','laurier','huile_d_olive']::text[], ARRAY['morue_en_pétales','pois_chiche_fondant','épinard_fondant']::text[],
    ARRAY['Morue salée sèche','Pois chiche sec, cru','Huile d''olive vierge extra','Paprika fumé']::text[], ARRAY['dessalage_long_obligatoire','pois_chiche_unique_feculent','huile_ajoutee_a_cru','pas_de_creme']::text[],
    ARRAY['dessalage','trempage','pochage doux','cuisson au four','assaisonnement à cru']::text[], ARRAY['Version froide en salada de bacalhau com grão','Œuf dur émietté au service','Haricot blanc à la place du pois chiche']::text[], ARRAY['poisson']::text[],
    '3 jours au réfrigérateur, encore meilleur le lendemain à température ambiante. Ne pas congeler après dessalage.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
