  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:PROT-002', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2df4ddda4062f060fd7455c342b90b61'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"smoky_sweet","scores":{"sweet":2,"salty":4,"acidic":3,"bitter":1,"umami":5,"heat":1,"pungency":2,"richness":3,"freshness":3,"intensity":4},"dominant_flavors":["iodé","fumé","olive"],"aroma_families":["morue_dessalée","paprika_fumé","ail","laurier","huile_d_olive"],"target_textures":["morue_en_pétales","pois_chiche_fondant","épinard_fondant"],"signature_ingredients":["Morue salée sèche","Pois chiche sec, cru","Huile d''olive vierge extra","Paprika fumé"],"identity_guardrails":["dessalage_long_obligatoire","pois_chiche_unique_feculent","huile_ajoutee_a_cru","pas_de_creme"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
