  VALUES (v_version, 2, 'Découper le poulet en huit morceaux, le frotter au paprika fumé, au piment, au poivre et au sel, et le laisser reposer 30 minutes à température ambiante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Égoutter les haricots, les couvrir d’eau fraîche avec le laurier et une branche de thym, porter à ébullition franche 10 minutes puis laisser cuire 50 minutes à petit bouillon ; saler à mi-cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une cocotte allant au four, faire suer à sec l’oignon, le poivron et le céleri taillés en petits dés (la « sainte trinité ») jusqu’à ce qu’ils rendent leur eau, puis ajouter l’ail et les tomates pelées écrasées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les haricots égouttés avec une louche de leur cuisson, poser les morceaux de poulet peau vers le haut sur ce lit et enfourner à 200 °C, à découvert, 40 minutes : la peau caramélise pendant que les haricots absorbent le jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Sortir la cocotte, effeuiller le reste du thym sur le plat et laisser reposer 10 minutes avant de servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'PROT-008', 'recipe_family', 'Poulet rôti à la créole et haricots rouges',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'PROT-008', 'missing_required_count', v_missing), 'open');
  END IF;

