  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Détailler le jarret en gros tronçons de 4–5 cm en gardant les os. Éponger soigneusement la viande : une surface humide ne colore pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Chauffer une cocotte en fonte à vide jusqu''à ce qu''une goutte d''eau y danse. Saisir les morceaux à sec, en deux fournées, 4 minutes par face sans les bouger : le jarret relâche assez de gras pour dorer seul. Réserver.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Jeter l''oignon émincé dans la graisse rendue, gratter les sucs, ajouter l''ail écrasé et le thym, cuire 3 minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Déglacer au vin blanc, laisser réduire de moitié, puis remettre la viande et les os. Ajouter l''eau, le laurier, couvrir et braiser à 150 °C pendant 1 h 45.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter les lentilles vertes rincées (elles doivent être immergées ; compléter d''un peu d''eau chaude si besoin) et poursuivre 35 à 40 minutes à couvert, jusqu''à ce qu''elles soient tendres mais entières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Poêler les champignons émincés à sec dans une poêle très chaude jusqu''à évaporation complète de leur eau et coloration, puis les verser dans la cocotte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer les os. Délayer la moutarde dans une louche de jus chaud (jamais en plein bouillon, elle tournerait amère) et la reverser dans la cocotte hors du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Ajouter les épinards par poignées : ils tombent en 2 minutes dans le jus brûlant. Réveiller au vinaigre de vin rouge, poivrer, saler seulement à ce moment, parsemer de persil et servir.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'PROT-009', 'recipe_family', 'Jarret de bœuf braisé aux lentilles vertes et aux épinards, moutarde et thym',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'PROT-009', 'missing_required_count', v_missing), 'open');
  END IF;

