  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Lentilles corail à la place des vertes pour une texture plus liée','Chou frisé à la place des épinards','Version cocotte-minute : 45 min sous pression puis 15 min lentilles']::text[]) AS variant(name);

