  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:PROT-009', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f4befa1a0ef097a5c3d7b8906711e72c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"earthy_herbal","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":5,"heat":0,"pungency":3,"richness":3,"freshness":2,"intensity":4},"dominant_flavors":["umami","terreux","rôti","herbacé"],"aroma_families":["bœuf","oignon_compoté","thym","laurier","moutarde","champignon_terreux"],"target_textures":["viande_fondante","légumes_tendres","sauce_courte"],"signature_ingredients":["Jarret de bœuf cru, avec os","Lentille verte sèche, crue","Moutarde de Dijon","Épinard frais"],"identity_guardrails":["conserver_les_ingrédients_signatures","conserver_la_technique_centrale","ne_pas_remplacer_par_un_simple_équivalent_nutritionnel","cuisson_longue","pas_de_crème","lentilles_cuites_dans_le_braisage"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
