     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poule au pot farcie', 'Poule entière pochée longuement avec une farce de pain de mie, lait, jambon et persil', ds.id, 'SRC-001',
    'Myko', 'editorial', 6, 45, 180, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '6c1b1504414ecbd4736466a346894f8b',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":0,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1}'::jsonb, ARRAY['bouillon_de_volaille','légumes_racines','farce_au_jambon']::text[],
    ARRAY['volaille_pochée','légume_bouilli','muscade']::text[], ARRAY['chair_fondante','bouillon_clair','farce_moelleuse']::text[],
    ARRAY['Poule crue','Pain de mie','Clou de girofle']::text[], ARRAY['Le bouillon reste clair : on écume et on ne laisse jamais bouillir.','La poule est farcie — sans farce, c''est un pot-au-feu de volaille, pas une poule au pot.']::text[],
    ARRAY['pochage','farce','écumage','cuisson longue']::text[], ARRAY['Sans farce, en pot-au-feu de volaille','Avec chou vert blanchi à part']::text[], ARRAY['gluten','œuf','lait']::text[],
    'Le bouillon se garde 4 jours au froid et se congèle. La poule se conserve 3 jours immergée dans son bouillon, jamais à sec.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
