  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Mélanger cette mie avec le jambon détaillé en petits dés, les œufs battus, l''ail et le persil hachés, la muscade. Saler modérément : le jambon apporte déjà du sel.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Garnir l''intérieur de la poule de cette farce, coudre l''ouverture et brider la volaille pour qu''elle garde sa forme pendant les trois heures de cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Déposer la poule dans une grande marmite, couvrir largement d''eau froide et porter lentement à frémissement. Écumer soigneusement pendant le premier quart d''heure : c''est ce qui donne un bouillon clair.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter l''oignon piqué des clous de girofle, le céleri, le poivre en grains et le sel. Laisser frémir à découvert deux heures, sans jamais laisser bouillir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter les carottes et les navets taillés en gros tronçons, puis les poireaux ficelés en botte trente minutes plus tard. Poursuivre jusqu''à ce que la cuisse se détache sans résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Servir le bouillon d''abord, puis la poule découpée et sa farce en tranches, entourée des légumes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
