     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Paupiettes de veau sauce tomate', 'Escalopes de veau roulées autour d''une farce au porc haché, braisées dans une sauce tomate', ds.id, 'SRC-005',
    'Myko', 'editorial', 4, 20, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a75be19b8a1433ef02738f9068258abb',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":1,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1}'::jsonb, ARRAY['tomate_cuite','veau_moelleux','champignon']::text[],
    ARRAY['tomate_cuite','oignon_compoté','vin_blanc']::text[], ARRAY['chair_moelleuse','sauce_nappante','champignon_fondant']::text[],
    ARRAY['Escalope de veau crue fine','Tomate fraîche mûre','Champignon de Paris frais']::text[], ARRAY['La paupiette est roulée et ficelée : sans farce à l''intérieur, ce n''est qu''une escalope roulée.','Vingt minutes de mijotage suffisent — au-delà le veau se dessèche.']::text[],
    ARRAY['farce','saisie','mijotage','déglaçage']::text[], ARRAY['Avec tomates concassées en conserve hors saison','Sans farce, en simple roulé de veau']::text[], ARRAY[]::text[],
    'Se garde 3 jours au froid, se réchauffe doucement dans sa sauce. Se congèle 2 mois.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
