  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-005', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a75be19b8a1433ef02738f9068258abb'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":1,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1},"dominant_flavors":["tomate_cuite","veau_moelleux","champignon"],"aroma_families":["tomate_cuite","oignon_compoté","vin_blanc"],"target_textures":["chair_moelleuse","sauce_nappante","champignon_fondant"],"signature_ingredients":["Escalope de veau crue fine","Tomate fraîche mûre","Champignon de Paris frais"],"identity_guardrails":["La paupiette est roulée et ficelée : sans farce à l''intérieur, ce n''est qu''une escalope roulée.","Vingt minutes de mijotage suffisent — au-delà le veau se dessèche."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
