DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouchées à la reine', 'bouchees a la reine', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Bouchées à la reine', 'Bouchées feuilletées garnies d''une fricassée de poulet et veau dans une sauce liée avec champignons', ds.id, 'SRC-009',
    'Myko', 'editorial', 6, 30, 90, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '090554455be4e7af376dc734699418ac',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['volaille','champignon','crème','vin blanc']::text[],
    ARRAY['beurré','lacté','épicé doux','champignon']::text[], ARRAY['sauce nappante','viande fondante','lamelles de champignon tendres']::text[],
    ARRAY['Champignon de Paris frais','Escalope de veau crue fine','Bouillon de volaille','Jaune d''œuf cru']::text[], ARRAY['Sans la liaison finale au Jaune d''œuf cru et à la Crème fraîche liquide entière, le velouté retombe au rang de simple béchamel et le plat perd son caractère de sauce à la reine.','Retirer le Champignon de Paris frais ou la volaille pochée vide la garniture de sa substance : ce sont les deux éléments présents dans presque toutes les sources du dossier.','Le bouillon de volaille doit être celui du pochage des viandes, pas de l''eau salée : c''est lui qui porte tout l''umami de la sauce.','La sauce ne doit jamais bouillir après l''ajout des jaunes, sous peine de grainer irrémédiablement.']::text[],
    ARRAY['pochage','mijotage','réduction','liaison']::text[], ARRAY['Version aux fruits de mer inspirée de chefsimon.com : remplacer les viandes par du Pavé de saumon cru, sans peau taillé en cubes et poché 3 minutes dans le velouté en fin de cuisson, avec un zeste de citron et un peu d''estragon dans la sauce.','Version alsacienne de fête : augmenter la part de viandes, ajouter des quenelles coupées en tronçons au moment de réunir la garniture, et servir avec des spätzle.','Version apéritive d''après 750g.com : garnir des mini-bouchées de champignons de Paris crémés, parsemer de fromage râpé et gratiner 8 à 15 minutes à 170 °C.','Version express : sauter les viandes déjà cuites au lieu de les pocher et monter le velouté directement sur du bouillon de volaille reconstitué, en 20 minutes chrono.']::text[], ARRAY['gluten','lait','œuf','sulfites']::text[],
    'Se garde 2 jours au réfrigérateur à 4 °C dans une boîte hermétique, la garniture bien refroidie avant fermeture. Réchauffer à feu très doux ou au bain-marie en remuant, sans jamais laisser frémir. La congélation est déconseillée : la liaison jaune d''œuf et crème tranche à la décongélation et les champignons relâchent leur eau.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
