  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler la carotte et l''oignon jaune, les couper en gros tronçons. Détailler le poulet en quatre morceaux et l''installer avec les légumes dans une cocotte juste assez large pour les contenir. Verser le bouillon de volaille, amener à frémissement puis couvrir et laisser cuire 45 minutes à tout petits bouillons, en retournant les morceaux à mi-parcours.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Glisser l''escalope de veau crue fine dans le bouillon pour les 10 dernières minutes seulement : elle doit rester moelleuse et perdre juste son cru. Sortir toutes les viandes, les laisser tiédir sur une planche, puis filtrer le bouillon au chinois. En prélever 600 g pour la sauce et garder le reste au chaud pour détendre la garniture si besoin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer la peau du poulet, désosser la chair et la tailler en cubes d''environ 1,5 cm. Détailler le veau de la même façon. Réunir les deux viandes dans un saladier et couvrir d''un film pour qu''elles ne sèchent pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Nettoyer les champignons de Paris frais en grattant le chapeau et en coupant le bout terreux du pied, puis les émincer en lamelles épaisses. Les faire sauter à feu vif dans une noisette du beurre doux jusqu''à ce que l''eau rendue se soit entièrement évaporée et que les lamelles commencent à dorer. Réserver hors du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Dans une casserole à fond épais, fondre le reste du beurre doux à feu doux, pluvioriser la farine de blé T55 d''un coup et remuer au fouet pendant 3 minutes : le mélange doit mousser sans jamais prendre couleur, on veut un roux blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Retirer la casserole du feu et verser le bouillon chaud en filet, fouet en main, pour éviter tout grumeau. Ajouter le vin blanc sec puis le lait entier, remettre sur feu moyen et laisser réduire 15 minutes en fouettant régulièrement, jusqu''à ce que le velouté nappe le dos d''une cuillère. Assaisonner de poivre noir moulu et de muscade moulue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Verser les cubes de viande et les champignons réservés dans le velouté, baisser au minimum et laisser les saveurs se lier 5 minutes sans que la sauce reprenne l''ébullition.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Battre les jaunes d''œuf cru avec la crème fraîche liquide entière dans un bol, détendre cet appareil avec une louche de sauce brûlante, puis le reverser dans la casserole hors du feu en mélangeant. Réchauffer 2 à 3 minutes à feu très doux : la sauce épaissit et prend du brillant, mais un seul bouillon ferait grainer les jaunes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Servir sans attendre, la garniture bien chaude répartie dans des croûtes feuilletées passées quelques minutes au four, ou nappée sur du riz, des nouilles ou des spätzle. Le surplus de sauce se présente à part en saucière.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-009', 'recipe_family', 'Bouchées à la reine',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-009', 'missing_required_count', v_missing), 'open');
  END IF;

