  CROSS JOIN unnest(ARRAY['Version aux fruits de mer inspirée de chefsimon.com : remplacer les viandes par du Pavé de saumon cru, sans peau taillé en cubes et poché 3 minutes dans le velouté en fin de cuisson, avec un zeste de citron et un peu d''estragon dans la sauce.','Version alsacienne de fête : augmenter la part de viandes, ajouter des quenelles coupées en tronçons au moment de réunir la garniture, et servir avec des spätzle.','Version apéritive d''après 750g.com : garnir des mini-bouchées de champignons de Paris crémés, parsemer de fromage râpé et gratiner 8 à 15 minutes à 170 °C.','Version express : sauter les viandes déjà cuites au lieu de les pocher et monter le velouté directement sur du bouillon de volaille reconstitué, en 20 minutes chrono.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-009","variants":["Version aux fruits de mer inspirée de chefsimon.com : remplacer les viandes par du Pavé de saumon cru, sans peau taillé en cubes et poché 3 minutes dans le velouté en fin de cuisson, avec un zeste de citron et un peu d''estragon dans la sauce.","Version alsacienne de fête : augmenter la part de viandes, ajouter des quenelles coupées en tronçons au moment de réunir la garniture, et servir avec des spätzle.","Version apéritive d''après 750g.com : garnir des mini-bouchées de champignons de Paris crémés, parsemer de fromage râpé et gratiner 8 à 15 minutes à 170 °C.","Version express : sauter les viandes déjà cuites au lieu de les pocher et monter le velouté directement sur du bouillon de volaille reconstitué, en 20 minutes chrono."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-009', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('090554455be4e7af376dc734699418ac'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3},"dominant_flavors":["volaille","champignon","crème","vin blanc"],"aroma_families":["beurré","lacté","épicé doux","champignon"],"target_textures":["sauce nappante","viande fondante","lamelles de champignon tendres"],"signature_ingredients":["Champignon de Paris frais","Escalope de veau crue fine","Bouillon de volaille","Jaune d''œuf cru"],"identity_guardrails":["Sans la liaison finale au Jaune d''œuf cru et à la Crème fraîche liquide entière, le velouté retombe au rang de simple béchamel et le plat perd son caractère de sauce à la reine.","Retirer le Champignon de Paris frais ou la volaille pochée vide la garniture de sa substance : ce sont les deux éléments présents dans presque toutes les sources du dossier.","Le bouillon de volaille doit être celui du pochage des viandes, pas de l''eau salée : c''est lui qui porte tout l''umami de la sauce.","La sauce ne doit jamais bouillir après l''ajout des jaunes, sous peine de grainer irrémédiablement."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Courgettes farcies', 'courgettes farcies', 'France', 'France',
     'meal', 'plat au four', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Courgettes farcies', 'Courgettes évidées farcies d''un mélange de porc et bœuf haché à la tomate, cuites au four', ds.id, 'SRC-010',
    'Myko', 'editorial', 4, 20, 50, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a27ae3042de3418aad6d130e09c797b3',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['viande rôtie','tomate','ail']::text[],
    ARRAY['alliacé','herbacé','épicé doux']::text[], ARRAY['légume fondant','farce moelleuse','dessus doré']::text[],
    ARRAY['Courgette fraîche','Porc haché cru','Bœuf haché cru 15 % MG']::text[], ARRAY['La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.','La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.','La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat.']::text[],
    ARRAY['saisie','rôtissage']::text[], ARRAY['Version au poisson relevée dans le dossier : remplacer les viandes par de la chair de brochet crue, avec une pointe de jus de citron frais.','Version orientale : accentuer le cumin moulu, ajouter de la coriandre fraîche ciselée et un filet de jus de citron frais au moment de servir.','Avec des courgettes rondes : décalotter, évider, blanchir dix minutes à l''eau bouillante avant de garnir, puis remettre le chapeau pour la cuisson au four.','Sauce plus fraîche : troquer la tomate entière pelée en conserve contre de la tomate râpée étalée dans le fond du plat.']::text[], ARRAY[]::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un plat couvert, et se réchauffe 15 minutes à 160 °C plutôt qu''au micro-ondes pour que la barquette ne s''affaisse pas. La congélation de la farce seule tient 2 mois à -18 °C ; en revanche les courgettes garnies supportent mal le gel, elles rendent leur eau et deviennent flasques à la décongélation.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
