  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-010', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a27ae3042de3418aad6d130e09c797b3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["viande rôtie","tomate","ail"],"aroma_families":["alliacé","herbacé","épicé doux"],"target_textures":["légume fondant","farce moelleuse","dessus doré"],"signature_ingredients":["Courgette fraîche","Porc haché cru","Bœuf haché cru 15 % MG"],"identity_guardrails":["La courgette évidée doit rester le contenant du plat : farce servie à part ou légume coupé en dés, ce ne sont plus des courgettes farcies.","La farce est à base de viande hachée liée à la pulpe de courgette récupérée ; sans cette pulpe réincorporée, le plat perd le lien végétal qui le caractérise.","La cuisson se fait au four dans un plat, garniture apparente : cuire à couvert en cocotte comme un mijoté change la nature du plat."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Croque-madame', 'croque madame', 'France', 'France',
     'meal', 'sandwich chaud', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Croque-madame', 'Pain de mie fourré au jambon et emmental, gratiné, surmonté d''un œuf', ds.id, 'SRC-011',
    'Myko', 'editorial', 4, 15, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', '1ec73aff7b20d2db1bddd045d8c3eff0',
    '{"sweet":1,"salty":4,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":0,"intensity":3}'::jsonb, ARRAY['fromage fondu','jambon sale','beurre dore']::text[],
    ARRAY['lactee','grillee','beurree']::text[], ARRAY['pain grille croustillant','coeur fondant','jaune coulant']::text[],
    ARRAY['Pain de mie','Œuf cru','Jambon blanc cuit','Emmental râpé']::text[], ARRAY['Sans l''oeuf pose sur le dessus, le plat redevient un croque-monsieur et perd son nom.','Le pain de mie est la seule enveloppe admise : remplace par une baguette ou un pain de campagne, ce n''est plus un croque.','Le couple jambon blanc cuit et fromage fondu forme le coeur du plat ; retirer l''un des deux le denature.']::text[],
    ARRAY['saisie','gratinage']::text[], ARRAY['Version integralement au four : monter les croques beurres, enfourner a 210 degres pendant quinze minutes, puis coiffer chacun d''un oeuf au plat cuit a part.','Version a l''oeuf encastre : decouper un disque au centre de la tranche superieure avant cuisson, retourner le croque a mi-cuisson et casser l''oeuf directement dans l''ouverture.','Version jaune ferme : prolonger la cuisson de l''oeuf de deux minutes a couvert, pour un croque qui se mange a la main sans couler.']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se mange immediatement, le jaune coulant ne supportant pas l''attente. Un croque deja garni se garde au maximum 24 heures a 4 degres au refrigerateur et se rechauffe dix minutes a 180 degres, l''oeuf devenant alors ferme. La congelation ne convient qu''au croque monte cru et non garni d''oeuf, jusqu''a un mois a -18 degres, a cuire sans decongelation prealable.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
