BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de brocolis', 'gratin de brocolis', 'France', 'France',
     'meal', 'gratin de légumes', 'domestic_standard', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gratin de brocolis', 'Bouquets de brocolis blanchis nappés d''une sauce béchamel crémeuse, gratinés au four', ds.id, 'SRC-012',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '7e52d50367c9e6edea86885cb40842b1',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté','fromagé','végétal vert']::text[],
    ARRAY['lacté','alliacé','épicé doux']::text[], ARRAY['fondant','croûte gratinée croustillante','appareil pris']::text[],
    ARRAY['Brocoli cru','Lait entier','Gruyère râpé']::text[], ARRAY['Sans brocoli, le plat n''existe plus : c''est lui qui donne le nom, la couleur et la légère amertume végétale du gratin.','Sans liaison lactée à base de lait entier et de farine, on obtient des bouquets gratinés et non un gratin : la béchamel est ce qui lie le légume.','Sans couverture de gruyère râpé et de chapelure, il manque la croûte dorée qui définit le gratinage.','Le brocoli doit rester ferme et bien égoutté : trop cuit ou détrempé, il délave la sauce et fait rendre de l''eau au plat.']::text[],
    ARRAY['blanchiment','gratinage','réduction']::text[], ARRAY['Version végétarienne : retirer le jambon blanc cuit et compenser en portant le gruyère râpé à 120 g pour garder du corps à l''appareil.','Version allégée : supprimer la crème fraîche liquide entière et compléter avec 150 ml de lait entier supplémentaire, quitte à cuire la béchamel deux minutes de plus.','Croûte renforcée : doubler la chapelure de blé et l''arroser d''un filet d''huile d''olive vierge extra avant d''enfourner.','Sans œuf : omettre l''œuf cru et augmenter la farine de blé T55 à 50 g, ce qui donne un gratin plus coulant et moins compact.']::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C, dans le plat filmé ou en boîte hermétique une fois refroidi à cœur. Réchauffer 15 à 20 minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : l''appareil aux œufs et à la crème se dissocie en rendant de l''eau à la décongélation et le brocoli devient filandreux ; si on y tient, congeler avant cuisson au four, jusqu''à 1 mois à -18 °C, et enfourner sans décongeler en ajoutant 20 minutes.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
