  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version végétarienne : retirer le jambon blanc cuit et compenser en portant le gruyère râpé à 120 g pour garder du corps à l''appareil.','Version allégée : supprimer la crème fraîche liquide entière et compléter avec 150 ml de lait entier supplémentaire, quitte à cuire la béchamel deux minutes de plus.','Croûte renforcée : doubler la chapelure de blé et l''arroser d''un filet d''huile d''olive vierge extra avant d''enfourner.','Sans œuf : omettre l''œuf cru et augmenter la farine de blé T55 à 50 g, ce qui donne un gratin plus coulant et moins compact.']::text[]) AS variant(name);

