  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Remplacer l''œuf mollet par des lardons rissolés jusqu''au croustillant, égouttés de leur gras et parsemés tièdes sur les lentilles.','Version plus copieuse : effilocher un jambonneau cuit à l''eau pendant une heure avec oignon et carotte, et l''incorporer aux lentilles avant la vinaigrette.','Substituer le vinaigre de vin rouge par du vinaigre de cidre, plus doux, en augmentant légèrement la dose.','Ajouter des dés de patate douce rôtis au four et des dés de betterave cuite pour une salade plus sucrée et plus colorée.','Faire fondre le poireau à la poêle avec un peu d''huile et de thym au lieu de le cuire avec les lentilles, pour un goût plus confit.','Troquer les noix contre des noisettes torréfiées à sec.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-014","variants":["Remplacer l''œuf mollet par des lardons rissolés jusqu''au croustillant, égouttés de leur gras et parsemés tièdes sur les lentilles.","Version plus copieuse : effilocher un jambonneau cuit à l''eau pendant une heure avec oignon et carotte, et l''incorporer aux lentilles avant la vinaigrette.","Substituer le vinaigre de vin rouge par du vinaigre de cidre, plus doux, en augmentant légèrement la dose.","Ajouter des dés de patate douce rôtis au four et des dés de betterave cuite pour une salade plus sucrée et plus colorée.","Faire fondre le poireau à la poêle avec un peu d''huile et de thym au lieu de le cuire avec les lentilles, pour un goût plus confit.","Troquer les noix contre des noisettes torréfiées à sec."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-014', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1c2fa1080ab372de7025a1383fad03b7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["terreux","acidulé","herbacé","alliacé"],"aroma_families":["herbacé","aromates séchés","alliacé"],"target_textures":["lentilles fondantes mais entières","jaune d''œuf coulant","éclats de noix croquants","oignon cru croquant"],"signature_ingredients":["Lentille corail sèche, crue","Huile d''olive vierge extra","Vinaigre de vin rouge","Persil frais"],"identity_guardrails":["Les lentilles doivent être assaisonnées encore tièdes : une fois froides elles n''absorbent plus la vinaigrette et le plat bascule en salade froide banale.","L''eau de cuisson reste non salée jusqu''à la fin, sinon la peau durcit et le grain ne s''attendrit plus uniformément.","La garniture aromatique carotte-poireau-oignon cuite avec la légumineuse et le duo thym-laurier constituent la base commune à toutes les sources : les retirer viderait le plat de son fond de goût.","La vinaigrette doit rester une émulsion huile d''olive et vinaigre franchement acide ; adoucie ou crémée, le contraste avec la lentille disparaît."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Œufs mimosa', 'oeufs mimosa', 'France', 'France',
     'meal', 'entrée froide', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Œufs mimosa', 'Œufs durs farcis d''un mélange de jaunes tamisés avec mayonnaise et moutarde', ds.id, 'SRC-015',
    'Myko', 'editorial', 4, 25, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', 'edae4e4b8ae7e048f394c06a11829519',
    '{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":2}'::jsonb, ARRAY['jaune d''œuf cuit','mayonnaise','moutarde']::text[],
    ARRAY['œuf cuit','moutardé','herbacé']::text[], ARRAY['blanc ferme et lisse','farce crémeuse','poudre sèche de jaune tamisé']::text[],
    ARRAY['Œuf cru','Mayonnaise','Moutarde de Dijon']::text[], ARRAY['La finition en jaune dur tamisé saupoudré sur le dessus est ce qui fait le mimosa : sans elle, le plat n''est qu''un œuf dur garni.','Les demi-blancs doivent rester entiers et servir de contenant ; hachés ou mixés, on bascule sur une salade d''œufs.','La liaison est une mayonnaise froide montée à l''huile, jamais une sauce cuite ni une crème chaude.','Le plat se sert froid, après passage au réfrigérateur ; tiède, la farce se délite et l''identité se perd.']::text[],
    ARRAY['pochage','émulsion','tamisage']::text[], ARRAY['Œufs mimosa au thon : émietter le thon au naturel en conserve, égoutté et l''incorporer à la farce de jaunes avant de garnir les blancs.','Montage en verrine : n''utiliser que les jaunes, les mixer avec la mayonnaise et le thon jusqu''à une crème lisse, dresser en verrines et saupoudrer de jaunes tamisés.','Farce à l''avocat : remplacer la mayonnaise par de la chair d''avocat écrasée avec les jaunes, du jus de citron frais, sel et poivre, dressée à la poche à douille cannelée.','Œufs mimosa frits : paner les demi-blancs (farine, œuf battu, chapelure), les frire une à deux minutes en huile chaude, puis les garnir de la farce mimosa au moment de servir.']::text[], ARRAY['œuf','moutarde','poisson']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C, à plat, filmé sans contact avec la farce ; les œufs durs entiers non écalés tiennent jusqu''à trois jours. La congélation est à exclure : le blanc cuit devient caoutchouteux et la mayonnaise tranche à la décongélation. La variante au thon se consomme dans les 12 heures.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

