  SELECT
    v_family, 3, 'Pâtes au thon et à la tomate', 'Petites pâtes avec thon en conserve et sauce tomate réduite à l''ail', ds.id, 'SRC-018',
    'Myko', 'editorial', 4, 10, 25, 'facile',
