  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-023', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3eb8aee51a9d443a6fbb855cfc9828d8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":2,"freshness":1,"intensity":2},"dominant_flavors":["salé","umami","douceur végétale"],"aroma_families":["alliacé","grillé","céréalier"],"target_textures":["grains détachés","moelleux","lanières fondantes"],"signature_ingredients":["Riz cru","Œuf cru","Jambon blanc cuit","Petit pois surgelé"],"identity_guardrails":["L''œuf doit être cuit à part en omelette fine puis retaillé en lanières : des œufs brouillés directement dans le riz donnent un autre plat.","Le riz doit être cuit à l''avance et refroidi avant d''être sauté ; un riz encore chaud colle et fait perdre la texture en grains détachés qui définit le plat.","Le trio riz, œuf et petit pois est présent dans les sept sources du dossier : retirer l''un des trois fait sortir de l''identité du riz cantonais.","Le sauté se fait sur feu vif et court, jamais en mijotage : le plat n''est pas un riz cuisiné en sauce."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade de riz niçoise', 'salade de riz nicoise', 'France', 'France',
     'meal', 'salade composée', 'named_traditional_dish', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade de riz niçoise', 'Riz froid avec thon, œufs, tomates et poivron vert en vinaigrette', ds.id, 'SRC-024',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', '33064d002835e8e21a1fa32d9aab851e',
    '{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2}'::jsonb, ARRAY['tomate','huile d''olive','poivron vert']::text[],
    ARRAY['végétal','fruité']::text[], ARRAY['grains de riz détachés','dés de poivron croquants','enrobage huileux léger']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Riz cru','Huile d''olive vierge extra']::text[], ARRAY['Sans thon ni œuf dur, ce n''est plus une salade niçoise mais une salade de riz aux crudités.','Le riz est refroidi avant d''être assaisonné : tiède, il boit l''huile et devient pâteux.','Les légumes restent crus et taillés à la main ; cuits, la salade perd son mordant.']::text[],
    ARRAY['pochage','marinade','émulsion']::text[], ARRAY['Remplacer un tiers du riz blanc par du riz complet pour un grain plus mordant, en allongeant la cuisson de cinq à sept minutes.','Plonger les dés de poivron vert une minute dans l''eau bouillante puis les refroidir aussitôt, pour une version plus digeste tout en gardant du croquant.','Servir le riz encore tiède simplement arrosé de l''assaisonnement à la tomate, en accompagnement d''un poisson grillé.']::text[], ARRAY['poisson','œuf']::text[],
