  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Sauce maison : monter une mayonnaise au jaune d''œuf, à la moutarde de Dijon et à l''huile d''olive vierge extra, puis la détendre au vinaigre plutôt que d''utiliser une mayonnaise du commerce.','Version allégée : remplacer une partie de la mayonnaise par de la crème fraîche liquide entière relevée de moutarde, pour une sauce plus fluide et moins riche.','Sans porc : substituer au jambon blanc des blancs de volaille cuits taillés en dés, comme le proposent certaines sources du dossier.','Version végétarienne : supprimer le jambon et doubler la part d''œuf dur, en renforçant le croquant avec davantage de cornichons.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-025","variants":["Sauce maison : monter une mayonnaise au jaune d''œuf, à la moutarde de Dijon et à l''huile d''olive vierge extra, puis la détendre au vinaigre plutôt que d''utiliser une mayonnaise du commerce.","Version allégée : remplacer une partie de la mayonnaise par de la crème fraîche liquide entière relevée de moutarde, pour une sauce plus fluide et moins riche.","Sans porc : substituer au jambon blanc des blancs de volaille cuits taillés en dés, comme le proposent certaines sources du dossier.","Version végétarienne : supprimer le jambon et doubler la part d''œuf dur, en renforçant le croquant avec davantage de cornichons."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-025', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('952decfa71f25586ab8c8bf3b7c94411'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":0,"umami":2,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["acidulé","salé","moutardé","crémeux"],"aroma_families":["vinaigré","herbacé","végétal frais"],"target_textures":["fondant","croquant","crémeux"],"signature_ingredients":["Pomme de terre cuite","Mayonnaise","Cornichon au vinaigre","Œuf dur"],"identity_guardrails":["Sans dés de pomme de terre cuite refroidis, ce n''est plus une salade piémontaise mais une simple salade de crudités.","La sauce doit rester à dominante mayonnaise : remplacée par une vinaigrette seule, le plat perd son onctuosité caractéristique.","L''acidité vive apportée par les cornichons et le vinaigre est constitutive du plat ; sans elle, l''ensemble devient plat et gras.","Le plat se sert froid après repos au réfrigérateur : servi tiède, il n''est pas reconnaissable."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
