      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version corse : doubler les lardons fumés et allonger le mijotage à deux heures pour une sauce plus courte et plus fumée.','Version au citron : ajouter des rondelles de citron avec les olives et réduire la cuisson à trente minutes en utilisant des tranches fines de veau plutôt que des cubes.','Version tout-en-un : glisser des pommes de terre en quartiers en même temps que les olives, ce qui fait passer le plat en rôle complet.','Version sans alcool : remplacer le vin blanc par la même quantité d''eau et une pointe supplémentaire de concentré de tomate.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-027","variants":["Version corse : doubler les lardons fumés et allonger le mijotage à deux heures pour une sauce plus courte et plus fumée.","Version au citron : ajouter des rondelles de citron avec les olives et réduire la cuisson à trente minutes en utilisant des tranches fines de veau plutôt que des cubes.","Version tout-en-un : glisser des pommes de terre en quartiers en même temps que les olives, ce qui fait passer le plat en rôle complet.","Version sans alcool : remplacer le vin blanc par la même quantité d''eau et une pointe supplémentaire de concentré de tomate."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-027', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('424ef2bdf06472dbbef01849b0a4cba0'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["olive saumurée","veau braisé","ail fondu","vin blanc réduit"],"aroma_families":["herbacé méditerranéen","oignon compoté","tomate concentrée"],"target_textures":["viande fondante","sauce nappante","olive charnue"],"signature_ingredients":["Épaule de veau crue","Olive verte dénoyautée","Olive noire"],"identity_guardrails":["Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.","Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.","La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
