  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, couvrir largement d''eau froide les haricots blancs secs et, si vous les utilisez, les haricots rouges secs. Les egoutter et les rincer au moment de cuisiner : sans ce trempage, ils resteraient fermes apres une heure de bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Detailler les carottes et l''oignon en des reguliers d''un demi-centimetre, les courgettes en batonnets courts, les pommes de terre en cubes un peu plus gros. Effiler les haricots verts et les casser en deux. Plonger les tomates dix secondes dans l''eau bouillante, les depouiller, retirer les pepins et hacher la chair, que l''on reserve a part pour le pistou.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans un grand faitout, faire tiedir un cinquieme de l''huile d''olive et y laisser suer l''oignon, la carotte et la courgette a feu doux cinq minutes, sans coloration : on cherche a reveiller les sucres des legumes, pas a les rissoler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mouiller avec l''eau froide, ajouter les haricots secs egouttes, porter a fremissement et ecumer la mousse grise qui monte. Laisser mijoter a couvert quarante minutes, en salant seulement a mi-parcours pour ne pas durcir la peau des legumineuses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer les des de pomme de terre et les haricots verts, poursuivre un quart d''heure, puis jeter les pates courtes dans le bouillon frissonnant pour les dix a douze dernieres minutes. Rectifier en sel fin et en poivre noir moulu : le bouillon doit rester juste couvrant, epaissi par l''amidon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, monter le pistou. Degermer les gousses d''ail et les reduire en puree au mortier avec une pincee de sel, ajouter les feuilles de basilic et piler jusqu''a obtenir une pate vert sombre. Travailler le parmesan rape dedans, puis verser le reste de l''huile d''olive en mince filet sans cesser de tourner, comme pour une mayonnaise, jusqu''a une pommade brillante. Finir en melangeant la pulpe de tomate hachee.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le faitout du feu avant d''y delayer le pistou : au-dela du fremissement, le basilic noircit et l''emulsion se rompt. Couvrir et laisser les aromes se diffuser dix a quinze minutes, puis servir avec le gruyere rape presente a part.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-029', 'recipe_family', 'Soupe au pistou',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-029', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Pistou sans tomate, monte seulement a l''ail, au basilic, au parmesan et a l''huile d''olive, comme dans la version la plus depouillee du dossier.','Remplacer le parmesan du pistou par du gruyere rape, ou partager la quantite entre les deux fromages.','Utiliser de la tomate rapee incorporee directement au bouillon plutot que de la tomate fraiche pelee.','Supprimer les pates courtes et augmenter la part de pomme de terre pour une soupe plus rustique et sans gluten.','Ajouter les haricots rouges secs aux haricots blancs pour une version deux legumineuses, plus dense et plus coloree.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-029","variants":["Pistou sans tomate, monte seulement a l''ail, au basilic, au parmesan et a l''huile d''olive, comme dans la version la plus depouillee du dossier.","Remplacer le parmesan du pistou par du gruyere rape, ou partager la quantite entre les deux fromages.","Utiliser de la tomate rapee incorporee directement au bouillon plutot que de la tomate fraiche pelee.","Supprimer les pates courtes et augmenter la part de pomme de terre pour une soupe plus rustique et sans gluten.","Ajouter les haricots rouges secs aux haricots blancs pour une version deux legumineuses, plus dense et plus coloree."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-029', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('fcc4d258c4ad3ccb63addc0f10f8a01c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_herbal","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":3,"richness":3,"freshness":4,"intensity":3},"dominant_flavors":["basilic","ail","légumes mijotés","fromage affiné"],"aroma_families":["herbacé","alliacé","végétal","huile d''olive"],"target_textures":["bouillon lié par l''amidon","légumes fondants en dés","pistou onctueux et émulsionné"],"signature_ingredients":["Basilic frais","Ail cru","Huile d''olive vierge extra","Haricot blanc sec"],"identity_guardrails":["Le pistou est incorporé hors du feu, jamais bouilli : c''est ce qui garde l''arôme de basilic cru intact.","Le basilic doit être frais et pilé avec l''ail cru et l''huile d''olive ; un basilic séché ou une sauce cuite fait perdre son nom au plat.","La garniture repose sur les haricots (blancs secs et verts) avec courgette et pomme de terre, cuits à l''eau sans bouillon de viande."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tapenade noire', 'tapenade noire', 'France', 'France',
     'meal', 'condiment', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Tapenade noire', 'Condiment d''olives noires dénoyautées mixées avec ail et huile d''olive', ds.id, 'SRC-030',
    'Myko', 'editorial', 4, 15, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f5450d8d0633a94b540ad0651f219c04',
