DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Boudin noir aux pommes', 'boudin noir aux pommes', 'France', 'France',
     'meal', 'plat sauté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Boudin noir aux pommes', 'Boudin noir poêlé avec des pommes et oignons sautés au beurre', ds.id, 'SRC-032',
    'Myko', 'editorial', 4, 25, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e8899dd085c384b9bb67334258be5cce',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['caramélisé','sucré','profond','beurré']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['protéine_fondante','tendre','contraste_léger']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.','La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.','Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['saisie','sauté','suer']::text[], ARRAY['Tourte feuilletée : compote de pomme, tronçons de blanc de poireau et rondelles de boudin sans peau entre deux abaisses, dorées à l''œuf, 35 min à 210 °C (750g.com).','Version tatin : quartiers de pomme beurrés et rondelles de boudin recouverts de pâte feuilletée piquée, 30 min à 200 °C (marmiton.org).','Assiette complète : purée de pomme de terre et oignons confits au miel servis avec le boudin poêlé (marmiton.org).','Poêlée de rattes en rondelles avec dés de pomme et raisins secs, boudin doré à part et ajouté au dernier moment (750g.com).','Pommes entières évidées, passées au four puis garnies du hachis de boudin grillé et d''oignons fondus (750g.com).','Flambage au calvados sur les pommes caramélisées, ou mousse froide de boudin et de pomme montée en verrine (chefsimon.com).']::text[], ARRAY['lait']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
