BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Calamars à l''armoricaine', 'calamars a l armoricaine', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Calamars à l''armoricaine', 'Calamars flambés au cognac et mijotés dans une sauce tomate au vin blanc', ds.id, 'SRC-034',
    'Myko', 'editorial', 4, 25, 55, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '8323fccfc3ac8a243d3a5a462c4b8960',
    '{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":2,"pungency":2,"richness":3,"freshness":1,"intensity":4}'::jsonb, ARRAY['tomate concentrée','iodé','ail','vin blanc']::text[],
    ARRAY['marin','alliacé','vineux','eau-de-vie']::text[], ARRAY['anneaux tendres sous la dent','sauce nappante','oignons fondus']::text[],
    ARRAY['Calamar cru nettoyé','Cognac','Concentré de tomate','Vin blanc sec']::text[], ARRAY['Sans calamar, il n''y a plus de plat : c''est le mollusque, et non un poisson ou une autre chair, qui porte l''identité.','Le flambage au Cognac est constitutif de l''armoricaine ; le supprimer donne un simple calamar à la tomate.','La base doit rester tomate et vin blanc : une liaison crémeuse dominante bascule vers une autre recette.','La cuisson est longue et frémissante ; un passage rapide à la poêle laisse une chair caoutchouteuse et sort du registre du plat mijoté.']::text[],
    ARRAY['saisie','flambage','déglaçage','mijotage','réduction']::text[], ARRAY['Sans crème ni persil, à la façon des versions marmiton.org les plus dépouillées : la sauce reste franchement tomatée et se réduit un peu plus longtemps à découvert.','Corser la sauce en fin de cuisson avec un fond de bisque de crustacés, comme le suggèrent deux des pages consultées, en réduisant d''autant le vin blanc.','Remplacer le Cognac par un whisky, variante explicitement proposée par une source, pour une note plus fumée que fruitée.','Version crème et safran de 750g.com : champignons de Paris avec les échalotes, cuisson courte, liaison à la crème et quelques pistils de safran à la place de la tomate.']::text[], ARRAY['mollusques','sulfites','lait']::text[],
    'Se garde deux à trois jours au réfrigérateur à 4 °C dans un contenant hermétique, et gagne même à être préparé la veille. Réchauffer à feu très doux, sans ébullition, sous peine de raidir les calamars. La congélation est possible un mois mais dégrade nettement la texture du mollusque : mieux vaut congeler la sauce seule et cuire les calamars au moment.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

