    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Sans crème ni persil, à la façon des versions marmiton.org les plus dépouillées : la sauce reste franchement tomatée et se réduit un peu plus longtemps à découvert.','Corser la sauce en fin de cuisson avec un fond de bisque de crustacés, comme le suggèrent deux des pages consultées, en réduisant d''autant le vin blanc.','Remplacer le Cognac par un whisky, variante explicitement proposée par une source, pour une note plus fumée que fruitée.','Version crème et safran de 750g.com : champignons de Paris avec les échalotes, cuisson courte, liaison à la crème et quelques pistils de safran à la place de la tomate.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-034","variants":["Sans crème ni persil, à la façon des versions marmiton.org les plus dépouillées : la sauce reste franchement tomatée et se réduit un peu plus longtemps à découvert.","Corser la sauce en fin de cuisson avec un fond de bisque de crustacés, comme le suggèrent deux des pages consultées, en réduisant d''autant le vin blanc.","Remplacer le Cognac par un whisky, variante explicitement proposée par une source, pour une note plus fumée que fruitée.","Version crème et safran de 750g.com : champignons de Paris avec les échalotes, cuisson courte, liaison à la crème et quelques pistils de safran à la place de la tomate."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-034', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('8323fccfc3ac8a243d3a5a462c4b8960'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":2,"pungency":2,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["tomate concentrée","iodé","ail","vin blanc"],"aroma_families":["marin","alliacé","vineux","eau-de-vie"],"target_textures":["anneaux tendres sous la dent","sauce nappante","oignons fondus"],"signature_ingredients":["Calamar cru nettoyé","Cognac","Concentré de tomate","Vin blanc sec"],"identity_guardrails":["Sans calamar, il n''y a plus de plat : c''est le mollusque, et non un poisson ou une autre chair, qui porte l''identité.","Le flambage au Cognac est constitutif de l''armoricaine ; le supprimer donne un simple calamar à la tomate.","La base doit rester tomate et vin blanc : une liaison crémeuse dominante bascule vers une autre recette.","La cuisson est longue et frémissante ; un passage rapide à la poêle laisse une chair caoutchouteuse et sort du registre du plat mijoté."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
