  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-035', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('faae6d2725360f5be291fcf3de2a826c'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":3,"salty":2,"acidic":4,"bitter":0,"umami":1,"heat":0,"pungency":2,"richness":2,"freshness":5,"intensity":2},"dominant_flavors":["sucré végétal de la carotte crue","acidité vinaigrée","jus d''agrume"],"aroma_families":["agrume","épices chaudes","végétal frais"],"target_textures":["croquant filamenteux","juteux","moelleux des raisins regonflés"],"signature_ingredients":["Carotte crue","Orange fraîche","Moutarde de Dijon"],"identity_guardrails":["La carotte reste crue et râpée : dès qu''elle est cuite, le plat cesse d''être des carottes râpées","L''assaisonnement est une vinaigrette acidulée montée à la moutarde, jamais une sauce crémeuse ou mayonnaise","Le jus d''agrume frais vient épauler le vinaigre, il ne le remplace pas par un sirop sucré","La râpe à gros trous fait la texture : une carotte réduite en purée ou en fins cheveux d''ange n''a plus le croquant attendu"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Cassoulet', 'cassoulet', 'France', 'France',
     'meal', 'plat mijoté', 'named_traditional_dish', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Cassoulet', 'Haricots blancs mijotés longuement avec confit de canard, saucisse de Toulouse et poitrine de porc', ds.id, 'SRC-036',
    'Myko', 'editorial', 8, 45, 240, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'e3dbafe3803bd7918f1bfc05e3644ad3',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":0,"intensity":4}'::jsonb, ARRAY['gras de canard confit','porc rissolé','haricot fondant','ail cuit']::text[],
    ARRAY['carné rôti','herbacé sec','aillé','graisse fondue']::text[], ARRAY['haricot fondant à peau intacte','croûte de chapelure cassante','viande confite qui s''effiloche']::text[],
    ARRAY['Haricot blanc sec','Confit de canard cuit','Saucisse de Toulouse crue','Poitrine de porc crue']::text[], ARRAY['Sans haricot blanc sec trempé et cuit à part dans un bouillon de couenne, ce n''est plus un cassoulet mais un ragoût de charcuterie.','Le confit de canard et la saucisse de Toulouse portent l''identité toulousaine du plat : les remplacer par une viande maigre le fait basculer ailleurs.','La cuisson longue au four à découvert, avec la croûte enfoncée plusieurs fois, est constitutive : un mijotage à couvert sur le feu donne un autre plat.','Aucun liant à la farine ni crème : l''onctuosité vient de l''amidon des haricots et de la graisse de confit.']::text[],
    ARRAY['mijotage','saisie','blanchiment','rôtissage']::text[], ARRAY['Version de Castelnaudary : uniquement porc, couenne et confit de canard, sans agneau ni tomate.','Version sans chapelure : on se contente d''enfoncer sept fois la croûte de haricots au cours de la cuisson au four.','Ajout de Saucisse de Montbéliard pour une note fumée, à la place ou en complément de la saucisse de Toulouse.','Cuisson en deux jours : trois heures de four la veille, refroidissement complet, puis une heure de reprise avant le service.']::text[], ARRAY['gluten','sulfites']::text[],
    'Se conserve 4 jours au réfrigérateur entre 0 et 4 °C, dans son plat couvert d''un film ; il gagne au réchauffage lent à 150 °C avec une louche de bouillon. Congélation possible 3 mois pour les haricots et les viandes, mais la croûte de chapelure ne la supporte pas : la refaire au four après décongélation complète au réfrigérateur.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
