  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir à l''achat environ 1,3 kg de bulbes entiers avec leurs tiges et leurs plumets : c''est ce qu''il faut pour arriver aux 900 g de fenouil paré indiqués dans la liste. Sectionner les tiges à ras du bulbe, réserver quelques plumets pour la finition, et supprimer la côte extérieure dès qu''elle paraît fibreuse au toucher.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Raccourcir la base terreuse au couteau sans creuser le cœur : c''est lui qui empêchera les morceaux de se défaire pendant la cuisson. Fendre chaque bulbe en deux dans la hauteur, puis recouper en quartiers de deux à trois centimètres d''épaisseur selon la taille du légume, et les citronner aussitôt pour qu''ils ne noircissent pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffer l''huile d''olive et le beurre ensemble dans une cocotte assez large pour recevoir tous les quartiers sur une seule couche. Y jeter l''oignon finement émincé et le laisser s''attendrir cinq minutes à feu modéré, jusqu''à ce qu''il perde son opacité, sans lui laisser prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Coucher les quartiers de fenouil sur leur face tranchée, bien à plat contre le fond, et les laisser dorer sans y toucher cinq à six minutes. Les retourner pour colorer l''autre face, puis glisser l''ail écrasé entre les morceaux au tout dernier moment afin qu''il parfume sans amertume.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le vin blanc sur le fond brûlant et gratter les sucs à la spatule ; laisser bouillonner une minute pour chasser l''alcool. Mouiller ensuite avec l''eau, qui doit monter à mi-hauteur des quartiers, éparpiller le thym et le sucre, puis assaisonner de sel et de poivre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Poser le couvercle et maintenir un frémissement paresseux pendant une trentaine de minutes, en retournant les quartiers une fois à mi-cuisson pour qu''ils s''imprègnent des deux côtés. Le fenouil est prêt quand la pointe d''un couteau traverse le cœur sans résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le couvercle et pousser le feu quelques minutes : le jus doit se resserrer jusqu''à napper les quartiers d''un sirop léger et brillant. Rectifier l''assaisonnement, disperser les plumets réservés et servir sans attendre, la sauce cuillérée par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-040', 'recipe_family', 'Fenouil braisé',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-040', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['À la provençale : remplacer une partie de l''eau par du jus de tomate et ajouter une lanière de zeste d''orange dans le liquide de braisage.','Départ blanchi, façon 750g.com : plonger les demi-bulbes cinq minutes dans une eau bouillante salée et les égoutter avant de les colorer, pour un cœur encore plus fondant.','Sans alcool : supprimer le vin blanc sec, compenser par la même quantité d''eau et doubler le jus de citron frais en fin de réduction.','Tout à l''huile d''olive : retirer le beurre et monter à 40 g d''huile, pour une version maigre et une conservation plus longue au froid.']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-040","variants":["À la provençale : remplacer une partie de l''eau par du jus de tomate et ajouter une lanière de zeste d''orange dans le liquide de braisage.","Départ blanchi, façon 750g.com : plonger les demi-bulbes cinq minutes dans une eau bouillante salée et les égoutter avant de les colorer, pour un cœur encore plus fondant.","Sans alcool : supprimer le vin blanc sec, compenser par la même quantité d''eau et doubler le jus de citron frais en fin de réduction.","Tout à l''huile d''olive : retirer le beurre et monter à 40 g d''huile, pour une version maigre et une conservation plus longue au froid."]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-040', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('486af3145c19697b80adf9b5c7236910'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":1,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":2},"dominant_flavors":["anisé","citronné","sucré végétal"],"aroma_families":["anisée","agrume","herbacée"],"target_textures":["fondant","légèrement confit","jus sirupeux"],"signature_ingredients":["Fenouil frais","Vin blanc sec","Jus de citron frais"],"identity_guardrails":["Le fenouil doit être braisé en quartiers gardant leur cœur : émincé finement, il devient une fondue de fenouil et perd l''identité du plat.","La cuisson se fait à couvert dans un liquide court puis réduit ; rôti à sec au four, le résultat n''est plus un braisé.","L''acidité du vin blanc et du citron est structurante : sans elle le plat vire au légume sucré et l''amertume du bulbe ressort."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de chou-fleur', 'gratin de chou fleur', 'France', 'France',
     'meal', 'gratin', 'named_traditional_dish', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gratin de chou-fleur', 'Bouquets de chou-fleur blanchis gratinés dans une béchamel crémeuse au gruyère', ds.id, 'SRC-041',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c9b3cfa18a880699c71b3195793f02f7',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté crémeux','fromage affiné','légume crucifère doux']::text[],
    ARRAY['lacté','beurré','épices douces']::text[], ARRAY['bouquets fondants','sauce nappante','croûte gratinée']::text[],
    ARRAY['Chou-fleur frais','Gruyère râpé','Lait entier']::text[], ARRAY['Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.','La sauce blanche liée au roux beurre-farine-lait est la colonne vertébrale du plat ; la remplacer par de la crème seule ou par un simple jus de cuisson en change la nature.','La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel.']::text[],
    ARRAY['blanchiment','gratinage']::text[], ARRAY['Version au bouillon, comme sur marmiton : remplacer le lait entier par du bouillon de volaille bien chaud pour une sauce plus légère, et ne garder la crème qu''en filet final.','Version au curry de chefsimon : fouetter une petite cuillerée de curry en poudre dans la béchamel juste avant de napper, en rallongeant d''un peu de lait si la sauce s''épaissit trop.','Version à l''oignon : faire blondir un oignon jaune finement émincé dans le beurre avant d''ajouter la farine, ce qui donne une sauce plus douce et plus sucrée.','Version croquante : parsemer une poignée de noix grossièrement concassées avec le fromage du dessus, à ajouter en fin de cuisson pour qu''elles ne brûlent pas.']::text[], ARRAY['gluten','lait']::text[],
    'Se conserve trois jours au réfrigérateur entre 0 et 4 °C, plat couvert d''un film une fois refroidi. Réchauffer vingt minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : le chou-fleur relâche son eau et la béchamel tranche à la décongélation.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
