  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-041', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c9b3cfa18a880699c71b3195793f02f7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["lacté crémeux","fromage affiné","légume crucifère doux"],"aroma_families":["lacté","beurré","épices douces"],"target_textures":["bouquets fondants","sauce nappante","croûte gratinée"],"signature_ingredients":["Chou-fleur frais","Gruyère râpé","Lait entier"],"identity_guardrails":["Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.","La sauce blanche liée au roux beurre-farine-lait est la colonne vertébrale du plat ; la remplacer par de la crème seule ou par un simple jus de cuisson en change la nature.","La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
