  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version veloutée du dossier : mixer la moitié de la casserole, remonter à la crème et remettre les lardons entiers par-dessus','Avec de la lentille corail, qui se délite en purée en une vingtaine de minutes et donne un plat plus fondant que grainé','Sans crème, simplement lustrée d''un filet d''huile d''olive crue et relevée de persil et d''un tour de moulin']::text[]) AS variant(name);

