     'aromate', false, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'persil frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Persil frais', 60, 'g', 'required',
     'herbe', false, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'celeri branche cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Céleri branche cru', 10, 'g', 'optional',
     'légume aromatique', true, 7);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 1, 'g', 'optional',
     'assaisonnement', true, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Compter 3 kg de moules en coquille chez le poissonnier pour obtenir les 900 g de chair de la recette. Les trier une à une : écarter les coquilles brisées et celles qui restent béantes après une pression du doigt.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Arracher le byssus de chaque moule en tirant vers la charnière, gratter au couteau les concrétions accrochées à la coquille, puis laver en deux eaux froides successives en frottant les moules entre les paumes. Égoutter et réserver au réfrigérateur jusqu''à la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Peler et ciseler finement l''oignon. Écraser les gousses d''ail sous une lame plate puis les hacher. Tailler le céleri en dés minuscules. Laver le persil, l''effeuiller et le hacher grossièrement ; le garder de côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le beurre à feu doux dans une grande marmite. Y laisser fondre l''oignon, l''ail et le céleri pendant 4 à 5 minutes en remuant, sans jamais leur laisser prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mouiller avec le vin blanc, pousser le feu et laisser bouillonner deux minutes à découvert pour évaporer l''alcool et concentrer le parfum du bouillon aromatique.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser toutes les moules d''un seul coup dans le liquide en pleine ébullition, couvrir aussitôt et laisser 5 à 7 minutes à feu vif. Soulever le couvercle deux ou trois fois pour retourner délicatement les coquilles à l''écumoire, sans arracher la chair de sa nacre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu dès que la quasi-totalité des coquilles est ouverte : une minute de trop rétracte et durcit la chair. Retirer les rares moules restées closes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Disperser le persil haché, donner un tour de poivre et mélanger une dernière fois avec précaution. Goûter le jus avant d''ajouter du sel : l''eau de mer rendue par les moules suffit le plus souvent, la pincée prévue ne sert qu''à ajuster.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Servir sans attendre, directement dans la marmite ou réparti en assiettes creuses, en arrosant chaque part de son jus de cuisson brûlant.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-044', 'recipe_family', 'Moules marinières',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-044', 'missing_required_count', v_missing), 'open');
  END IF;

  WITH axis AS (
    INSERT INTO culinary.recipe_variation_axes
      (recipe_family_id, name, selection_mode, required)
    VALUES (v_family, 'Variante culinaire', 'single', false)
    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Marinière liée : saupoudrer une cuillerée de farine sur les aromates fondus avant de mouiller au vin, pour un jus plus nappant','Version crémée : filtrer le jus de cuisson, le faire réduire avec de la crème fraîche puis en napper les moules décoquillées à moitié','Version normande : remplacer le vin blanc par du cidre brut','Moules-frites du Nord : servir avec des frites maison, comme pendant la braderie de Lille']::text[]) AS variant(name);

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_validation', 5,
     ARRAY['source_backed_variant_needs_test'], '{"recipe_code":"SRC-044","variants":["Marinière liée : saupoudrer une cuillerée de farine sur les aromates fondus avant de mouiller au vin, pour un jus plus nappant","Version crémée : filtrer le jus de cuisson, le faire réduire avec de la crème fraîche puis en napper les moules décoquillées à moitié","Version normande : remplacer le vin blanc par du cidre brut","Moules-frites du Nord : servir avec des frites maison, comme pendant la braderie de Lille"]}'::jsonb, 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-044', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('d3e4c7a58566c6b494b8dcdfe16ec882'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":4,"acidic":3,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["iodé","vineux","aillé","beurré"],"aroma_families":["marin","alliacé","herbacé","vineux"],"target_textures":["chair tendre et charnue","jus court et fluide"],"signature_ingredients":["Moule commune crue","Vin blanc sec","Persil frais"],"identity_guardrails":["Sans moules fraîches cuites dans leur coquille, le plat n''existe plus : la chair préparée à part ou décoquillée à l''avance perd le jus qui fait la marinière","Le mouillement doit rester un vin blanc sec : le remplacer par de la crème, du curry ou un fond fait basculer la recette vers les moules à la crème","Le jus ne se sale pas d''avance : l''eau de mer relâchée par les coquillages est l''assaisonnement principal","Le persil s''ajoute cru en fin de cuisson, jamais cuit avec les aromates"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Osso buco', 'osso buco', 'Italie', 'Italie',
     'meal', 'plat mijoté', 'named_traditional_dish', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Osso buco', 'Rondelles de jarret de veau braisées dans une garniture aromatique au vin blanc', ds.id, 'SRC-045',
    'Myko', 'editorial', 4, 25, 90, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '2f4b6083c60b74da3cce2bbbe2e58483',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['veau braisé','tomate cuite longuement','vin blanc réduit','zeste de citron']::text[],
    ARRAY['agrume','aromates séchés','légumes racines fondus']::text[], ARRAY['viande fondante se détachant de l''os','sauce nappante','moelle onctueuse']::text[],
    ARRAY['Jarret de veau cru, en tranches avec os','Vin blanc sec','Tomate entière pelée en conserve','Zeste de citron']::text[], ARRAY['Le veau doit rester en tranches épaisses avec l''os et sa moelle : désossé, ou remplacé par un autre morceau, ce n''est plus un osso buco.','Le mouillement se fait au vin blanc sec et jamais au vin rouge, sinon la sauce vire au ragoût et perd son acidité claire.','La gremolata, persil et ail et zeste de citron hachés, s''ajoute crue au moment de servir : cuite, elle disparaît et le plat perd son relief.','La cuisson est longue, à couvert et à frémissement : un feu vif raccourcit le temps mais laisse la viande ferme et attachée à l''os.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY['Osso buco in bianco : supprimer la tomate pelée et le concentré, allonger au bouillon et au vin, pour la version milanaise historique sans tomate.','Sans farine ni beurre : saisir à l''huile seule et lier la sauce en fin de cuisson par simple réduction à découvert, ce qui retire le gluten et le lait.','Version agrumes et anchois, relevée par une page du dossier : ajouter des quartiers de citron et d''orange lavés et quelques filets d''anchois en cours de mijotage.','Garniture de champignons émincés ajoutés vingt minutes avant la fin, comme le font deux des sources.']::text[], ARRAY['gluten','lait','sulfites','céleri']::text[],
    'Se garde trois jours au réfrigérateur à 4 °C, viande immergée dans sa sauce en boîte hermétique, et gagne à être réchauffée doucement le lendemain. La viande et la sauce se congèlent ensemble jusqu''à trois mois ; la gremolata, elle, ne supporte ni le froid négatif ni l''attente et se refait au moment de servir.', false, '[]'::jsonb,
    NULL, '{}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
