    RETURNING id
  )
  INSERT INTO culinary.recipe_variation_options
    (variation_axis_id, name, confidence_level, status)
  SELECT axis.id, variant.name, 'B', 'candidate'
  FROM axis
  CROSS JOIN unnest(ARRAY['Version alsacienne stricte : supprimer les lardons et râper un peu de muscade dans l''appareil œuf-crème.','Tarte à l''oignon au chèvre : disposer des rondelles de Fromage de chèvre bûche sur la compotée avant de verser l''appareil.','Version méridionale : parfumer la compotée d''Herbes de Provence séderisées — ici, une cuillère d''Herbes de Provence séchées ajoutée en fin de compotée.','Compotée poussée plus loin au miel, étalée seule sur le feuilletage sans appareil œuf-crème, façon tarte fine à servir tiède.']::text[]) AS variant(name);

