  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Couvrir les flageolets d''eau bouillante et les laisser gonfler une heure hors du feu — ce trempage court remplace la nuit entière sans durcir la peau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Les égoutter, les couvrir d''eau froide avec l''oignon entier, le thym et le laurier, porter à frémissement et cuire une heure à petits bouillons. Ne saler qu''en fin de cuisson, le sel précoce raidit la peau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, peler l''ail et le tailler en éclats. Inciser le gigot à intervalles réguliers et glisser un éclat dans chaque fente.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Badigeonner le gigot d''huile d''olive, saler, poivrer, parsemer de thym, puis l''installer sur une grille au-dessus du plat de cuisson, la face la plus charnue tournée vers le fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Enfourner à 220 °C et saisir vingt minutes, puis baisser à 180 °C, retourner le gigot, verser un demi-verre d''eau dans le plat et poursuivre trente à quarante minutes en arrosant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Sortir le gigot et le laisser reposer dix minutes sous une feuille d''aluminium : la chair se détend et le jus se redistribue.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Égoutter les flageolets, les réchauffer avec la tomate concassée égouttée dix minutes à feu doux pour que l''acidité s''arrondisse, les lier au beurre et au jus de rôtissage dégraissé, puis servir le gigot tranché sur ce lit.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-003-D1', 'recipe_family', 'Gigot d''agneau aux flageolets à la tomate',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-003-D1', 'missing_required_count', v_missing), 'open');
  END IF;

