     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-003-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-003-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('4d64a61668acf27caaba272f214c64b8'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":0,"heat":3,"pungency":0,"richness":3,"freshness":5,"intensity":1},"dominant_flavors":["agneau_rôti","ail_confit","haricot_fondant"],"aroma_families":["viande_rôtie","ail","thym"],"target_textures":["croûte_dorée","chair_rosée","haricot_fondant"],"signature_ingredients":["Gigot d''agneau cru","Haricot flageolet sec","Ail cru"],"identity_guardrails":["Le gigot repose avant d''être tranché, sinon le jus part sur la planche.","Les flageolets ne sont pas un accompagnement rapporté : ils finissent dans le jus de rôtissage."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
