     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Veau Marengo à la tomate pelée', 'Veau braisé au vin blanc avec champignons, oignons grelots et tomates pelées en conserve', ds.id, 'SRC-006-D1',
    'Myko', 'editorial', 6, 20, 90, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '51bf1ad2c55f4a05fdd1c9e94809fa74',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":1,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1}'::jsonb, ARRAY['tomate_cuite','veau_moelleux','vin_blanc']::text[],
    ARRAY['tomate_cuite','oignon_compoté','champignon']::text[], ARRAY['viande_fondante','sauce_nappante','champignon_fondant']::text[],
    ARRAY['Épaule de veau crue, en cubes','Champignon de Paris frais','Oignon grelot cru']::text[], ARRAY['Champignons et petits oignons entrent en fin de cuisson : ajoutés au début, ils se défont.','La liaison vient de la farine roussie sur la viande, pas d''un ajout de fécule en fin de course.']::text[],
    ARRAY['saisie','singer','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','lait']::text[],
    'Se garde 3 jours au froid et gagne au réchauffage. Se congèle 3 mois.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-006'), '{"variant_label":"Avec tomates pelées en conserve hors saison","rationale":"La tomate entière pelée en conserve remplace la tomate fraîche quand celle-ci n''a plus de goût. Écrasée à la cuillère dans la cocotte, elle donne la même sauce, un peu plus dense.","operations":[{"op":"substitute","form":"Tomate fraîche mûre","with":"Tomate entière pelée en conserve","quantity":400,"role":"sauce"}],"steps":[{"op":"replace","n":4,"instruction":"Ajouter le concentré de tomate, puis les tomates entières pelées écrasées à la cuillère avec un peu de leur jus, le vin blanc et l''eau à hauteur, enfin le thym et le laurier. Saler et poivrer."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
