  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fondre le beurre dans une cocotte et dorer la viande par fournées, sur toutes les faces. Réserver.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire revenir dans la même cocotte les oignons émincés, l''ail, le céleri et les carottes taillées en rondelles épaisses, cinq minutes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Déglacer au vin blanc et gratter les sucs jusqu''à ce qu''ils se détachent du fond, puis laisser réduire de moitié. On ne singe pas cette version : un jus épaissi se prend en pâte trouble au froid, là où un jus nu se coupe net.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre la viande, mouiller au bouillon à hauteur, ajouter le thym et le laurier, saler et poivrer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et laisser mijoter à feu très doux deux heures trente, jusqu''à ce qu''une fourchette entre sans effort.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le thym et le laurier, puis sortir la viande et les carottes à l''écumoire. Filtrer le jus au chinois, le laisser reposer quelques minutes et le dégraisser à la louche, avant de le réduire à environ six cents millilitres. Rectifier l''assaisonnement franchement, plus haut que pour un plat chaud, puis dissoudre hors du feu la gélatine ramollie dix minutes à l''eau très froide et essorée entre les doigts.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Ranger la viande et les carottes en couches serrées dans une terrine, en parsemant de persil ciselé entre chacune, puis verser le jus tiède jusqu''à les recouvrir. Laisser prendre au réfrigérateur une nuit entière : quelques heures suffisent à figer la surface mais pas le cœur. Démouler en trempant trois secondes le moule dans l''eau chaude, et trancher au couteau à lame fine.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-002-D1', 'recipe_family', 'Bœuf mode en gelée',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-002-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-002-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-002-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1ed8c1f89b0fb7c9a5536ec28177b1f9'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":3,"pungency":0,"richness":2,"freshness":4,"intensity":1},"dominant_flavors":["bœuf_braisé","carotte_fondante","vin_blanc"],"aroma_families":["viande_braisée","oignon_compoté","bouillon_corsé"],"target_textures":["viande_effilochable","sauce_nappante","carotte_fondante"],"signature_ingredients":["Bœuf à braiser cru","Carotte crue","Vin blanc sec"],"identity_guardrails":["Les carottes cuisent avec la viande et deviennent fondantes : les ajouter tard en ferait une garniture, pas un bœuf mode.","La quantité de carottes égale au moins la moitié du poids de viande."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouchées à la reine au saumon', 'bouchees a la reine au saumon', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Bouchées à la reine au saumon', 'Bouchées feuilletées garnies d''une fricassée de saumon et champignons liée', ds.id, 'SRC-009-D1',
    'Myko', 'editorial', 6, 25, 50, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '609be1f41aff72a3ac12d70f043bf493',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['volaille','champignon','crème','vin blanc']::text[],
    ARRAY['beurré','lacté','épicé doux','champignon']::text[], ARRAY['sauce nappante','viande fondante','lamelles de champignon tendres']::text[],
    ARRAY['Champignon de Paris frais','Bouillon de volaille','Jaune d''œuf cru']::text[], ARRAY['Sans la liaison finale au Jaune d''œuf cru et à la Crème fraîche liquide entière, le velouté retombe au rang de simple béchamel et le plat perd son caractère de sauce à la reine.','Retirer le Champignon de Paris frais ou la volaille pochée vide la garniture de sa substance : ce sont les deux éléments présents dans presque toutes les sources du dossier.','Le bouillon de volaille doit être celui du pochage des viandes, pas de l''eau salée : c''est lui qui porte tout l''umami de la sauce.','La sauce ne doit jamais bouillir après l''ajout des jaunes, sous peine de grainer irrémédiablement.']::text[],
    ARRAY['pochage','mijotage','réduction','liaison']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf','sulfites']::text[],
    'Se garde 2 jours au réfrigérateur à 4 °C dans une boîte hermétique, la garniture bien refroidie avant fermeture. Réchauffer à feu très doux ou au bain-marie en remuant, sans jamais laisser frémir. La congélation est déconseillée : la liaison jaune d''œuf et crème tranche à la décongélation et les champignons relâchent leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-009'), '{"variant_label":"Version aux fruits de mer inspirée de chefsimon.com : remplacer les viandes par du Pavé de saumon cru, sans peau taillé en cubes et poché 3 minutes dans le velouté en fin de cuisson, avec un zeste de citron et un peu d''estragon dans la sauce.","rationale":"Le poisson ne se poche pas quarante-cinq minutes : le long pochage des viandes disparaît, et avec lui l''essentiel du temps de cuisson. Le bouillon n''est plus fabriqué par la recette, il est seulement infusé aux légumes, ce qui donne un velouté plus court en goût — c''est le zeste et l''estragon qui compensent. Le saumon ne rejoint la sauce qu''une fois celle-ci liée aux jaunes, trois minutes avant le service : il reste nacré mais ne pardonne pas l''attente, et cette version se sert dans la minute ou ne se sert pas.","operations":[{"op":"substitute","form":"Poulet entier cru","with":"Pavé de saumon cru, sans peau","quantity":600,"unit":"g","role":"protéine"},{"op":"remove","form":"Escalope de veau crue fine"},{"op":"add","form":"Zeste de citron","quantity":4,"unit":"g","role":"aromate","optional":false},{"op":"add","form":"Estragon frais","quantity":6,"unit":"g","role":"aromate","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Peler la carotte et l''oignon jaune, les couper en gros tronçons et les mettre dans une casserole avec le bouillon de volaille. Porter à frémissement, couvrir et laisser infuser vingt minutes, le temps que les légumes donnent au liquide un peu de rondeur. Filtrer au chinois, prélever 600 g pour la sauce et garder le reste au chaud pour détendre la garniture si besoin."},{"op":"remove","n":2},{"op":"replace","n":3,"instruction":"Éponger les pavés de saumon, passer la pince à arêtes sur la ligne médiane, puis les tailler en cubes d''environ 2 cm — un peu plus gros que pour une viande, car le poisson se rétracte à la chaleur. Les réserver au frais sous un film jusqu''au dernier moment."},{"op":"replace","n":6,"instruction":"Retirer la casserole du feu et verser le bouillon chaud en filet, fouet en main, pour éviter tout grumeau. Ajouter le vin blanc sec puis le lait entier, remettre sur feu moyen et laisser réduire 15 minutes en fouettant régulièrement, jusqu''à ce que le velouté nappe le dos d''une cuillère. Assaisonner de poivre noir moulu et de muscade moulue, puis incorporer le zeste de citron et l''estragon frais ciselé : l''un tend une sauce que le poisson ne salera pas, l''autre lui donne son parfum d''anis."},{"op":"replace","n":7,"instruction":"Verser les champignons réservés dans le velouté, baisser au minimum et laisser les saveurs se lier 5 minutes sans que la sauce reprenne l''ébullition. La sauce doit être entièrement terminée avant que le poisson n''y entre : on ne rattrape pas un velouté autour de cubes de saumon sans les défaire."},{"op":"insert","after":7,"instruction":"Garder la sauce liée sur le feu le plus doux, à peine tremblante, et y glisser les cubes de saumon en une seule couche. Compter trois minutes sans jamais remuer, puis couvrir et retirer du feu : ils achèvent de cuire dans la chaleur du velouté et restent nacrés au cœur. Un fouet à ce stade défait les cubes et fait grainer les jaunes."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
