  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler la carotte et l''oignon jaune, les couper en gros tronçons et les mettre dans une casserole avec le bouillon de volaille. Porter à frémissement, couvrir et laisser infuser vingt minutes, le temps que les légumes donnent au liquide un peu de rondeur. Filtrer au chinois, prélever 600 g pour la sauce et garder le reste au chaud pour détendre la garniture si besoin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Éponger les pavés de saumon, passer la pince à arêtes sur la ligne médiane, puis les tailler en cubes d''environ 2 cm — un peu plus gros que pour une viande, car le poisson se rétracte à la chaleur. Les réserver au frais sous un film jusqu''au dernier moment.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Nettoyer les champignons de Paris frais en grattant le chapeau et en coupant le bout terreux du pied, puis les émincer en lamelles épaisses. Les faire sauter à feu vif dans une noisette du beurre doux jusqu''à ce que l''eau rendue se soit entièrement évaporée et que les lamelles commencent à dorer. Réserver hors du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une casserole à fond épais, fondre le reste du beurre doux à feu doux, pluvioriser la farine de blé T55 d''un coup et remuer au fouet pendant 3 minutes : le mélange doit mousser sans jamais prendre couleur, on veut un roux blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer la casserole du feu et verser le bouillon chaud en filet, fouet en main, pour éviter tout grumeau. Ajouter le vin blanc sec puis le lait entier, remettre sur feu moyen et laisser réduire 15 minutes en fouettant régulièrement, jusqu''à ce que le velouté nappe le dos d''une cuillère. Assaisonner de poivre noir moulu et de muscade moulue, puis incorporer le zeste de citron et l''estragon frais ciselé : l''un tend une sauce que le poisson ne salera pas, l''autre lui donne son parfum d''anis.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser les champignons réservés dans le velouté, baisser au minimum et laisser les saveurs se lier 5 minutes sans que la sauce reprenne l''ébullition. La sauce doit être entièrement terminée avant que le poisson n''y entre : on ne rattrape pas un velouté autour de cubes de saumon sans les défaire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Battre les jaunes d''œuf cru avec la crème fraîche liquide entière dans un bol, détendre cet appareil avec une louche de sauce brûlante, puis le reverser dans la casserole hors du feu en mélangeant. Réchauffer 2 à 3 minutes à feu très doux : la sauce épaissit et prend du brillant, mais un seul bouillon ferait grainer les jaunes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Garder la sauce liée sur le feu le plus doux, à peine tremblante, et y glisser les cubes de saumon en une seule couche. Compter trois minutes sans jamais remuer, puis couvrir et retirer du feu : ils achèvent de cuire dans la chaleur du velouté et restent nacrés au cœur. Un fouet à ce stade défait les cubes et fait grainer les jaunes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Servir sans attendre, la garniture bien chaude répartie dans des croûtes feuilletées passées quelques minutes au four, ou nappée sur du riz, des nouilles ou des spätzle. Le surplus de sauce se présente à part en saucière.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-009-D1', 'recipe_family', 'Bouchées à la reine au saumon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-009-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-009-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-009-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('609be1f41aff72a3ac12d70f043bf493'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3},"dominant_flavors":["volaille","champignon","crème","vin blanc"],"aroma_families":["beurré","lacté","épicé doux","champignon"],"target_textures":["sauce nappante","viande fondante","lamelles de champignon tendres"],"signature_ingredients":["Champignon de Paris frais","Bouillon de volaille","Jaune d''œuf cru"],"identity_guardrails":["Sans la liaison finale au Jaune d''œuf cru et à la Crème fraîche liquide entière, le velouté retombe au rang de simple béchamel et le plat perd son caractère de sauce à la reine.","Retirer le Champignon de Paris frais ou la volaille pochée vide la garniture de sa substance : ce sont les deux éléments présents dans presque toutes les sources du dossier.","Le bouillon de volaille doit être celui du pochage des viandes, pas de l''eau salée : c''est lui qui porte tout l''umami de la sauce.","La sauce ne doit jamais bouillir après l''ajout des jaunes, sous peine de grainer irrémédiablement."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Bouchées apéritives aux champignons gratinées', 'bouchees aperitives aux champignons gratinees', 'France', 'France',
     'meal', 'entrée', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Bouchées apéritives aux champignons gratinées', 'Petites bouchées feuilletées garnies d''une fricassée de champignons liée et gratinées en entrée', ds.id, 'SRC-009-D2',
    'Myko', 'editorial', 6, 25, 60, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '1da0708f286a66d0eb1998c725d2a60e',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['volaille','champignon','crème','vin blanc']::text[],
    ARRAY['beurré','lacté','épicé doux','champignon']::text[], ARRAY['sauce nappante','viande fondante','lamelles de champignon tendres']::text[],
    ARRAY['Champignon de Paris frais','Bouillon de volaille','Jaune d''œuf cru']::text[], ARRAY['Sans la liaison finale au Jaune d''œuf cru et à la Crème fraîche liquide entière, le velouté retombe au rang de simple béchamel et le plat perd son caractère de sauce à la reine.','Retirer le Champignon de Paris frais ou la volaille pochée vide la garniture de sa substance : ce sont les deux éléments présents dans presque toutes les sources du dossier.','Le bouillon de volaille doit être celui du pochage des viandes, pas de l''eau salée : c''est lui qui porte tout l''umami de la sauce.','La sauce ne doit jamais bouillir après l''ajout des jaunes, sous peine de grainer irrémédiablement.']::text[],
    ARRAY['mijotage','réduction','liaison','gratinage']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf','sulfites']::text[],
    'Se garde 2 jours au réfrigérateur à 4 °C dans une boîte hermétique, la garniture bien refroidie avant fermeture. Réchauffer à feu très doux ou au bain-marie en remuant, sans jamais laisser frémir. La congélation est déconseillée : la liaison jaune d''œuf et crème tranche à la décongélation et les champignons relâchent leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-009'), '{"variant_label":"Version apéritive d''après 750g.com : garnir des mini-bouchées de champignons de Paris crémés, parsemer de fromage râpé et gratiner 8 à 15 minutes à 170 °C.","rationale":"Sans les viandes, le champignon passe de garniture à sujet du plat : il faut plus du triple pour que la bouchée ait encore quelque chose à mordre, et une saisie en deux fois pour qu''il dore au lieu de bouillir. Le velouté est ramené de moitié et lié plus serré — la garniture ayant perdu les deux tiers de sa matière, la sauce de la base y ferait une soupe qui déborderait de croûtes minuscules ; il n''a plus non plus de bouillon de pochage pour le nourrir, seulement une infusion de carotte et d''oignon, ce qui le rend plus lacté et moins profond. Le gratinage referme le tout d''une croûte de fromage que la version chaude en croûte n''a pas.","operations":[{"op":"remove","form":"Poulet entier cru"},{"op":"remove","form":"Escalope de veau crue fine"},{"op":"set","form":"Champignon de Paris frais","quantity":500,"role":"légume","optional":false},{"op":"set","form":"Bouillon de volaille","quantity":300,"role":"liquide"},{"op":"set","form":"Lait entier","quantity":150},{"op":"set","form":"Vin blanc sec","quantity":90},{"op":"set","form":"Farine de blé T55","quantity":30},{"op":"set","form":"Carotte crue","quantity":40},{"op":"set","form":"Oignon jaune cru","quantity":50},{"op":"set","form":"Beurre doux","quantity":60},{"op":"add","form":"Emmental râpé","quantity":80,"unit":"g","role":"fromage","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Peler la carotte et l''oignon jaune, les couper en gros tronçons et les jeter dans une casserole avec le bouillon de volaille. Porter à frémissement, couvrir et laisser infuser vingt minutes : sans viande à pocher, c''est ce seul passage des légumes qui donnera au liquide de quoi soutenir le velouté. Filtrer au chinois et réserver au chaud."},{"op":"remove","n":2},{"op":"remove","n":3},{"op":"replace","n":4,"instruction":"Nettoyer les champignons de Paris frais en grattant le chapeau et en coupant le bout terreux du pied, puis les émincer en lamelles fines. Les faire sauter en deux fournées à feu vif dans la moitié du beurre doux, jusqu''à ce que toute l''eau rendue se soit évaporée et que les lamelles prennent couleur. En deux fournées et non en une : une poêle surchargée fait bouillir les champignons, et ici ils portent la garniture à eux seuls. Réserver hors du feu, l''autre moitié du beurre revenant au roux."},{"op":"replace","n":7,"instruction":"Verser les champignons réservés dans le velouté, baisser au minimum et laisser les saveurs se lier 5 minutes sans que la sauce reprenne l''ébullition. La sauce, deux fois moins abondante qu''au plat de la base et liée plus serré, doit à peine napper les lamelles : trop fluide, la garniture déborderait des petites croûtes au gratinage."},{"op":"replace","n":9,"instruction":"Chauffer le four à 170 °C. Garnir les mini-croûtes feuilletées à ras bord, les ranger sur une plaque, parsemer chacune d''emmental râpé et enfourner de 8 à 15 minutes selon leur taille, jusqu''à ce que le fromage colore et que la garniture frémisse en surface. Servir brûlant et à la main, dès la sortie du four : une bouchée apéritive tiède retombe et détrempe sa croûte."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
