DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Anchoïade à la tomate', 'anchoiade a la tomate', 'France', 'France',
     'meal', 'condiment', 'documented_variation', 'spicy_umami',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Anchoïade à la tomate', 'Anchoïade d''anchois et ail à l''huile d''olive avec tomate râpée incorporée', ds.id, 'SRC-007-D3',
    'Myko', 'editorial', 4, 15, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', '3e6cbe5d115b86d73a5992bb4f25f07e',
    '{"sweet":0,"salty":4,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":4,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['aillé','salin','acidulé']::text[],
    ARRAY['allium','fruité vert','vinaigré']::text[], ARRAY['pommade lisse','onctueux']::text[],
    ARRAY['Anchois à l''huile, égoutté','Ail cru','Huile d''olive vierge extra']::text[], ARRAY['Sans filets d''anchois pilés, ce n''est pas une anchoïade mais une pâte d''ail à l''huile.','L''ail reste cru et réduit en pâte : le confire efface le mordant qui fait le plat.','L''huile s''incorpore en filet pour que la préparation prenne ; versée d''un coup, elle rejette son gras.','Le plat se sert froid ou à température ambiante — servi chaud, il bascule vers une bagna cauda.']::text[],
    ARRAY['émulsion']::text[], ARRAY[]::text[], ARRAY['poisson','gluten','sulfites']::text[],
    'Se garde 24 heures au réfrigérateur entre 0 et 4 °C, 48 au plus, dans un bocal hermétique : la tomate rend de l''eau et délie peu à peu l''émulsion. Retirer le liquide remonté en surface et remuer avant chaque service. Sortir 20 minutes avant de servir, l''huile figeant au froid. La congélation est à exclure : l''émulsion se casse au dégel, la tomate s''y défait en filaments et l''ail cru y développe une amertume marquée.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-007'), '{"variant_label":"Version à la tomate râpée, plus fraîche et moins concentrée, servie l''été","rationale":"Cent cinquante grammes de tomate râpée pour quatre changent l''échelle du condiment : le sel de l''anchois se dilue, l''ail s''adoucit, et la tartinade devient une sauce fraîche plutôt qu''une pâte à mordre. On y gagne en légèreté, on y perd la concentration et la tenue — cette version rend de l''eau au repos et ne se garde qu''un jour ou deux.","operations":[{"op":"set","form":"Tomate râpée","quantity":150,"role":"légume","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Râper la tomate à la grosse grille, la laisser s''égoutter dix minutes dans une passoire en pressant du dos de la cuillère, puis l''incorporer à la pommade par tiers, en travaillant vite. Ajoutée d''un coup, son eau délierait l''émulsion ; fractionnée, elle se laisse absorber. Rectifier au jus de citron frais et au poivre noir moulu."},{"op":"replace","n":5,"instruction":"Couvrir et laisser reposer une heure au réfrigérateur : l''ail y perd son feu et les arômes se fondent. Retirer à la cuillère le peu d''eau remontée en surface, mélanger une dernière fois et servir frais, dans la journée — cette version tourne bien plus vite que l''anchoïade sèche."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
