  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Ranger les œufs dans une casserole, les couvrir d''eau froide salée et porter sur feu vif ; dès les premiers bouillons, baisser à frémissement et compter dix minutes, en faisant rouler les œufs à la cuillère pendant la première minute pour que les jaunes restent au centre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Sortir les œufs à l''écumoire et les plonger sans attendre dans un saladier d''eau très froide, le temps qu''ils refroidissent à cœur ; les écaler ensuite sous un mince filet d''eau, la coquille se détachant alors sans arracher le blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Fendre chaque œuf en deux dans la longueur, lame essuyée entre chaque coupe, et faire glisser les jaunes dans un bol. Réserver les blancs à couvert : ils ne servent pas ici et se gardent deux jours au frais pour une salade ou une farce. Mettre à part deux jaunes entiers, qui feront la neige de finition.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pour une liaison maison, travailler le jaune d''œuf cru avec la moutarde de Dijon, verser l''huile d''olive vierge extra en filet très mince sans cesser de fouetter jusqu''à ce que la sauce se tienne, puis détendre au jus de citron frais au dernier moment ; sinon, partir directement de la mayonnaise.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Réunir dans le bol du mixeur les jaunes restants, la mayonnaise, le thon soigneusement égoutté et émietté, le sel fin, le poivre noir moulu et le persil frais ciselé. Mixer par impulsions courtes, racler les parois, puis mixer en continu jusqu''à une crème parfaitement lisse : elle doit tomber du ruban sans se casser ni couler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Répartir la crème dans quatre verrines à la poche à douille, en descendant la douille au fond du verre pour ne pas emprisonner de bulle d''air, puis lisser la surface à la petite spatule. Ne pas remplir à ras bord : il faut garder la place de la neige de jaunes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Tamiser les deux jaunes réservés directement au-dessus des verrines pour obtenir la neige jaune caractéristique, ajouter quelques pluches de persil frais, puis laisser raffermir trente minutes au réfrigérateur avant de servir bien frais, à la petite cuillère.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-015-D3', 'recipe_family', 'Verrines mimosa au thon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-015-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-015-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-015-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('18645dc0ab5f23a5321f071f6e991ce1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["jaune d''œuf cuit","mayonnaise","moutarde"],"aroma_families":["œuf cuit","moutardé","herbacé"],"target_textures":["blanc ferme et lisse","farce crémeuse","poudre sèche de jaune tamisé"],"signature_ingredients":["Œuf cru","Mayonnaise","Moutarde de Dijon"],"identity_guardrails":["La finition en jaune dur tamisé saupoudré sur le dessus est ce qui fait le mimosa : sans elle, le plat n''est qu''un œuf dur garni.","Les demi-blancs doivent rester entiers et servir de contenant ; hachés ou mixés, on bascule sur une salade d''œufs.","La liaison est une mayonnaise froide montée à l''huile, jamais une sauce cuite ni une crème chaude.","Le plat se sert froid, après passage au réfrigérateur ; tiède, la farce se délite et l''identité se perd."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Œufs mimosa frits', 'oeufs mimosa frits', 'France', 'France',
     'meal', 'entrée froide', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Œufs mimosa frits', 'Œufs mimosa à la mayonnaise moutardée, panés à la chapelure et frits', ds.id, 'SRC-015-D4',
    'Myko', 'editorial', 4, 35, 20, 'facile',
    NULL, NULL,
    'B', 'candidate', '84da60873cfc3f6ccd5e755df6903239',
    '{"sweet":0,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":2}'::jsonb, ARRAY['jaune d''œuf cuit','mayonnaise','moutarde']::text[],
    ARRAY['œuf cuit','moutardé','herbacé']::text[], ARRAY['blanc ferme et lisse','farce crémeuse','poudre sèche de jaune tamisé']::text[],
    ARRAY['Œuf cru','Mayonnaise','Moutarde de Dijon']::text[], ARRAY['La finition en jaune dur tamisé saupoudré sur le dessus est ce qui fait le mimosa : sans elle, le plat n''est qu''un œuf dur garni.','Les demi-blancs doivent rester entiers et servir de contenant ; hachés ou mixés, on bascule sur une salade d''œufs.','La liaison est une mayonnaise froide montée à l''huile, jamais une sauce cuite ni une crème chaude.','Le plat se sert froid, après passage au réfrigérateur ; tiède, la farce se délite et l''identité se perd.']::text[],
    ARRAY['pochage','émulsion','tamisage','panure','friture']::text[], ARRAY[]::text[], ARRAY['œuf','moutarde','poisson']::text[],
    'Ne se conserve pas : la panure ramollit en moins d''une heure au contact de la farce et de l''humidité des blancs. Frire et garnir au moment de servir ; les demi-blancs panés crus peuvent en revanche attendre deux heures au réfrigérateur avant friture.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-015'), '{"variant_label":"Œufs mimosa frits : paner les demi-blancs (farine, œuf battu, chapelure), les frire une à deux minutes en huile chaude, puis les garnir de la farce mimosa au moment de servir.","rationale":"La panure change la nature du plat : le blanc n''est plus une coquille froide mais une croquette chaude, et l''entrée passe de légère à franchement riche entre la friture et la chapelure. Un œuf supplémentaire est nécessaire pour la dorure, et la préparation cesse d''être une entrée qu''on prend de l''avance — panée puis garnie, elle ramollit en une demi-heure et se sert donc à la minute.","operations":[{"op":"set","form":"Œuf cru","quantity":330,"role":"protéine principale"},{"op":"add","form":"Farine de blé T55","quantity":40,"unit":"g","role":"panure"},{"op":"add","form":"Chapelure de blé","quantity":80,"unit":"g","role":"panure"},{"op":"add","form":"Huile de friture","quantity":400,"unit":"ml","role":"friture"}],"steps":[{"op":"replace","n":1,"instruction":"Mettre de côté un œuf entier cru, qui servira à la dorure. Ranger les autres dans une casserole, les couvrir d''eau froide salée et porter sur feu vif ; dès les premiers bouillons, baisser à frémissement et compter dix minutes, en faisant rouler les œufs à la cuillère pendant la première minute pour que les jaunes restent au centre."},{"op":"replace","n":3,"instruction":"Fendre chaque œuf en deux dans la longueur, lame essuyée entre chaque coupe, puis faire glisser le jaune hors de son logement en préservant l''intégrité du blanc : une entaille et la panure laisserait entrer l''huile jusque dans le creux. Réserver les jaunes dans un bol et aligner les demi-blancs sur une plaque, creux vers le haut, prêts à être panés."},{"op":"insert","after":3,"instruction":"Battre à la fourchette l''œuf cru réservé dans une assiette creuse. Disposer à côté la farine de blé dans une première assiette et la chapelure de blé dans une seconde. Passer chaque demi-blanc dans la farine en tapotant l''excédent, puis dans l''œuf battu, puis dans la chapelure en pressant du bout des doigts jusque dans le creux — c''est là que la panure lâche si on la néglige. Ranger les demi-blancs panés au frais, le temps de monter la farce : la friture ne vient qu''après elle."},{"op":"insert","after":6,"instruction":"La farce prête, chauffer l''huile de friture dans une petite casserole à haut bord jusqu''à 175 °C — une pincée de chapelure jetée dedans doit grésiller aussitôt sans noircir. Y descendre les demi-blancs trois ou quatre à la fois, creux vers le haut, et les laisser une à deux minutes, le temps que la croûte prenne couleur sans que le blanc ne caoutchoute. Les remonter à l''écumoire et les égoutter sur un papier absorbant."},{"op":"replace","n":6,"instruction":"Laisser les demi-blancs frits tiédir cinq minutes, le temps que la croûte se raffermisse, puis les garnir de la farce à la poche à douille en bombant la surface. Ne pas déborder sur la panure : mouillée, elle ramollit en quelques minutes et tout le travail est perdu."},{"op":"replace","n":7,"instruction":"Tamiser le dernier tiers des jaunes réservés au-dessus des œufs garnis pour obtenir la neige jaune caractéristique, ajouter quelques pluches de persil frais et servir sans attendre. Contrairement aux mimosa classiques, ceux-ci ne passent pas au réfrigérateur : ils y perdraient en une demi-heure tout le croustillant qu''on vient de leur donner."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
