  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire rendre leur gras aux lardons dans une poêle, à feu moyen, puis ajouter l''oignon et le laisser blondir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Ajouter les rondelles de pomme de terre dans la seule graisse rendue par les lardons et les laisser colorer sans trop les remuer. La croûte se forme plus lentement qu''avec une matière grasse laitière et reste plus sèche : compter deux ou trois minutes de plus et résister à l''envie de retourner les rondelles trop tôt.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Battre les œufs à la fourchette, saler légèrement — les lardons salent déjà — et poivrer, puis incorporer la ciboulette ciselée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser les œufs sur la garniture bien chaude et baisser le feu, sans ramener les bords vers le centre. L''omelette doit rester plate et d''épaisseur régulière : c''est à cette condition qu''elle se découpera droit une fois froide.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Prolonger la cuisson à feu doux jusqu''à ce que le cœur soit pris et ne tremble plus sous la poêle secouée, puis faire glisser l''omelette sur une grille et la laisser refroidir complètement. La détailler alors en lanières d''un centimètre : un cœur resté coulant se déferait au couteau et rendrait son eau en refroidissant.');

