  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler l''oignon et le hacher menu, dégermer l''ail puis l''écraser. Ouvrir la conserve de thon, la laisser s''égoutter quelques minutes dans une passoire et défaire la chair en miettes grossières à la fourchette.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire tiédir la moitié de l''huile d''olive dans une sauteuse large, y laisser fondre l''oignon à feu doux jusqu''à ce qu''il devienne translucide sans prendre couleur, puis ajouter l''ail écrasé pour la dernière minute seulement, le temps qu''il libère son parfum. Réserver l''autre moitié de l''huile : c''est elle qui assaisonnera le plat au dressage, et elle ne doit pas voir le feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Verser la tomate concassée avec tout son jus, saler légèrement, donner un tour de poivre, poser le couvercle en biais et laisser réduire à petit feu une quinzaine de minutes, jusqu''à ce que la sauce se resserre et nappe le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Pendant la réduction, porter un grand volume d''eau salée à pleine ébullition et y cuire les pâtes une minute de moins que le temps indiqué sur le paquet. Réserver une petite louche d''eau de cuisson avant d''égoutter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Baisser le feu sous la sauce et y disperser les miettes de thon, puis laisser confire cinq minutes sans remuer trop fort : le poisson doit se réchauffer et prendre le goût de la tomate en restant en morceaux. Rien d''autre ne vient parfumer la sauteuse à ce stade, c''est l''ail fondu du début qui doit s''entendre sous la tomate.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Réunir les pâtes égouttées et la sauce dans la sauteuse, verser l''huile d''olive réservée bien crue et un filet d''eau de cuisson si l''ensemble paraît sec, mélanger hors du feu pour enrober chaque pâte. Une huile qui n''a pas chauffé garde son amertume poivrée et son fruité vert, et c''est tout l''assaisonnement du plat : rectifier sel et poivre, puis servir sans attendre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-018-D3', 'recipe_family', 'Pâtes au thon à l''huile d''olive crue',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-018-D3', 'missing_required_count', v_missing), 'open');
  END IF;

