  VALUES (v_version, 3, 'Sortir le panier et laisser les tronçons s''égoutter deux minutes sans jamais les presser. Ils n''ont pas bu d''eau, il n''y a donc rien à chasser, et le dos de la louche ne ferait ici que les écraser et les défaire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire chauffer l''huile d''olive vierge extra dans une sauteuse large et y remuer les poireaux deux minutes seulement sur feu vif, le temps de sécher leur surface et de leur donner une pointe de coloration. Les retourner à la spatule plutôt qu''à la cuillère, ils sont encore entiers et le resteront. Saler et poivrer à ce moment-là.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Retirer la sauteuse du feu, arroser de crème fraîche liquide entière et mélanger doucement jusqu''à ce que chaque tronçon soit enrobé d''un voile crémeux. Goûter et rectifier le sel et le poivre avant de dresser.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler la préparation dans un plat à gratin en une couche régulière, sans tasser, puis recouvrir uniformément de gruyère râpé jusqu''aux bords du plat.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Enfourner à 210 °C sur la grille haute pendant quinze à vingt minutes, jusqu''à obtenir une surface dorée et boursouflée. Rester à proximité sur la fin : le fromage bascule très vite du doré au brûlé. Laisser reposer cinq minutes hors du four avant de servir à même le plat de cuisson.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-020-D4', 'recipe_family', 'Poireaux vapeur gratinés au gruyère',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-020-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-020-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-020-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('b0b6f698d295ab4b67d41b917da42e12'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["poireau doux","crème lactée","fromage gratiné"],"aroma_families":["lactée","alliacée","grillée"],"target_textures":["fondant","croûte gratinée","nappage crémeux"],"signature_ingredients":["Poireau cru","Gruyère râpé","Crème fraîche liquide entière"],"identity_guardrails":["Le poireau doit être précuit puis pressé : sans cet égouttage, le plat rend son eau et devient une soupe gratinée.","Sans gruyère râpé sur le dessus, il n''y a plus de croûte dorée et le plat cesse d''être un gratin.","Le liant blanc et onctueux est obligatoire : privé de crème, l''appareil n''est plus qu''un plat de poireaux rôtis."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poivrons farcis au riz et au curry', 'poivrons farcis au riz et au curry', 'France', 'France',
     'meal', 'légume farci', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poivrons farcis au riz et au curry', 'Poivrons rouges farcis de riz cuisiné au curry dans un bouillon de volaille, rôtis au four', ds.id, 'SRC-021-D1',
    'Myko', 'editorial', 4, 25, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', 'a3999cae4e05fb476978efe2c7ff3b0e',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['poivron rôti','lard fumé','tomate cuite','ail doux']::text[],
    ARRAY['végétal grillé','fumé','aillé','herbacé']::text[], ARRAY['poivron fondant','riz moelleux','farce liée','surface légèrement grillée']::text[],
    ARRAY['Poivron rouge frais','Riz cru']::text[], ARRAY['Le poivron entier évidé sert de contenant et cuit avec la farce : farcir un autre légume ou servir la garniture à part change le plat.','Le riz est engagé à mi-cuisson et finit de gonfler au four dans les sucs du poivron ; un riz déjà cuit à cœur donne une farce pâteuse qui n''est plus la recette.','La cuisson se termine au four, pas à la casserole : le poivron doit s''affaisser et caraméliser en surface.']::text[],
    ARRAY['blanchiment','suage','réduction','rôtissage']::text[], ARRAY[]::text[], ARRAY['œuf']::text[],
    'Trois jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, réchauffés vingt minutes à 160 °C plutôt qu''au micro-ondes qui détrempe la peau. La congélation tient deux mois mais ramollit beaucoup le poivron à la décongélation : mieux vaut congeler la farce seule et garnir des poivrons frais le jour du repas.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-021'), '{"variant_label":"Version sans viande : supprimer le lardon fumé cru et cuire le riz avec du curry en poudre pour compenser la perte de profondeur.","rationale":"Le lardon fumé sort de la farce et cinq grammes de curry en poudre entrent dans l''eau du riz. Le plat perd son fumé, son sel de charcuterie et une bonne part de son gras, et se retrouve porté par l''épice, la tomate et l''ail : plus léger, plus végétal, franchement autre. Le riz cuit à part dans juste assez d''eau pour qu''il la boive presque entièrement, faute de quoi le curry resterait dans un liquide qu''on jette et n''arriverait jamais dans la farce. Il faut saler la farce d''une pincée de plus qu''à l''ordinaire, la charcuterie ne s''en chargeant plus.","operations":[{"op":"remove","form":"Lardon fumé cru"},{"op":"add","form":"Curry en poudre","quantity":5,"unit":"g","role":"épice","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Porter à ébullition trente centilitres d''eau salée dans une petite casserole, y délayer le curry en poudre, puis y jeter le riz et l''arrêter à la moitié du temps indiqué sur l''emballage. Un volume court plutôt que la grande eau de blanchiment des poivrons : le grain boit ici presque toute son eau et garde l''épice avec elle, là où plusieurs litres l''emporteraient à l''évier. Égoutter le peu de liquide restant sans rincer, puis étaler le riz pour qu''il tiédisse — il absorbera le reste de son eau pendant la cuisson au four."},{"op":"remove","n":5},{"op":"replace","n":6,"instruction":"Verser un tiers de l''huile d''olive dans une poêle, ajouter l''oignon finement émincé et l''ail écrasé, et laisser suer à feu moyen jusqu''à transparence."},{"op":"replace","n":8,"instruction":"Hors du feu, réunir dans un saladier le riz au curry, la fondue de tomate à l''oignon et les herbes ciselées. Saler, poivrer, puis lier avec l''œuf battu en travaillant la farce à la main pour la rendre homogène. Goûter avant de garnir : privée du gras salé de la charcuterie, cette farce demande toujours une pincée de sel de plus qu''on ne le croit."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

