     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 1, 'g', 'optional',
     'assaisonnement', true, 13);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mettre le four à chauffer sur 200 °C. Trancher une calotte au sommet de chaque poivron du côté du pédoncule et la garder de côté : elle servira de chapeau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Creuser l''intérieur des poivrons pour enlever les pépins et les nervures pâles, en veillant à ne pas percer la paroi. Rincer la cavité et l''éponger.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Immerger les poivrons évidés dans une grande casserole d''eau salée à petits bouillons pendant environ quinze minutes : la chair doit céder sous le doigt tout en gardant assez de tenue pour rester debout. Les rafraîchir aussitôt à l''eau froide, puis les laisser s''égoutter retournés.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans cette même eau, jeter le riz et l''arrêter à la moitié du temps indiqué sur l''emballage. L''égoutter et l''étaler pour qu''il tiédisse : il absorbera le reste de son eau pendant la cuisson au four.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire fondre les lardons à sec dans une poêle chaude, juste le temps que leur gras devienne translucide, sans chercher de coloration marquée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser un tiers de l''huile d''olive dans la poêle, ajouter l''oignon finement émincé et l''ail écrasé, et laisser suer à feu moyen jusqu''à transparence.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Incorporer la tomate râpée et laisser réduire une dizaine de minutes à découvert, en remuant de temps en temps, jusqu''à ce que le mélange ne rende plus d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Hors du feu, réunir dans un saladier le riz à mi-cuisson et la préparation lardons-tomate, et attendre que l''ensemble ait vraiment tiédi avant d''y jeter la coriandre et le persil ciselés au dernier moment. Sur une farce brûlante, les deux herbes noircissent et rendent leur eau : on aurait doublé les quantités pour rien. Saler, poivrer, puis lier avec l''œuf battu en travaillant la farce à la main pour la rendre homogène.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Remplir les poivrons sans tasser la garniture, recoiffer chacun de sa calotte et les caler debout dans un plat à four badigeonné du reste d''huile d''olive.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Délayer le bouillon de volaille dans un grand verre d''eau chaude et le verser au fond du plat, sans arroser les chapeaux. Couvrir de papier aluminium.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 11, 'Enfourner quarante minutes, en ôtant l''aluminium sur le dernier quart d''heure pour que le dessus sèche et prenne couleur. Laisser reposer une bonne demi-heure hors du four et servir tiède : un poivron farci est dense et tient longtemps sa chaleur, vingt minutes ne suffiraient pas à le ramener sous la brûlure. C''est à cette température seulement que la coriandre et le persil se font entendre, alors qu''un poivron sortant du four les couvre entièrement.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-021-D2', 'recipe_family', 'Poivrons farcis aux herbes fraîches',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-021-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-021-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-021-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('990dde975eceaa4cc18aac73ca21658e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["poivron rôti","lard fumé","tomate cuite","ail doux"],"aroma_families":["végétal grillé","fumé","aillé","herbacé"],"target_textures":["poivron fondant","riz moelleux","farce liée","surface légèrement grillée"],"signature_ingredients":["Poivron rouge frais","Riz cru","Lardon fumé cru"],"identity_guardrails":["Le poivron entier évidé sert de contenant et cuit avec la farce : farcir un autre légume ou servir la garniture à part change le plat.","Le riz est engagé à mi-cuisson et finit de gonfler au four dans les sucs du poivron ; un riz déjà cuit à cœur donne une farce pâteuse qui n''est plus la recette.","La cuisson se termine au four, pas à la casserole : le poivron doit s''affaisser et caraméliser en surface."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poivrons farcis rôtis à découvert', 'poivrons farcis rotis a decouvert', 'France', 'France',
     'meal', 'légume farci', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poivrons farcis rôtis à découvert', 'Poivrons rouges farcis de riz et lardons à la tomate, rôtis à découvert pour une peau plus dorée', ds.id, 'SRC-021-D3',
    'Myko', 'editorial', 4, 25, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '92ee4b723470d4e5bb04311e3b3a0df3',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['poivron rôti','lard fumé','tomate cuite','ail doux']::text[],
    ARRAY['végétal grillé','fumé','aillé','herbacé']::text[], ARRAY['poivron fondant','riz moelleux','farce liée','surface légèrement grillée']::text[],
    ARRAY['Poivron rouge frais','Riz cru','Lardon fumé cru']::text[], ARRAY['Le poivron entier évidé sert de contenant et cuit avec la farce : farcir un autre légume ou servir la garniture à part change le plat.','Le riz est engagé à mi-cuisson et finit de gonfler au four dans les sucs du poivron ; un riz déjà cuit à cœur donne une farce pâteuse qui n''est plus la recette.','La cuisson se termine au four, pas à la casserole : le poivron doit s''affaisser et caraméliser en surface.']::text[],
    ARRAY['blanchiment','saisie','réduction','rôtissage']::text[], ARRAY[]::text[], ARRAY['œuf']::text[],
    'Trois jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, réchauffés vingt minutes à 160 °C plutôt qu''au micro-ondes qui détrempe la peau. La congélation tient deux mois mais ramollit beaucoup le poivron à la décongélation : mieux vaut congeler la farce seule et garnir des poivrons frais le jour du repas.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-021'), '{"variant_label":"Cuisson à découvert du début à la fin pour une farce plus sèche et une peau nettement plus grillée, en surveillant le fond de plat qui s''assèche plus vite.","rationale":"L''aluminium disparaît du début à la fin : les poivrons ne cuisent plus dans leur propre vapeur mais rôtissent à sec. La peau se tache de brun et se plisse, et la farce, qui garde sa calotte pour couvercle, se resserre et perd l''humidité qui la rendait moelleuse à cœur. Le bouillon passe de sept à dix grammes parce que le fond de plat s''évapore deux fois plus vite et qu''il faudra le rallonger en cours de route. C''est un plat plus grillé et plus concentré, mais il ne se laisse plus oublier : dix minutes de fond à sec suffisent à donner de l''amer brûlé à toute la farce.","operations":[{"op":"set","form":"Bouillon de volaille","quantity":10,"role":"liquide de cuisson","optional":false}],"steps":[{"op":"replace","n":10,"instruction":"Délayer le bouillon de volaille dans un grand verre d''eau chaude et le verser au fond du plat, sans arroser les chapeaux. Ne rien couvrir : c''est tout le principe de cette version, et c''est aussi ce qui fait s''évaporer le fond deux fois plus vite qu''à l''ordinaire."},{"op":"replace","n":11,"instruction":"Enfourner quarante minutes à découvert, en regardant le fond du plat toutes les dix minutes : dès qu''il n''y reste plus de liquide, rajouter un demi-verre d''eau chaude, sans quoi les sucs attachés brûlent et communiquent leur amertume à toute la farce. La peau se ride et se marque de taches brunes, tandis que la farce, protégée par sa calotte, se resserre sans se dessécher en surface. Laisser reposer dix minutes hors du four avant de servir."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
