     jsonb_build_object('recipe_code', 'SRC-021-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-021-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('92ee4b723470d4e5bb04311e3b3a0df3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["poivron rôti","lard fumé","tomate cuite","ail doux"],"aroma_families":["végétal grillé","fumé","aillé","herbacé"],"target_textures":["poivron fondant","riz moelleux","farce liée","surface légèrement grillée"],"signature_ingredients":["Poivron rouge frais","Riz cru","Lardon fumé cru"],"identity_guardrails":["Le poivron entier évidé sert de contenant et cuit avec la farce : farcir un autre légume ou servir la garniture à part change le plat.","Le riz est engagé à mi-cuisson et finit de gonfler au four dans les sucs du poivron ; un riz déjà cuit à cœur donne une farce pâteuse qui n''est plus la recette.","La cuisson se termine au four, pas à la casserole : le poivron doit s''affaisser et caraméliser en surface."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poivrons farcis au riz en barquettes', 'poivrons farcis au riz en barquettes', 'France', 'France',
     'meal', 'légume farci', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poivrons farcis au riz en barquettes', 'Poivrons rouges coupés en barquettes, farcis de riz et lardons à la tomate', ds.id, 'SRC-021-D4',
    'Myko', 'editorial', 4, 25, 30, 'facile',
    NULL, NULL,
    'B', 'candidate', '99e5cc211e396d15596c13d4cdeb5f69',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['poivron rôti','lard fumé','tomate cuite','ail doux']::text[],
    ARRAY['végétal grillé','fumé','aillé','herbacé']::text[], ARRAY['poivron fondant','riz moelleux','farce liée','surface légèrement grillée']::text[],
    ARRAY['Poivron rouge frais','Riz cru','Lardon fumé cru']::text[], ARRAY['Le poivron entier évidé sert de contenant et cuit avec la farce : farcir un autre légume ou servir la garniture à part change le plat.','Le riz est engagé à mi-cuisson et finit de gonfler au four dans les sucs du poivron ; un riz déjà cuit à cœur donne une farce pâteuse qui n''est plus la recette.','La cuisson se termine au four, pas à la casserole : le poivron doit s''affaisser et caraméliser en surface.']::text[],
    ARRAY['blanchiment','saisie','réduction','rôtissage']::text[], ARRAY[]::text[], ARRAY['œuf']::text[],
    'Trois jours au réfrigérateur entre 0 et 4 °C dans une boîte hermétique, réchauffés vingt minutes à 160 °C plutôt qu''au micro-ondes qui détrempe la peau. La congélation tient deux mois mais ramollit beaucoup le poivron à la décongélation : mieux vaut congeler la farce seule et garnir des poivrons frais le jour du repas.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-021'), '{"variant_label":"Poivrons coupés en deux dans la longueur et couchés dans le plat : cuisson raccourcie d''une dizaine de minutes, portions plus faciles à répartir.","rationale":"Les poivrons sont fendus dans la longueur et couchés au lieu d''être chapeautés et dressés. Sans calotte, la farce reste à découvert : dès qu''on ôte l''aluminium, elle sèche et prend couleur sur le dessus au lieu d''étuver jusqu''au bout sous son chapeau. Une moitié s''attendrit plus vite qu''un poivron entier, si bien que le blanchiment tombe de quinze à dix minutes et le four de quarante à trente. Le service y gagne, une ou deux barquettes faisant une part nette sans découpe hasardeuse ; en échange, une moitié blanchie trop longtemps se déchire et ne tient plus sa garniture.","operations":[],"steps":[{"op":"replace","n":1,"instruction":"Mettre le four à chauffer sur 200 °C. Fendre chaque poivron en deux dans la longueur, en passant la lame de part et d''autre du pédoncule pour obtenir deux moitiés de taille égale."},{"op":"replace","n":2,"instruction":"Racler l''intérieur de chaque moitié à la cuillère pour ôter les pépins et les nervures pâles, sans entamer la paroi qui doit rester assez épaisse pour porter la farce. Rincer les barquettes et les éponger."},{"op":"replace","n":3,"instruction":"Plonger les moitiés dans une grande casserole d''eau salée à petits bouillons dix minutes seulement : ouvertes, elles s''attendrissent bien plus vite qu''un poivron entier et se déchirent si on les oublie. Les rafraîchir aussitôt à l''eau froide, puis les laisser s''égoutter retournées."},{"op":"replace","n":9,"instruction":"Garnir chaque moitié de farce sans la tasser, en arrondissant le dessus à la cuillère, puis coucher les barquettes côte à côte dans un plat à four badigeonné du reste d''huile d''olive, sans jamais les superposer."},{"op":"replace","n":10,"instruction":"Délayer le bouillon de volaille dans un grand verre d''eau chaude et le verser au fond du plat, entre les barquettes et jamais dessus : arrosée par-dessus, la farce ouverte se détremperait au lieu de prendre. Couvrir de papier aluminium."},{"op":"replace","n":11,"instruction":"Enfourner trente minutes, en ôtant l''aluminium sur les dix dernières pour que la surface sèche et prenne couleur. Laisser reposer dix minutes hors du four avant de servir, le temps que la farce se raffermisse : les barquettes se soulèvent alors d''une seule pièce à la spatule, une ou deux par assiette."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
