  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Mettre le four à chauffer sur 200 °C. Fendre chaque poivron en deux dans la longueur, en passant la lame de part et d''autre du pédoncule pour obtenir deux moitiés de taille égale.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Racler l''intérieur de chaque moitié à la cuillère pour ôter les pépins et les nervures pâles, sans entamer la paroi qui doit rester assez épaisse pour porter la farce. Rincer les barquettes et les éponger.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Plonger les moitiés dans une grande casserole d''eau salée à petits bouillons dix minutes seulement : ouvertes, elles s''attendrissent bien plus vite qu''un poivron entier et se déchirent si on les oublie. Les rafraîchir aussitôt à l''eau froide, puis les laisser s''égoutter retournées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans cette même eau, jeter le riz et l''arrêter à la moitié du temps indiqué sur l''emballage. L''égoutter et l''étaler pour qu''il tiédisse : il absorbera le reste de son eau pendant la cuisson au four.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faire fondre les lardons à sec dans une poêle chaude, juste le temps que leur gras devienne translucide, sans chercher de coloration marquée.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser un tiers de l''huile d''olive dans la poêle, ajouter l''oignon finement émincé et l''ail écrasé, et laisser suer à feu moyen jusqu''à transparence.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Incorporer la tomate râpée et laisser réduire une dizaine de minutes à découvert, en remuant de temps en temps, jusqu''à ce que le mélange ne rende plus d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Hors du feu, réunir dans un saladier le riz à mi-cuisson, la préparation lardons-tomate et les herbes ciselées. Saler, poivrer, puis lier avec l''œuf battu en travaillant la farce à la main pour la rendre homogène.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Garnir chaque moitié de farce sans la tasser, en arrondissant le dessus à la cuillère, puis coucher les barquettes côte à côte dans un plat à four badigeonné du reste d''huile d''olive, sans jamais les superposer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Délayer le bouillon de volaille dans un grand verre d''eau chaude et le verser au fond du plat, entre les barquettes et jamais dessus : arrosée par-dessus, la farce ouverte se détremperait au lieu de prendre. Couvrir de papier aluminium.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 11, 'Enfourner trente minutes, en ôtant l''aluminium sur les dix dernières pour que la surface sèche et prenne couleur. Laisser reposer dix minutes hors du four avant de servir, le temps que la farce se raffermisse : les barquettes se soulèvent alors d''une seule pièce à la spatule, une ou deux par assiette.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-021-D4', 'recipe_family', 'Poivrons farcis au riz en barquettes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-021-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-021-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-021-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('99e5cc211e396d15596c13d4cdeb5f69'::text), 'myko_v3_canonical_recipe'),
