  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler les pommes de terre, les rincer sous l''eau claire puis les débiter en cubes réguliers d''environ deux centimètres ; les maintenir dans un saladier d''eau froide le temps de préparer le reste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Fendre les poireaux en deux sur la longueur, les laver feuille à feuille pour chasser la terre, puis les détailler en fines demi-rondelles en gardant surtout le blanc et le vert tendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire mousser le beurre doux seul dans une cocotte à fond épais — l''huile d''olive est ici réservée à la friture des croûtons —, y verser les poireaux et les laisser suer huit minutes à feu doux, sans jamais les laisser prendre couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Égoutter les cubes de pomme de terre, les mêler aux poireaux fondus, mouiller avec le bouillon de volaille bien chaud jusqu''à recouvrir les légumes, saler modérément et amener au frémissement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et laisser cuire à petits bouillons vingt-cinq à trente minutes : la pointe d''un couteau doit traverser un cube de pomme de terre sans la moindre résistance.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Tailler le pain de campagne, rassis de préférence, en cubes d''un centimètre. Chauffer l''huile d''olive vierge extra dans une petite poêle jusqu''à ce qu''un cube y grésille aussitôt, puis frire les croûtons par poignées en les remuant sans arrêt deux à trois minutes, jusqu''à ce qu''ils dorent sur toutes leurs faces. Les débarrasser sur un papier absorbant et les saler tout de suite : le sel n''accroche que sur le gras encore chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Mixer le potage encore chaud jusqu''à une texture veloutée, le passer au chinois pour une finesse parfaite, puis incorporer la crème hors du feu et rectifier en sel et poivre. Verser en assiette creuse, semer les croûtons au tout dernier moment et couronner de pluches de cerfeuil frais : posés d''avance, les croûtons boivent le potage et retombent, et le cerfeuil, s''il cuit, perd en quelques secondes son parfum d''anis.');

