  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Peler les pommes de terre, les rincer sous l''eau claire puis les débiter en cubes réguliers d''environ deux centimètres ; les maintenir dans un saladier d''eau froide le temps de préparer le reste.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Fendre les poireaux en deux sur la longueur, les laver feuille à feuille pour chasser la terre, puis les détailler en fines demi-rondelles en gardant surtout le blanc et le vert tendre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Faire mousser le beurre — avec l''huile d''olive si l''on veut une matière grasse plus stable — dans une cocotte à fond épais, y verser les poireaux et les laisser suer huit minutes à feu doux, sans jamais les laisser prendre couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Égoutter les cubes de pomme de terre, les mêler aux poireaux fondus, mouiller d''eau bien chaude jusqu''à recouvrir les légumes, puis saler d''emblée et sans timidité — rien d''autre n''apportera de fond à ce potage, et un mouillement fade ne se rattrape pas au moment de servir. Amener au frémissement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Couvrir et maintenir un frémissement doux vingt-cinq à trente minutes : la pointe d''un couteau doit traverser un cube de pomme de terre sans la moindre résistance. Tenir la casserole en dessous de l''ébullition franche, qui disperserait l''amidon dans le liquide alors que c''est précisément lui qui doit lier ce velouté maigre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Mixer le potage encore chaud jusqu''à une texture veloutée, le passer au chinois pour une finesse parfaite, puis incorporer la crème hors du feu, rectifier en sel et poivre et servir aussitôt en assiette creuse.');

