DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Porc aux pruneaux à la cocotte', 'porc aux pruneaux a la cocotte', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Porc aux pruneaux à la cocotte', 'Épaule de porc mijotée en cocotte avec des pruneaux', ds.id, 'SRC-026-D2',
    'Myko', 'editorial', 4, 20, 90, 'facile',
    NULL, NULL,
    'B', 'candidate', '0aee98be7eaf59392df36689651c6196',
    '{"sweet":3,"salty":2,"acidic":1,"bitter":0,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2}'::jsonb, ARRAY['sucré du fruit sec','porc caramélisé','oignon confit']::text[],
    ARRAY['fruit sec','viande rôtie','légume fondu']::text[], ARRAY['viande fondante à la fourchette','pruneau moelleux et gonflé','sauce nappante']::text[],
    ARRAY['Épaule de porc crue','Pruneau dénoyauté']::text[], ARRAY['Sans pruneau dénoyauté, il ne reste qu''un sauté de porc ordinaire : c''est le fruit sec qui porte le contraste sucré-salé du plat.','La viande doit être saisie en deux fournées et poussée jusqu''au brun : c''est elle seule qui donne au jus la profondeur que la garniture fumée apportait.','La cuisson reste longue et à couvert : un passage rapide à la poêle ne rend pas l''épaule fondante et ne laisse pas les pruneaux parfumer le jus.','Le mouillement se limite à un fond d''eau, pas à un bain : la sauce doit finir réduite et nappante, jamais aqueuse.']::text[],
    ARRAY['saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['sulfites']::text[],
    'Se conserve 3 jours au réfrigérateur entre 0 et 4 °C dans un récipient fermé, et gagne même en goût réchauffé le lendemain à feu doux avec une cuillère d''eau. Le plat se congèle très bien 3 mois : la viande et la sauce supportent la décongélation, les pruneaux ressortent seulement un peu plus fondus.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-026'), '{"variant_label":"Sans lardons : doubler la saisie de la viande pour compenser la profondeur fumée manquante.","rationale":"Retirer les lardons ôte au plat sa colonne fumée et l''essentiel de son sel : la saisie menée en deux fournées et poussée jusqu''au brun redonne du fond au jus, mais ne remplace pas le fumé, qui disparaît vraiment. Il faut désormais saler la cocotte, ce que la recette d''origine n''avait pas à faire, et juger l''assaisonnement une fois le jus réduit. Le résultat est plus maigre, plus franchement porc et pruneau, moins complexe aussi.","operations":[{"op":"remove","form":"Lardon fumé cru"},{"op":"add","form":"Sel fin","quantity":4,"unit":"g","role":"assaisonnement","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Débarrasser l''oignon et la carotte dans une assiette : la saisie se mène ici en deux fournées, et des légumes laissés sur les bords d''une cocotte brûlante noirciraient pendant que la seconde colore, donnant au jus une amertume dont il ne se relève pas. Monter le feu et déposer la moitié des cubes de porc à plat, sans qu''ils se touchent. Les laisser dorer sans les bouger, les retourner face par face jusqu''à ce qu''ils soient colorés partout et presque bruns, les réserver, puis recommencer avec le reste : privée de garniture fumée, la cocotte n''a plus que cette croûte caramélisée pour donner du fond à son jus, et une viande entassée bout au lieu de saisir. Remettre alors dans la cocotte l''oignon, la carotte, toute la viande et les sucs qu''elle a rendus."},{"op":"remove","n":4},{"op":"replace","n":5,"instruction":"Verser l''eau et gratter aussitôt le fond à la cuillère en bois pour décoller les sucs caramélisés. Ajouter le sel fin et poivrer — il n''y a plus de charcuterie pour saler le jus à la place du cuisinier —, porter à petits bouillons puis couvrir et baisser au minimum."},{"op":"replace","n":8,"instruction":"Retirer le couvercle pour les dix dernières minutes et laisser le liquide réduire jusqu''à une sauce brillante qui nappe la cuillère. Mélanger avec précaution, goûter et rectifier en sel et en poivre seulement à ce moment : la réduction concentre l''assaisonnement, et un jus salé trop tôt devient immangeable une fois réduit."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
