    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-027-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-027-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('5f9bcb0995dd4e4b90795d05ccc2be49'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["olive saumurée","veau braisé","ail fondu","vin blanc réduit"],"aroma_families":["herbacé méditerranéen","oignon compoté","tomate concentrée"],"target_textures":["viande fondante","sauce nappante","olive charnue"],"signature_ingredients":["Épaule de veau crue","Olive verte dénoyautée","Olive noire"],"identity_guardrails":["Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.","Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.","La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Sauté de veau aux olives et pommes de terre', 'saute de veau aux olives et pommes de terre', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Sauté de veau aux olives et pommes de terre', 'Veau braisé aux olives avec pommes de terre cuites dans le même jus de cuisson', ds.id, 'SRC-027-D3',
    'Myko', 'editorial', 4, 25, 125, 'facile',
    NULL, NULL,
    'B', 'candidate', 'eb7e5398a29de29b186d4889958bbb1d',
    '{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['olive saumurée','veau braisé','ail fondu','vin blanc réduit']::text[],
    ARRAY['herbacé méditerranéen','oignon compoté','tomate concentrée']::text[], ARRAY['viande fondante','sauce nappante','olive charnue']::text[],
    ARRAY['Épaule de veau crue','Olive verte dénoyautée','Olive noire']::text[], ARRAY['Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.','Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.','La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale.']::text[],
    ARRAY['blanchiment','saisie','déglaçage','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['gluten','sulfites']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans un récipient hermétique, et gagne même à être réchauffé doucement le lendemain. La congélation est possible trois mois à -18 °C, mais mieux vaut congeler la viande et sa sauce sans les olives, dont la chair se ramollit à la décongélation, et les ajouter au réchauffage.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-027'), '{"variant_label":"Version tout-en-un : glisser des pommes de terre en quartiers en même temps que les olives, ce qui fait passer le plat en rôle complet.","rationale":"Les quartiers de pomme de terre cuisent dans la sauce, en boivent une part et rendent leur amidon : le jus épaissit sans farine supplémentaire et le plat se suffit à lui-même, sans riz ni pâtes à côté. En échange la sauce devient moins abondante et moins franche, diluée par sept cents grammes de féculent, et la part pèse près d''une fois et demie celle de la base.","operations":[{"op":"add","form":"Pomme de terre crue, épluchée","quantity":700,"unit":"g","role":"féculent","optional":false}],"steps":[{"op":"replace","n":7,"instruction":"Ajoutez les olives égouttées et les pommes de terre taillées en gros quartiers, retirez le couvercle et prolongez trente-cinq minutes : les quartiers doivent s''ouvrir à la pointe du couteau sans se déliter, et l''amidon qu''ils lâchent achève d''épaissir la sauce. Remuez le moins possible pour ne pas les casser, goûtez et rectifiez le sel en tenant compte des olives avant d''envoyer à table."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

