  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Parez l''épaule de veau et taillez-la en cubes réguliers d''environ quatre centimètres, puis roulez-les dans la farine et secouez-les pour ne garder qu''un voile mince.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Portez une petite casserole d''eau à frémissement, immergez-y les olives vertes et noires une quinzaine de secondes pour adoucir la saumure, égouttez-les et gardez-les de côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Chauffez l''huile d''olive dans une cocotte à fond épais et colorez les cubes de veau par petites poignées, sans jamais surcharger le fond, jusqu''à une croûte ambrée sur toutes les faces ; débarrassez la viande et faites rendre leur gras aux lardons au même endroit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Baissez le feu, jetez l''oignon finement émincé et la carotte en rondelles dans la graisse de cuisson, laissez-les fondre sans brunir, ajoutez l''ail écrasé puis le concentré de tomate — un peu plus généreusement qu''à l''ordinaire — et tournez deux bonnes minutes pour qu''il perde son mordant : c''est lui qui devra porter seul la profondeur et l''acidité du fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mouillez avec un grand verre d''eau prélevé sur les six cents millilitres et raclez aussitôt les sucs collés au fond à la spatule, tant qu''ils se décollent encore ; laissez réduire de moitié, remettez la viande et les lardons, versez le reste de l''eau à hauteur, parsemez de thym et de romarin, salez et poivrez.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrez et maintenez un frémissement à peine perceptible pendant une heure et quart, en remuant délicatement de loin en loin pour que rien n''attache.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Ajoutez les olives égouttées, retirez le couvercle et prolongez trente minutes : la viande doit céder sous la fourchette et la sauce napper le dos d''une cuillère. Goûtez et rectifiez le sel en tenant compte des olives avant d''envoyer à table.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-027-D4', 'recipe_family', 'Sauté de veau aux olives sans alcool',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-027-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-027-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-027-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('eb54dfcd783e817a093a4dae56c7a21d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["olive saumurée","veau braisé","ail fondu","vin blanc réduit"],"aroma_families":["herbacé méditerranéen","oignon compoté","tomate concentrée"],"target_textures":["viande fondante","sauce nappante","olive charnue"],"signature_ingredients":["Épaule de veau crue","Olive verte dénoyautée","Olive noire"],"identity_guardrails":["Les olives sont ajoutées en fin de mijotage et jamais dès le départ : cuites trop longtemps elles rendent le plat amer et perdent leur mâche.","Sans veau en gros cubes saisis puis braisés dans leur propre jus, ce n''est plus un sauté de veau mais un simple ragoût.","La sauce reste courte et liée par la farine de singeage, sans crème ni liaison finale."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Socca au poivre du moulin', 'socca au poivre du moulin', 'France', 'France',
     'meal', 'galette', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Socca au poivre du moulin', 'Galette de pois chiche à l''huile d''olive, assaisonnée généreusement au poivre noir du moulin', ds.id, 'SRC-028-D1',
    'Myko', 'editorial', 4, 15, 15, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '75e7b45e7900aa1d2f4c9519e5ca1670',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":3,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['pois chiche torréfié','huile d''olive','poivre']::text[],
    ARRAY['légumineuse grillée','fruité olive','notes fumées de croûte']::text[], ARRAY['croûte dorée et craquante','cœur souple et fondant','bords fins presque brûlés']::text[],
    ARRAY['Farine de pois chiche','Huile d''olive vierge extra']::text[], ARRAY['Sans farine de pois chiche, ce n''est plus une socca : aucune autre farine ne peut s''y substituer sans détruire le plat.','Sans cuisson à chaleur maximale finie sous le gril, le contraste entre croûte tachée de brun et intérieur moelleux disparaît et la galette devient une simple crêpe pâle.','Sans huile d''olive généreuse dans la pâte et sur la plaque brûlante, la socca perd son parfum et sa surface craquante.','Sans étalement très fin, de deux à trois millimètres, la galette cuit en épaisseur et perd sa texture caractéristique.']::text[],
    ARRAY['rôtissage','gratinage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'La socca se mange dans les minutes qui suivent la sortie du four, quand la croûte est encore craquante. À défaut, la garder quelques heures à température ambiante sous un linge, ou deux jours au réfrigérateur entre 0 et 4 °C en boîte hermétique, puis la repasser deux à trois minutes sous le gril pour lui rendre du croustillant. La congélation est déconseillée : la décongélation détrempe la croûte et rend le cœur caoutchouteux.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-028'), '{"variant_label":"Finition très poivrée au moulin juste avant de servir, jusqu''à couvrir visiblement la surface.","rationale":"Quatre grammes de poivre fraîchement moulu au lieu d''une pincée : le poivre cesse d''être un assaisonnement pour devenir la seconde saveur de la galette, à côté du pois chiche. Sa pointe piquante et résineuse recouvre en partie le goût de farine grillée, et la socca ne convient plus aux palais sensibles. L''assaisonnement passe donc du rang de facultatif à celui d''obligatoire.","operations":[{"op":"set","form":"Poivre noir moulu","quantity":4,"optional":false}],"steps":[{"op":"replace","n":7,"instruction":"Décoller la galette à la spatule et la débiter en morceaux irréguliers, puis passer le moulin sur toute la surface en allées serrées, jusqu''à ce que le poivre noir moulu se voie franchement sur le doré de la pâte. Servir brûlant, à la main : moulu au dernier moment et posé sur un support gras et chaud, le poivre libère ses arômes volatils au lieu de rester une poussière sèche."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
