  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'La veille, couvrir largement d''eau froide les haricots blancs secs et, si vous les utilisez, les haricots rouges secs. Les egoutter et les rincer au moment de cuisiner : sans ce trempage, ils resteraient fermes apres une heure de bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Détailler les carottes et l''oignon en dés réguliers d''un demi-centimètre, les courgettes en bâtonnets courts, les pommes de terre en cubes un peu plus gros. Effiler les haricots verts et les casser en deux. Couper les tomates en deux à l''équateur et les râper sur la grosse grille, face coupée contre la lame et peau tournée vers la paume : la chair passe, la peau reste en main, et l''on s''épargne le passage à l''eau bouillante.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans un grand faitout, faire tiedir un cinquieme de l''huile d''olive et y laisser suer l''oignon, la carotte et la courgette a feu doux cinq minutes, sans coloration : on cherche a reveiller les sucres des legumes, pas a les rissoler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Mouiller avec l''eau froide, ajouter les haricots secs égouttés et la tomate râpée, porter à frémissement et écumer la mousse grise qui monte. Laisser mijoter à couvert quarante minutes, en salant seulement à mi-parcours pour ne pas durcir la peau des légumineuses : la tomate cuite si longtemps perd son mordant et colore tout le bouillon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer les des de pomme de terre et les haricots verts, poursuivre un quart d''heure, puis jeter les pates courtes dans le bouillon frissonnant pour les dix a douze dernieres minutes. Rectifier en sel fin et en poivre noir moulu : le bouillon doit rester juste couvrant, epaissi par l''amidon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, monter le pistou. Dégermer les gousses d''ail et les réduire en purée au mortier avec une pincée de sel, ajouter les feuilles de basilic et piler jusqu''à obtenir une pâte vert sombre. Travailler le parmesan râpé dedans, puis verser le reste de l''huile d''olive en mince filet sans cesser de tourner, comme pour une mayonnaise, jusqu''à une pommade brillante. Elle restera ferme, rien ne venant plus la détendre à la fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer le faitout du feu avant d''y delayer le pistou : au-dela du fremissement, le basilic noircit et l''emulsion se rompt. Couvrir et laisser les aromes se diffuser dix a quinze minutes, puis servir avec le gruyere rape presente a part.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-029-D3', 'recipe_family', 'Soupe au pistou à la tomate râpée',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-029-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-029-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-029-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e0b7379bd29550fe288906df194450a1'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_herbal","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":3,"richness":3,"freshness":4,"intensity":3},"dominant_flavors":["basilic","ail","légumes mijotés","fromage affiné"],"aroma_families":["herbacé","alliacé","végétal","huile d''olive"],"target_textures":["bouillon lié par l''amidon","légumes fondants en dés","pistou onctueux et émulsionné"],"signature_ingredients":["Basilic frais","Ail cru","Huile d''olive vierge extra","Haricot blanc sec"],"identity_guardrails":["Le pistou est incorporé hors du feu, jamais bouilli : c''est ce qui garde l''arôme de basilic cru intact.","Le basilic doit être frais et pilé avec l''ail cru et l''huile d''olive ; un basilic séché ou une sauce cuite fait perdre son nom au plat.","La garniture repose sur les haricots (blancs secs et verts) avec courgette et pomme de terre, cuits à l''eau sans bouillon de viande."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Soupe au pistou aux pommes de terre', 'soupe au pistou aux pommes de terre', 'France', 'France',
     'meal', 'soupe', 'documented_variation', 'fresh_herbal',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Soupe au pistou aux pommes de terre', 'Soupe de légumes et haricots avec des pommes de terre en morceaux en plus des pâtes', ds.id, 'SRC-029-D4',
    'Myko', 'editorial', 6, 30, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ac15aa22a00731c603fba599c789a8fc',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":0,"pungency":3,"richness":3,"freshness":4,"intensity":3}'::jsonb, ARRAY['basilic','ail','légumes mijotés','fromage affiné']::text[],
    ARRAY['herbacé','alliacé','végétal','huile d''olive']::text[], ARRAY['bouillon lié par l''amidon','légumes fondants en dés','pistou onctueux et émulsionné']::text[],
    ARRAY['Basilic frais','Ail cru','Huile d''olive vierge extra','Haricot blanc sec']::text[], ARRAY['Le pistou est incorporé hors du feu, jamais bouilli : c''est ce qui garde l''arôme de basilic cru intact.','Le basilic doit être frais et pilé avec l''ail cru et l''huile d''olive ; un basilic séché ou une sauce cuite fait perdre son nom au plat.','La garniture repose sur les haricots (blancs secs et verts) avec courgette et pomme de terre, cuits à l''eau sans bouillon de viande.']::text[],
    ARRAY['mijotage','émulsion','blanchiment']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans un récipient fermé ; le goût de pistou s''estompe dès le lendemain, mieux vaut en réserver une part fraîche à ajouter au réchauffage. Le bouillon garni se congèle 3 mois s''il est préparé sans pâtes ni pommes de terre, qui se délitent à la décongélation ; le pistou, lui, ne supporte pas la congélation car l''émulsion se sépare.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-029'), '{"variant_label":"Supprimer les pates courtes et augmenter la part de pomme de terre pour une soupe plus rustique et sans gluten.","rationale":"Sans pâtes, la liaison du bouillon repose entièrement sur l''amidon des pommes de terre, portées de quatre cent cinquante à sept cents grammes et partiellement écrasées en fin de cuisson. La soupe devient plus épaisse et plus paysanne, et convient aux régimes sans gluten : les pâtes en étaient la seule source, l''allergène tombe donc avec elles. Elle perd en revanche la mâche des pâtes et se tient moins bien au réchauffage, la fécule se délitant d''un jour sur l''autre.","operations":[{"op":"remove","form":"Pâtes sèches courtes"},{"op":"set","form":"Pomme de terre cuite","quantity":700}],"steps":[{"op":"replace","n":5,"instruction":"Incorporer les dés de pomme de terre et les haricots verts, puis poursuivre une demi-heure à petits bouillons en écrasant quelques cubes contre la paroi du faitout : leur amidon prend le relais et lie le bouillon, qui doit rester juste couvrant. Rectifier alors en sel fin et en poivre noir moulu, la liaison ayant changé le goût du liquide."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

