  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Chauffer le four à 220 °C. Prendre deux aubergines d''environ 280 g pièce, soit à peu près 560 g sur la balance du primeur, qui donnent les 500 g nets une fois les pédoncules coupés. Les rincer et les fendre en deux dans la longueur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Quadriller la chair à la pointe du couteau sans traverser la peau, saler du bout des doigts, badigeonner avec la moitié de l''huile d''olive, puis enfourner les moitiés chair vers le haut 25 minutes : elles doivent s''affaisser et céder sous la cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pendant ce temps, hacher menu l''oignon et l''ail. Les faire suer 5 minutes à feu moyen dans le reste d''huile, en visant la transparence plutôt que la coloration.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Retirer d''abord du feu la poêle d''oignon et d''ail, qui attendra la farce sans brunir : douze minutes de plus sur la flamme suffiraient à l''amertume. Porter une casserole d''eau salée à ébullition et y verser le riz. Le cuire une douzaine de minutes seulement, puis l''égoutter tant qu''il reste ferme au cœur : il finira de gonfler dans la farce, puis au four, et un grain déjà tendre s''y déferait en bouillie. L''étaler dans un plat pour qu''il rende sa vapeur au lieu de coller en masse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Sortir les aubergines, les laisser tiédir 5 minutes, puis les évider à la petite cuillère en gardant une paroi d''environ 5 mm. Hacher grossièrement la chair prélevée et la reverser dans la poêle.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Ajouter la tomate râpée, le sucre, les herbes de Provence et un tour de poivre. Laisser réduire à découvert une quinzaine de minutes : la farce est au point quand la cuillère y laisse un sillon net.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Retirer du feu et verser le riz égoutté dans la poêle, en le mêlant à la fourchette pour que les grains se répartissent sans s''écraser. Ajouter le persil et le basilic ciselés, laisser la chaleur retomber deux minutes, puis lier avec les deux œufs battus en remuant sans arrêt, pour qu''ils épaississent la farce au lieu de coaguler en filaments.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Garnir les coques en tassant à peine — une farce au riz trop serrée devient compacte — puis couvrir de la totalité du gruyère râpé, deux fois la dose habituelle, qui forme ici une croûte franche et non un voile. Remettre au four 20 minutes à 200 °C, jusqu''à une surface dorée et boursouflée, et laisser reposer 5 minutes : le riz se tient nettement mieux tiède qu''à la sortie.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-031-D1', 'recipe_family', 'Aubergines farcies au riz',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-031-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-031-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-031-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('36d644a002e7b4e010947962db4731d2'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","fromage gratiné","ail"],"aroma_families":["herbacé","alliacé","fromager"],"target_textures":["chair fondante","farce moelleuse","surface gratinée"],"signature_ingredients":["Aubergine fraîche","Riz long blanc cru","Tomate râpée"],"identity_guardrails":["La coque d''aubergine rôtie doit rester le contenant : servie en gratin dans un plat, la préparation redevient un simple riz à la tomate.","La chair prélevée retourne obligatoirement dans la farce ; la jeter fait perdre au plat son goût d''aubergine et son moelleux.","Le riz entre dans la farce ferme au cœur : cuit à point avant l''assemblage, il se délite au four et la garniture devient pâteuse."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

