DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tourte au boudin noir et aux poireaux', 'tourte au boudin noir et aux poireaux', 'France', 'France',
     'meal', 'tourte sucrée-salée', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Tourte au boudin noir et aux poireaux', 'Tourte feuilletée garnie de boudin noir, pommes caramélisées et fondue de poireaux', ds.id, 'SRC-032-D1',
    'Myko', 'editorial', 4, 40, 60, 'facile',
    NULL, NULL,
    'B', 'candidate', '6456908594c7d2281b9a5cf850ddf32b',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['pomme compotée','sucré','profond','beurré']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['protéine_fondante','tendre','feuilletage_croustillant']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang en est l''axe et aucune autre charcuterie ne la remplace.','En tourte, la pomme passe en compote : elle doit rester granuleuse et peu sucrée, une purée lisse détrempant le fond et empêchant la pâte de cuire.','Le boyau se retire entièrement : conservé sous la pâte, il se rétracte sans jamais dorer et reste élastique.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['compotage','suer','fonçage','cuisson au four']::text[], ARRAY[]::text[], ARRAY['lait','gluten','œuf']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-032'), '{"variant_label":"Tourte feuilletée : compote de pomme, tronçons de blanc de poireau et rondelles de boudin sans peau entre deux abaisses, dorées à l''œuf, 35 min à 210 °C (750g.com).","rationale":"La poêlée devient une tourte : compote de pomme, fondue de poireau et d''oignon, rondelles de boudin dépouillées de leur boyau, le tout pris entre deux abaisses. Le boudin cuit à l''étouffée sous la pâte au lieu d''être saisi — il reste fondant mais ne développe aucune croûte, et son gras imbibe le feuilletage au lieu de rester dans la poêle. Passée en compote, la pomme perd les morceaux caramélisés dont vivait l''accord sucré-salé de la base ; en échange la tourte se transporte, se réchauffe et se coupe en parts. Le feuilletage pèse en calories presque autant que la charcuterie et fait quasiment doubler la part.","operations":[{"op":"add","form":"Pâte feuilletée crue","quantity":450,"unit":"g","role":"pâte","optional":false},{"op":"add","form":"Poireau cru","quantity":300,"unit":"g","role":"légume","optional":false},{"op":"add","form":"Œuf cru","quantity":50,"unit":"g","role":"dorure","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Pelez et évidez quatre pommes à chair ferme, soit environ 450 g de fruits entiers pour 320 g de chair nette, et détaillez-les en dés. Arrosez-les du jus de citron, poudrez-les du sucre et faites-les fondre à couvert une dizaine de minutes sur feu doux, puis écrasez-les grossièrement à la fourchette : la compote doit rester granuleuse et un peu sèche, une purée lisse détremperait le fond de la tourte."},{"op":"replace","n":2,"instruction":"Épluchez 280 g d''oignons pour en obtenir 250 g nets et émincez-les finement. Fendez les blancs de poireau en quatre dans la longueur, lavez-les à grande eau entre les feuilles et débitez-les en tronçons courts. Faites fondre le tout à couvert dans la totalité du beurre, sur feu très doux, une quinzaine de minutes, jusqu''à ce que le poireau cède sous le doigt sans avoir pris couleur — c''est le seul gras de la tourte, le feuilletage apportant le reste. Égouttez cette fondue et laissez-la refroidir : posée chaude, elle ferait fondre le feuilletage avant qu''il n''entre au four."},{"op":"remove","n":3},{"op":"replace","n":4,"instruction":"Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, qui donnent les 560 g de chair annoncés une fois les extrémités parées. Fendez le boyau d''un coup de lame et retirez-le entièrement — sous la pâte il resterait élastique sous la dent — puis coupez la chair en rondelles d''un bon centimètre, en la manipulant le moins possible, car elle se défait vite une fois nue."},{"op":"replace","n":5,"instruction":"Étalez la moitié de la pâte feuilletée sur une plaque garnie de papier cuisson, piquez-la à la fourchette et laissez deux centimètres de bord libre tout autour. Étalez la compote de pomme au centre, couvrez-la de la fondue de poireau et d''oignon bien égouttée, puis rangez les rondelles de boudin en une seule couche sans les faire chevaucher. Salez, poivrez, et humectez le bord au pinceau."},{"op":"replace","n":6,"instruction":"Posez la seconde abaisse par-dessus, soudez les bords en les pinçant fermement, dorez toute la surface à l''œuf battu et percez une cheminée au centre : sans elle, la vapeur soulève la pâte puis la fait retomber détrempée. Enfournez 35 minutes à 210 °C, jusqu''à ce que le dessus soit brun et le dessous sec au toucher, et attendez dix minutes avant de couper, sinon la garniture glisse hors des parts."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
