  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Comptez à l''achat quatre pommes à chair ferme, soit environ 450 g de fruits entiers : une fois pelées, évidées et débarrassées des pépins, il en reste près de 320 g de chair. Détaillez-les en quartiers épais et arrosez-les aussitôt du jus de citron pour qu''ils gardent leur teinte claire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Épluchez 280 g d''oignons pour en obtenir 250 g nets, émincez-les finement et laissez-les fondre à couvert dans un tiers du beurre, sur feu très doux. Au bout de dix minutes, versez le miel, découvrez et poursuivez dix minutes en remuant souvent : ils doivent devenir sirupeux et brun clair sans jamais accrocher, le miel noircissant longtemps avant le sucre propre de l''oignon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Épluchez 800 g de pommes de terre pour en obtenir 700 g nets, coupez-les en gros cubes et faites-les cuire vingt minutes à l''eau salée, départ à froid, jusqu''à ce que la pointe du couteau les traverse sans effort. Égouttez-les en réservant une louche d''eau de cuisson, écrasez-les au presse-purée avec un autre tiers du beurre et détendez avec l''eau réservée : au fouet ou au mixeur, l''amidon se délite et la purée devient élastique.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une seconde poêle, faites mousser la moitié du beurre restant et couchez-y les quartiers de pomme à plat. Poudrez-les de sucre, laissez-les prendre couleur cinq minutes à couvert, retournez chaque morceau, puis poursuivez à découvert jusqu''à ce que les faces soient laquées. Réservez au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, qui donnent les 560 g de chair annoncés une fois les extrémités parées et le boyau fendu d''un coup de lame — retirez-le entièrement si vous préférez cuire la chair nue, gardez-le pour servir les tronçons entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Essuyez la poêle des pommes, chauffez-y le reste du beurre et posez le boudin sur feu vif juste le temps de le colorer, puis baissez immédiatement l''allure. Huit à dix minutes de cuisson douce en le tournant avec délicatesse suffisent : ne le piquez jamais, sous peine de voir le boyau se rompre et le gras s''échapper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Salez et donnez deux tours de moulin à poivre au dressage. Étalez un large trait de purée dans des assiettes chaudes, posez le boudin par-dessus, ajoutez une cuillerée d''oignons au miel et rangez les quartiers de pomme caramélisés à côté. Nappez du beurre de cuisson resté dans la poêle : l''assiette se suffit alors à elle-même et n''appelle plus ni pain ni féculent.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-032-D3', 'recipe_family', 'Boudin noir aux pommes, purée et oignons au miel',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-032-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-032-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-032-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('1d39a740def81cef977083231dc13396'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["caramélisé","sucré","profond","beurré"],"aroma_families":["beurre","oignon_compoté","porc"],"target_textures":["protéine_fondante","tendre","contraste_léger"],"signature_ingredients":["Boudin noir à cuire","Pomme fraîche"],"identity_guardrails":["Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.","La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.","Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.","Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Poêlée de rattes au boudin noir et aux raisins secs', 'poelee de rattes au boudin noir et aux raisins secs', 'France', 'France',
     'meal', 'plat sauté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Poêlée de rattes au boudin noir et aux raisins secs', 'Boudin noir poêlé avec pommes, pommes de terre nouvelles et raisins secs', ds.id, 'SRC-032-D4',
    'Myko', 'editorial', 4, 30, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '2493795d00c94635d16827b3928e5591',
    '{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4}'::jsonb, ARRAY['caramélisé','sucré','profond','beurré']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['protéine_fondante','tendre','contraste_léger']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.','La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.','Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['saisie','sauté','suer']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-032'), '{"variant_label":"Poêlée de rattes en rondelles avec dés de pomme et raisins secs, boudin doré à part et ajouté au dernier moment (750g.com).","rationale":"Les rattes cuites à l''eau puis dorées en rondelles, les dés de pomme et les raisins secs forment une poêlée unique, dans laquelle le boudin n''entre qu''au dressage, coupé et posé dessus. Le sucre disparaît : ce sont les raisins gonflés au beurre qui portent seuls le sucré. Le plat gagne son féculent et un jeu de textures que la base n''avait pas, mais la pomme, taillée en dés et sautée vite, ne laque plus comme un quartier caramélisé, et le boudin posé trop tôt détremperait les rondelles dorées.","operations":[{"op":"add","form":"Pomme de terre nouvelle crue","quantity":600,"unit":"g","role":"féculent","optional":false},{"op":"add","form":"Raisin sec","quantity":60,"unit":"g","role":"garniture","optional":false},{"op":"remove","form":"Sucre semoule"}],"steps":[{"op":"replace","n":1,"instruction":"Comptez quatre pommes à chair ferme, soit environ 450 g de fruits entiers : pelées, évidées et débarrassées des pépins, il en reste près de 320 g de chair. Détaillez-les en dés d''un centimètre plutôt qu''en quartiers — ils doivent sauter à la même allure que les rondelles de ratte — et arrosez-les aussitôt du jus de citron pour qu''ils gardent leur teinte claire."},{"op":"insert","after":1,"instruction":"Brossez 600 g de rattes sans les peler, ces petites pommes de terre allongées tenant justement leur rondelle grâce à leur peau fine, et faites-les cuire vingt minutes à l''eau salée jusqu''à ce que la pointe du couteau entre sans forcer. Égouttez-les, laissez-les tiédir puis coupez-les en rondelles d''un demi-centimètre : jetées crues dans la poêle, elles brûleraient dehors bien avant d''être fondantes dedans."},{"op":"replace","n":3,"instruction":"Dans une seconde poêle, faites mousser la moitié du beurre restant et couchez-y les rondelles de ratte à plat. Laissez-les dorer cinq minutes sans y toucher, retournez-les, ajoutez les dés de pomme et les raisins secs, puis poursuivez cinq minutes à feu moyen : les raisins gonflent au contact du beurre chaud et suffisent à sucrer la poêlée. Réservez au chaud."},{"op":"replace","n":5,"instruction":"Essuyez la poêle qui a servi à la poêlée, chauffez-y le reste du beurre et posez le boudin sur feu vif juste le temps de le colorer, puis baissez immédiatement l''allure. Huit à dix minutes de cuisson douce en le tournant avec délicatesse suffisent : ne le piquez jamais, sous peine de voir le boyau se rompre et le gras s''échapper dans une poêle où plus rien ne viendra le boire."},{"op":"replace","n":6,"instruction":"Salez, poivrez au moulin et mêlez les oignons fondus à la poêlée de rattes. Répartissez-la dans des assiettes chaudes et posez les tronçons de boudin dessus au tout dernier moment, sans les enfouir : posé trop tôt, il rend son gras et détrempe les rondelles dorées qui faisaient tout l''intérêt du plat."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
