  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Comptez quatre pommes à chair ferme, soit environ 450 g de fruits entiers : pelées, évidées et débarrassées des pépins, il en reste près de 320 g de chair. Détaillez-les en dés d''un centimètre plutôt qu''en quartiers — ils doivent sauter à la même allure que les rondelles de ratte — et arrosez-les aussitôt du jus de citron pour qu''ils gardent leur teinte claire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Brossez 600 g de rattes sans les peler, ces petites pommes de terre allongées tenant justement leur rondelle grâce à leur peau fine, et faites-les cuire vingt minutes à l''eau salée jusqu''à ce que la pointe du couteau entre sans forcer. Égouttez-les, laissez-les tiédir puis coupez-les en rondelles d''un demi-centimètre : jetées crues dans la poêle, elles brûleraient dehors bien avant d''être fondantes dedans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Épluchez 280 g d''oignons pour en obtenir 250 g nets, émincez-les finement et laissez-les fondre à couvert dans un tiers du beurre, sur feu très doux : une quinzaine de minutes suffisent pour qu''ils deviennent translucides puis prennent une couleur dorée, sans jamais accrocher au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Dans une seconde poêle, faites mousser la moitié du beurre restant et couchez-y les rondelles de ratte à plat. Laissez-les dorer cinq minutes sans y toucher, retournez-les, ajoutez les dés de pomme et les raisins secs, puis poursuivez cinq minutes à feu moyen : les raisins gonflent au contact du beurre chaud et suffisent à sucrer la poêlée. Réservez au chaud.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, qui donnent les 560 g de chair annoncés une fois les extrémités parées et le boyau fendu d''un coup de lame — retirez-le entièrement si vous préférez cuire la chair nue, gardez-le pour servir les tronçons entiers.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Essuyez la poêle qui a servi à la poêlée, chauffez-y le reste du beurre et posez le boudin sur feu vif juste le temps de le colorer, puis baissez immédiatement l''allure. Huit à dix minutes de cuisson douce en le tournant avec délicatesse suffisent : ne le piquez jamais, sous peine de voir le boyau se rompre et le gras s''échapper dans une poêle où plus rien ne viendra le boire.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Salez, poivrez au moulin et mêlez les oignons fondus à la poêlée de rattes. Répartissez-la dans des assiettes chaudes et posez les tronçons de boudin dessus au tout dernier moment, sans les enfouir : posé trop tôt, il rend son gras et détrempe les rondelles dorées qui faisaient tout l''intérêt du plat.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-032-D4', 'recipe_family', 'Poêlée de rattes au boudin noir et aux raisins secs',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-032-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-032-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-032-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2493795d00c94635d16827b3928e5591'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":3,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":4},"dominant_flavors":["caramélisé","sucré","profond","beurré"],"aroma_families":["beurre","oignon_compoté","porc"],"target_textures":["protéine_fondante","tendre","contraste_léger"],"signature_ingredients":["Boudin noir à cuire","Pomme fraîche"],"identity_guardrails":["Sans boudin noir, le plat n''existe plus : la chair de sang poêlée en est l''axe et aucune autre charcuterie ne la remplace.","La pomme doit rester en morceaux identifiables et caramélisés ; réduite en compote lisse ou remplacée par de la pomme de terre, l''accord sucré-salé se défait.","Saisie brève puis feu doux : cuit à feu vif d''un bout à l''autre, le boyau éclate et le gras se perd dans la poêle.","Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pommes au four farcies au boudin noir', 'pommes au four farcies au boudin noir', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pommes au four farcies au boudin noir', 'Pommes évidées farcies de boudin noir et oignons, cuites au four', ds.id, 'SRC-032-D5',
    'Myko', 'editorial', 4, 25, 45, 'facile',
    NULL, NULL,
    'B', 'candidate', '245b6cb4434873701b38ea8a0ce319a4',
    '{"sweet":4,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['pomme au four','sucré','profond','grillé']::text[],
    ARRAY['beurre','oignon_compoté','porc']::text[], ARRAY['chair fondante','farce grumeleuse','peau tendue']::text[],
    ARRAY['Boudin noir à cuire','Pomme fraîche']::text[], ARRAY['Sans boudin noir, le plat n''existe plus : la chair de sang en est l''axe et aucune autre charcuterie ne la remplace.','La pomme entière est ici le contenant, non la garniture : farcie dans un plat à gratin ou remplacée par un autre fruit, la préparation redevient un simple hachis de boudin aux oignons.','La pomme doit s''assouplir sans s''affaisser : trop cuite, elle s''ouvre en éventail et ne retient plus rien.','Le boyau se retire entièrement et la chair se grille nue : c''est cette accroche à la poêle qui rend au hachis ce que la cuisson au four lui retire.','Le poivre reste un assaisonnement de finition : la médiane du dossier est faussée par des pesées de boudin et ne doit jamais être appliquée telle quelle.']::text[],
    ARRAY['évidage','suer','grillade','farcissage','cuisson au four']::text[], ARRAY[]::text[], ARRAY['lait']::text[],
    'Se garde 48 h à 4 °C en boîte fermée, boudin et pommes séparés, et se réchauffe à la poêle sur feu doux ou au four à 140 °C. Congélation déconseillée : le boudin cuit relargue son gras et devient granuleux, les pommes s''affaissent en rendant leur eau.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-032'), '{"variant_label":"Pommes entières évidées, passées au four puis garnies du hachis de boudin grillé et d''oignons fondus (750g.com).","rationale":"La pomme cesse d''être une garniture pour devenir le contenant : évidée, cuite au four, puis remplie du boudin grillé, écrasé et mêlé aux oignons fondus. Il faut deux fois plus de fruit — quatre pommes entières au lieu de quatre pommes détaillées — et le boudin, grillé nu puis haché, perd sa forme de tronçon et une part de son gras dans la poêle. La cuisson est plus longue, le service plus délicat, et le sucré du fruit domine nettement plus l''assiette que dans la poêlée d''origine.","operations":[{"op":"set","form":"Pomme fraîche","quantity":640,"role":"contenant"}],"steps":[{"op":"replace","n":1,"instruction":"Choisissez quatre pommes à chair ferme d''environ 200 g pièce, soit 800 g de fruits entiers, qui donneront les 640 g de chair annoncés une fois le cœur ôté. Lavez-les sans les peler, retirez le trognon au vide-pomme en creusant jusqu''aux deux tiers de la hauteur sans percer le fond, élargissez la cavité à la petite cuillère et badigeonnez-la du jus de citron pour qu''elle ne noircisse pas."},{"op":"replace","n":3,"instruction":"Rangez les pommes debout dans un plat, poudrez l''intérieur des cavités du sucre, posez une noisette du beurre restant sur chacune et enfournez 25 minutes à 180 °C. Elles doivent s''assouplir sans s''affaisser : trop cuite, une pomme s''ouvre en éventail et ne retient plus rien."},{"op":"replace","n":4,"instruction":"Le boudin se vend en boyau : prévoyez quatre tronçons d''environ 150 g, soit près de 600 g sur la balance du charcutier, pour les 560 g de chair annoncés. Fendez le boyau, retirez-le entièrement, puis grillez la chair nue cinq minutes à la poêle bien chaude en l''écrasant à la fourchette, jusqu''à ce qu''elle accroche par endroits. Hachez-la grossièrement au couteau une fois tiède."},{"op":"replace","n":5,"instruction":"Mêlez le hachis de boudin grillé aux oignons fondus, salez, poivrez, puis garnissez-en les cavités en tassant à la cuillère et en laissant un dôme dépasser. Remettez au four 10 minutes à 180 °C, le temps que la farce chauffe à cœur et que le dessus se croûte légèrement."},{"op":"replace","n":6,"instruction":"Servez les pommes brûlantes dans leur plat, arrosées du jus caramélisé qui a coulé au fond et d''un dernier tour de moulin à poivre. Elles ne supportent pas d''être dressées à l''assiette sans se briser : mieux vaut porter le plat entier et laisser chacun s''en servir."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
