  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 1,2 kg de calamars entiers chez le poissonnier pour obtenir les 800 g de chair nettoyée de la recette. Tirer la tête et les viscères hors du manteau, retirer la plume transparente, faire glisser la membrane violacée sous un filet d''eau froide, puis sectionner les tentacules juste au-dessus des yeux en éliminant le bec corné. Détailler les corps en anneaux d''environ un centimètre et demi et éponger le tout longuement dans un linge : une chair humide bout au lieu de dorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fumer l''huile d''olive dans une cocotte à fond épais et y jeter les anneaux et les tentacules en deux fournées, sans jamais tasser le fond. Laisser accrocher deux à trois minutes par fournée en remuant peu, le temps que les bords se marquent. Débarrasser au fur et à mesure dans une passoire posée sur un bol et conserver le jus qui s''y écoule.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Baisser sous la cocotte, y verser l''oignon jaune et l''échalote finement ciselés et les laisser suer une bonne huitaine de minutes en grattant les sucs, jusqu''à transparence et sans qu''ils blondissent. Ajouter l''ail haché seulement dans la dernière minute pour qu''il reste parfumé plutôt qu''amer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre les calamars et leur jus dans la cocotte, monter le feu, verser le Cognac et l''enflammer en écartant le visage et en éteignant la hotte. Attendre que la flamme retombe d''elle-même, puis racler le fond à la cuillère en bois pour décoller ce qui a caramélisé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajouter le concentré de tomate et le laisser pincer une à deux minutes contre le fond chaud : il fonce et perd son acidité crue. Incorporer alors la tomate râpée, mouiller avec le vin blanc sec, saler, poivrer et poudrer du piment de Cayenne. Le liquide doit affleurer les calamars sans les noyer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et maintenir un frémissement paresseux pendant trente-cinq minutes environ, en remuant deux ou trois fois. Les anneaux se raffermissent d''abord puis se détendent : goûter à partir de la trentième minute et prolonger si la chair résiste encore sous la dent. Retirer ensuite le couvercle et laisser réduire un bon quart d''heure, cinq minutes de plus qu''à l''ordinaire — rien ne viendra lier la sauce à la fin, c''est l''évaporation seule qui doit l''amener à napper le dos d''une cuillère.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, rectifier le sel et le piment, puis laisser reposer cinq minutes hors du feu pour que les parfums se rassemblent. La sauce reste rouge et franche, sans rien pour en arrondir l''acidité : servir brûlant avec un riz blanc long, qui l''absorbe et adoucit ce que la réduction a resserré.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-034-D1', 'recipe_family', 'Calamars à l''armoricaine sans crème',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-034-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-034-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-034-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('0910f6620933c263e0cbf77e8c95834d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":3,"bitter":0,"umami":4,"heat":2,"pungency":2,"richness":3,"freshness":1,"intensity":4},"dominant_flavors":["tomate concentrée","iodé","ail","vin blanc"],"aroma_families":["marin","alliacé","vineux","eau-de-vie"],"target_textures":["anneaux tendres sous la dent","sauce nappante","oignons fondus"],"signature_ingredients":["Calamar cru nettoyé","Cognac","Concentré de tomate","Vin blanc sec"],"identity_guardrails":["Sans calamar, il n''y a plus de plat : c''est le mollusque, et non un poisson ou une autre chair, qui porte l''identité.","Le flambage au Cognac est constitutif de l''armoricaine ; le supprimer donne un simple calamar à la tomate.","La base doit rester tomate et vin blanc : une liaison crémeuse dominante bascule vers une autre recette.","La cuisson est longue et frémissante ; un passage rapide à la poêle laisse une chair caoutchouteuse et sort du registre du plat mijoté."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Carottes râpées à la marocaine', 'carottes rapees a la marocaine', 'France', 'France',
     'meal', 'salade', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Carottes râpées à la marocaine', 'Carottes râpées en vinaigrette à l''orange avec cumin et raisins secs', ds.id, 'SRC-035-D1',
    'Myko', 'editorial', 4, 20, 0, 'facile',
    NULL, NULL,
    'B', 'candidate', '7faff84799761b2a215dd969fad8bc80',
    '{"sweet":3,"salty":2,"acidic":4,"bitter":0,"umami":1,"heat":0,"pungency":2,"richness":2,"freshness":5,"intensity":2}'::jsonb, ARRAY['sucré végétal de la carotte crue','acidité vinaigrée','jus d''agrume']::text[],
    ARRAY['agrume','épices chaudes','végétal frais']::text[], ARRAY['croquant filamenteux','juteux','moelleux des raisins regonflés']::text[],
    ARRAY['Carotte crue','Orange fraîche','Moutarde de Dijon']::text[], ARRAY['La carotte reste crue et râpée : dès qu''elle est cuite, le plat cesse d''être des carottes râpées','L''assaisonnement est une vinaigrette acidulée montée à la moutarde, jamais une sauce crémeuse ou mayonnaise','Le jus d''agrume frais vient épauler le vinaigre, il ne le remplace pas par un sirop sucré','La râpe à gros trous fait la texture : une carotte réduite en purée ou en fins cheveux d''ange n''a plus le croquant attendu']::text[],
    ARRAY['émulsion','marinade']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites']::text[],
    'Se garde 48 heures au réfrigérateur entre 0 et 4 °C dans une boîte hermétique ; dès le deuxième jour la carotte rend son eau et s''assouplit, il faut alors l''égoutter et rectifier sel et acidité avant de servir. Ne se congèle pas : la décongélation ruine définitivement le croquant.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-035'), '{"variant_label":"Version marocaine : doubler le cumin et servir tiède les raisins secs regonflés dans le jus d''orange chaud","rationale":"Le cumin doublé passe d''arrière-plan à premier plan et la salade cesse d''être une simple crudité acidulée. Faire gonfler les raisins dans le jus d''orange chaud plutôt que dans l''eau leur donne le parfum de l''agrume et les rend indispensables : ils cessent d''être une garniture qu''on peut sauter, et passent de 15 à 30 g, car deux ou trois raisins par assiette ne feraient pas le service tiède que l''étiquette annonce. Le service tiède supprime le passage au froid, donc le temps de repos long, mais la salade ne se garde plus : elle se mange dans la demi-heure ou elle retombe.","operations":[{"op":"set","form":"Cumin moulu","quantity":4,"optional":false},{"op":"set","form":"Raisin sec","quantity":30,"optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Presser l''orange et faire tiédir son jus dans une petite casserole sans jamais le laisser bouillir, sous peine de lui donner un goût cuit. Y jeter les raisins secs hors du feu et les laisser gonfler dix minutes : ils boivent l''agrume au lieu de l''eau et en gardent le parfum. Les égoutter au-dessus du bol en réservant tout le jus."},{"op":"replace","n":4,"instruction":"Délayer la moutarde à la fourchette dans le jus d''orange encore tiède jusqu''à disparition des grumeaux, ajouter le vinaigre, puis verser l''huile en mince filet en fouettant, jusqu''à ce que la sauce épaississe et cesse de se séparer."},{"op":"replace","n":5,"instruction":"Saler, poivrer et incorporer les quatre grammes de cumin en deux fois, en goûtant entre les deux : doublée, l''épice doit se sentir franchement dès le bol, sans pour autant couvrir l''orange qui la porte."},{"op":"replace","n":7,"instruction":"Couvrir et laisser reposer un quart d''heure à température ambiante seulement, jamais au réfrigérateur : le froid figerait l''huile et refermerait le cumin, qui ne s''ouvre qu''à la chaleur. Remuer une dernière fois, rectifier le sel et servir tiède, les raisins encore chauds au milieu des carottes."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
