  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-035-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('7faff84799761b2a215dd969fad8bc80'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"bright_acidic","scores":{"sweet":3,"salty":2,"acidic":4,"bitter":0,"umami":1,"heat":0,"pungency":2,"richness":2,"freshness":5,"intensity":2},"dominant_flavors":["sucré végétal de la carotte crue","acidité vinaigrée","jus d''agrume"],"aroma_families":["agrume","épices chaudes","végétal frais"],"target_textures":["croquant filamenteux","juteux","moelleux des raisins regonflés"],"signature_ingredients":["Carotte crue","Orange fraîche","Moutarde de Dijon"],"identity_guardrails":["La carotte reste crue et râpée : dès qu''elle est cuite, le plat cesse d''être des carottes râpées","L''assaisonnement est une vinaigrette acidulée montée à la moutarde, jamais une sauce crémeuse ou mayonnaise","Le jus d''agrume frais vient épauler le vinaigre, il ne le remplace pas par un sirop sucré","La râpe à gros trous fait la texture : une carotte réduite en purée ou en fins cheveux d''ange n''a plus le croquant attendu"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
