  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Peler l''orange à vif au couteau au-dessus d''un bol pour ne rien perdre, puis glisser la lame le long de chaque membrane afin d''en détacher les suprêmes ; les réserver au frais sur une assiette. Presser à la main les membranes et le cœur restants au-dessus du bol : c''est ce jus, plus court que celui d''un fruit pressé entier, qui reçoit la moutarde délayée à la fourchette, puis le vinaigre, puis l''huile versée en mince filet et fouettée jusqu''à ce que la sauce épaississe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Saler, poivrer et incorporer le cumin à la vinaigrette, puis goûter : elle doit sembler un cran trop franche dans le bol, car l''eau des carottes va l''adoucir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
