  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Cassoulet aux deux saucisses', 'Cassoulet avec saucisse de Toulouse et saucisse de Montbéliard réunies', ds.id, 'SRC-036-D3',
    'Myko', 'editorial', 8, 45, 240, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'caefc7e0ed0d40bdde5461d328528006',
    '{"sweet":1,"salty":3,"acidic":1,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":0,"intensity":4}'::jsonb, ARRAY['gras de canard confit','porc rissolé','haricot fondant','ail cuit']::text[],
    ARRAY['carné rôti','herbacé sec','aillé','graisse fondue']::text[], ARRAY['haricot fondant à peau intacte','croûte de chapelure cassante','viande confite qui s''effiloche']::text[],
    ARRAY['Haricot blanc sec','Confit de canard cuit','Saucisse de Toulouse crue','Poitrine de porc crue']::text[], ARRAY['Sans haricot blanc sec trempé et cuit à part dans un bouillon de couenne, ce n''est plus un cassoulet mais un ragoût de charcuterie.','Le confit de canard et la saucisse de Toulouse portent l''identité toulousaine du plat : les remplacer par une viande maigre le fait basculer ailleurs.','La cuisson longue au four à découvert, avec la croûte enfoncée plusieurs fois, est constitutive : un mijotage à couvert sur le feu donne un autre plat.','Aucun liant à la farine ni crème : l''onctuosité vient de l''amidon des haricots et de la graisse de confit.']::text[],
    ARRAY['mijotage','saisie','blanchiment','rôtissage']::text[], ARRAY[]::text[], ARRAY['gluten','sulfites']::text[],
    'Se conserve 4 jours au réfrigérateur entre 0 et 4 °C, dans son plat couvert d''un film ; il gagne au réchauffage lent à 150 °C avec une louche de bouillon. Congélation possible 3 mois pour les haricots et les viandes, mais la croûte de chapelure ne la supporte pas : la refaire au four après décongélation complète au réfrigérateur.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-036'), '{"variant_label":"Ajout de Saucisse de Montbéliard pour une note fumée, à la place ou en complément de la saucisse de Toulouse.","rationale":"La Montbéliard cesse d''être facultative et passe de 200 à 350 g : le fumé traverse alors tout le plat au lieu de se cantonner à une cuillerée, et il tire le cassoulet vers l''est, loin du profil doux du Lauragais. La part gagne en viande et donc en lipides comme en sel, la Montbéliard étant déjà cuite et salée. C''est le prix d''un plat plus démonstratif, où le confit passe au second plan.","operations":[{"op":"set","form":"Saucisse de Montbéliard","quantity":350,"optional":false}],"steps":[{"op":"replace","n":5,"instruction":"Faites fondre la graisse de confit réservée dans une large sauteuse. Colorez-y la saucisse de Toulouse enroulée en escargot, puis la Montbéliard taillée en rondelles épaisses — deux minutes par face suffisent, elle est déjà cuite et fumée, et s''obstiner ne ferait que la dessécher —, puis les lardons de poitrine, enfin le porc haché roulé en petites boulettes serrées. Cherchez une belle teinte ambrée, jamais une croûte brûlée, et débarrassez au fur et à mesure."},{"op":"replace","n":8,"instruction":"Frottez d''ail cru l''intérieur d''une cassole ou d''une cocotte en terre, couchez la couenne au fond gras contre la paroi, puis montez par couches alternées : haricots, viandes rissolées, morceaux de confit, et les rondelles de Montbéliard semées une à une à chaque étage plutôt que groupées, faute de quoi le fumé resterait prisonnier d''une seule strate. Terminez par une couche de haricots et versez du bouillon jusqu''à effleurer la surface."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

