  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-037-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('2b398cb6cf8eabf28a5b60013daf439a'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":1,"heat":0,"pungency":3,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["moutarde","citron","céleri"],"aroma_families":["moutardé","agrume","herbacé"],"target_textures":["croquant","crémeux"],"signature_ingredients":["Céleri branche cru","Moutarde de Dijon","Jus de citron frais"],"identity_guardrails":["Le céleri reste cru et taillé en filaments : cuit ou réduit en purée, ce n''est plus une rémoulade.","La moutarde doit rester perceptible dans l''émulsion, c''est elle qui donne son mordant au nom du plat.","L''acidité du citron est structurelle, elle empêche l''oxydation et équilibre le gras de la sauce ; la supprimer donne une salade grise et lourde."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
