  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Choisir une boule de céleri-rave d''environ 800 g, le calibre courant chez le primeur, la brosser sous l''eau puis retirer au couteau la peau et les zones fibreuses ou creuses : il doit rester à peu près 600 g de chair nette, le parage emportant près d''un quart du poids acheté. Frotter aussitôt les faces mises à nu avec un filet de jus de citron pour qu''elles ne brunissent pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Râper la chair en filaments fins, à la mandoline ou au robot muni de la grille à râper. Arroser du reste de jus de citron, saler, mélanger à pleines mains et laisser reposer un quart d''heure : les filaments s''assouplissent et rendent un peu d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans un bol qui n''est pas sorti du froid, fouetter le jaune d''œuf avec la moutarde de Dijon jusqu''à obtenir une pâte lisse et homogène. Verser l''huile d''olive en filet mince sans cesser de fouetter, jusqu''à ce que l''émulsion se tienne au fouet, puis la détendre avec le vinaigre blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Assouplir cette base avec le yaourt nature, donner un tour de moulin à poivre et n''ajouter la pincée de sucre que si la moutarde domine trop. Rincer les câpres à l''eau froide pour les débarrasser de leur saumure, les éponger dans un linge et les hacher grossièrement au couteau — laissées entières, elles éclateraient par paquets sous la dent au lieu de se répartir —, puis les mêler à la sauce. Celle-ci doit napper le dos d''une cuillère sans couler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Presser le céleri râpé entre les paumes pour chasser l''eau de dégorgement, puis l''incorporer à la sauce en trois fois, en soulevant la masse à la fourchette pour enrober chaque filament sans l''écraser. Goûter avant de rectifier : le sel des câpres se réveille au repos et une main trop généreuse ici ne se rattrape plus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et laisser reposer au moins trente minutes au réfrigérateur, le temps que le céleri s''imprègne et que la sauce s''accroche. Au moment de servir, tailler la pomme en fins bâtonnets et la répartir sur le dessus avec le persil ciselé.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-037-D2', 'recipe_family', 'Céleri rémoulade aux câpres',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
