  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Choisir une boule de céleri-rave d''environ 800 g, le calibre courant chez le primeur, la brosser sous l''eau puis retirer au couteau la peau et les zones fibreuses ou creuses : il doit rester à peu près 600 g de chair nette, le parage emportant près d''un quart du poids acheté. Frotter aussitôt les faces mises à nu avec un filet de jus de citron pour qu''elles ne brunissent pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Râper la chair en filaments fins, à la mandoline ou au robot muni de la grille à râper. Arroser du reste de jus de citron, saler, mélanger à pleines mains et laisser reposer un quart d''heure : les filaments s''assouplissent et rendent un peu d''eau.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Dans un bol qui n''est pas sorti du froid, fouetter le jaune d''œuf avec la moutarde de Dijon jusqu''à obtenir une pâte lisse et homogène. Verser l''huile d''olive en filet mince sans cesser de fouetter, jusqu''à ce que l''émulsion se tienne au fouet, puis la détendre avec le vinaigre blanc.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Assouplir cette base avec le yaourt nature, donner un tour de moulin à poivre et ajouter la pincée de sucre seulement si la moutarde domine trop. La sauce doit napper le dos d''une cuillère sans couler.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Tailler la pomme en bâtonnets fins et les jeter aussitôt dans la sauce, dont l''acidité les gardera clairs. Presser le céleri râpé entre les paumes pour chasser l''eau de dégorgement, puis l''incorporer par-dessus en trois fois, en soulevant la masse à la fourchette pour enrober chaque filament sans l''écraser. Rectifier le sel et l''acidité en tenant compte du sucre de la pomme, qui arrondit tout et fait paraître la sauce plus douce qu''elle n''est.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et laisser reposer trente minutes au réfrigérateur, sans aller au-delà de deux heures : passé ce délai les bâtonnets rendent leur eau, s''amollissent et la rémoulade tourne à la compote. Au moment de servir, remuer une dernière fois et parsemer le persil ciselé.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-037-D3', 'recipe_family', 'Rémoulade de céleri à la pomme',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-037-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-037-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-037-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3cd0d8d199fa496527e668df44f4a535'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":1,"heat":0,"pungency":3,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["moutarde","citron","céleri"],"aroma_families":["moutardé","agrume","herbacé"],"target_textures":["croquant","crémeux"],"signature_ingredients":["Céleri branche cru","Moutarde de Dijon","Jus de citron frais"],"identity_guardrails":["Le céleri reste cru et taillé en filaments : cuit ou réduit en purée, ce n''est plus une rémoulade.","La moutarde doit rester perceptible dans l''émulsion, c''est elle qui donne son mordant au nom du plat.","L''acidité du citron est structurelle, elle empêche l''oxydation et équilibre le gras de la sauce ; la supprimer donne une salade grise et lourde."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Paupiettes de chou à la tomate', 'paupiettes de chou a la tomate', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Paupiettes de chou à la tomate', 'Feuilles de chou farcies d''un mélange bœuf-porc haché, mijotées dans une sauce tomate', ds.id, 'SRC-038-D1',
    'Myko', 'editorial', 6, 55, 90, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '4eec1a9fb30285b8e0e488995ad43e2f',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['viande braisée','chou fondant','bouillon de volaille','tomate cuite']::text[],
    ARRAY['végétal cuit','gras animal','aromates verts']::text[], ARRAY['feuilles fondantes','farce moelleuse et serrée','jus court et nappant']::text[],
    ARRAY['Chou vert frais','Bœuf haché cru 15 % MG','Porc haché cru','Poitrine de porc crue']::text[], ARRAY['Les feuilles de chou vert entières doivent envelopper la farce et le chou être reconstitué en boule : émincé et mélangé à la viande, ce n''est plus un chou farci mais une potée','La farce reste une viande hachée grasse liée à la mie de pain et à l''œuf ; sans le gras de la poitrine de porc elle se dessèche et le plat perd son moelleux','La cuisson est un mijotage long à couvert dans un mouillement court, pas un rôtissage à sec']::text[],
    ARRAY['blanchiment','mijotage','farcissage']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se gardent 3 jours au réfrigérateur entre 0 et 4 °C, rangés serrés dans leur jus et couverts ; réchauffer à couvert et à feu doux, jamais à gros bouillons. Congélation possible en paquets individuels jusqu''à 3 mois : plus petits qu''une tête entière, ils prennent et reprennent le froid bien mieux qu''elle, mais congeler le jus à part et le réduire au moment du service, sans quoi il ressort délavé.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-038'), '{"variant_label":"Chou farci en petits paquets : une boulette de farce par feuille blanchie, refermée en aumônière et mijotée dans la tomate râpée","rationale":"Le chou n''est plus reconstitué en boule mais divisé en paquets individuels, ce qui supprime la ficelle et rend le service immédiat : plus de découpe en quartiers qui s''effondrent. Chaque paquet cuit en une heure et quart au lieu de deux heures, mais la mise en place s''allonge d''un quart d''heure, feuille par feuille. La tomate passe de 400 à 700 g et le bouillon tombe à 250 ml, car les paquets doivent mijoter immergés aux deux tiers dans un jus court plutôt qu''être arrosés d''un liquide clair.","operations":[{"op":"set","form":"Tomate râpée","quantity":700},{"op":"set","form":"Bouillon de volaille","quantity":250}],"steps":[{"op":"replace","n":7,"instruction":"Écarter une à une les feuilles du chou tiédi en progressant de l''extérieur vers le centre, sans les déchirer : compter deux à trois grandes feuilles par convive. Aplatir au couteau la côte centrale de chacune, qui résiste sinon au pliage et fait craquer la feuille en deux. Détacher le cœur, trop serré pour être farci, le hacher menu et le mêler à la farce, qui gagne ainsi le goût du chou."},{"op":"replace","n":8,"instruction":"Déposer au creux de chaque feuille une boulette de farce de la taille d''un gros œuf, rabattre la base sur elle, puis les deux côtés, et rouler jusqu''au bout pour fermer le paquet. Poser chacun soudure en dessous : le poids de la farce suffit alors à le tenir clos, et rien ne s''ouvrira à la cuisson."},{"op":"remove","n":9},{"op":"replace","n":10,"instruction":"Beurrer largement le fond d''une cocotte ou d''un large sautoir, y étaler les lamelles d''oignon et les rondelles de carotte en lit régulier, puis ranger les paquets dessus côte à côte et bien serrés, de façon qu''ils s''épaulent les uns les autres. Verser la tomate râpée et le bouillon de volaille le long des parois jusqu''à les immerger aux deux tiers, jamais davantage : le dessus doit rester au-dessus du jus."},{"op":"replace","n":11,"instruction":"Amener à frémissement à découvert, couvrir, puis tenir le feu au plus bas une heure et quart. Des paquets de la taille du poing cuisent bien plus vite qu''une tête entière : passé ce temps, la feuille cède sous la cuillère et la farce est prise à cœur. Arroser deux ou trois fois du jus en cours de route et vérifier que rien n''accroche au fond."},{"op":"replace","n":12,"instruction":"Laisser reposer dix minutes hors du feu, le temps que la farce se raffermisse et que les paquets se laissent soulever entiers à la spatule. Servir deux ou trois par assiette, nappés de la tomate réduite au fond de la cocotte."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

