DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de chou-fleur au curry', 'gratin de chou fleur au curry', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gratin de chou-fleur au curry', 'Chou-fleur blanchi dans une béchamel parfumée au curry, gratinée au gruyère', ds.id, 'SRC-041-D2',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '180a356acf85331a0dd6cf9bb36cfc2f',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté crémeux','curry doux','légume crucifère doux']::text[],
    ARRAY['lacté','épices douces','curcuma et coriandre']::text[], ARRAY['bouquets fondants','sauce nappante','croûte gratinée']::text[],
    ARRAY['Chou-fleur frais','Gruyère râpé','Lait entier','Curry en poudre']::text[], ARRAY['Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.','Le curry se fouette hors du feu et au dernier moment : cuit avec la sauce il devient amer et la sauce grise.','La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel.']::text[],
    ARRAY['blanchiment','gratinage']::text[], ARRAY[]::text[], ARRAY['gluten','lait']::text[],
    'Se conserve trois jours au réfrigérateur entre 0 et 4 °C, plat couvert d''un film une fois refroidi. Réchauffer vingt minutes à 160 °C plutôt qu''au micro-ondes, pour retrouver la croûte. La congélation est déconseillée : le chou-fleur relâche son eau et la béchamel tranche à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-041'), '{"variant_label":"Version au curry de chefsimon : fouetter une petite cuillerée de curry en poudre dans la béchamel juste avant de napper, en rallongeant d''un peu de lait si la sauce s''épaissit trop.","rationale":"Quatre grammes de curry suffisent à colorer la sauce et à poser une chaleur douce derrière le lacté, sans que le chou-fleur disparaisse dessous. Le mélange contient de l''amidon et de la fécule : il resserre la béchamel, d''où les cinquante millilitres de lait tenus en réserve. Ajouté trop tôt ou cuit longuement, il vire à l''amer et grise la sauce — c''est le seul vrai risque de la variante.","operations":[{"op":"add","form":"Curry en poudre","quantity":4,"unit":"g","role":"épice","optional":false},{"op":"set","form":"Lait entier","quantity":550,"role":"liquide de sauce"}],"steps":[{"op":"replace","n":4,"instruction":"Faire fondre le reste du beurre à feu doux dans une casserole, verser la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse sans colorer. Retirer du feu quelques secondes, puis incorporer 500 ml de lait tiédi en trois fois, en fouettant à chaque ajout pour éviter les grumeaux. Garder les 50 ml restants de côté : ils serviront peut-être en fin de sauce."},{"op":"replace","n":5,"instruction":"Remettre sur feu doux et laisser épaissir cinq à six minutes en fouettant sans arrêt, jusqu''à ce que la sauce nappe la spatule. La détendre avec la crème, puis avec le lait réservé si elle s''est trop resserrée. Saler, poivrer, râper la muscade, fouetter hors du feu un tiers du gruyère, et n''incorporer le curry en poudre qu''en tout dernier, juste avant de napper : longuement cuit il tourne à l''amer et grise, jeté au dernier moment il garde son parfum entier."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

