  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir un chou-fleur entier d''environ 1,2 kg chez le primeur : une fois les grosses feuilles retirées et le trognon éliminé, il reste à peu près les 650 g de bouquets utiles. Détacher ces bouquets à la main en gardant une taille régulière, de la grosseur d''une grosse noix, puis les rincer à l''eau froide et les laisser s''égoutter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Plonger les bouquets dans un grand volume d''eau salée en pleine ébullition et les laisser huit à dix minutes. La pointe d''un couteau doit traverser la tige sans résistance mais le bouquet doit rester ferme : trop cuit, il s''affaissera au four. Égoutter aussitôt et laisser reposer dans la passoire, bouquets retournés, le temps que l''eau s''écoule complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Allumer le four à 200 °C en chaleur tournante. Prélever une noisette sur le beurre pour graisser généreusement le fond et les bords d''un plat à gratin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le reste du beurre à feu doux dans une casserole, verser la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse sans colorer. Retirer du feu quelques secondes, puis incorporer 500 ml de lait tiédi en trois fois, en fouettant à chaque ajout pour éviter les grumeaux. Garder les 50 ml restants de côté : ils serviront peut-être en fin de sauce.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre sur feu doux et laisser épaissir cinq à six minutes en fouettant sans arrêt, jusqu''à ce que la sauce nappe la spatule. La détendre avec la crème, puis avec le lait réservé si elle s''est trop resserrée. Saler, poivrer, râper la muscade, fouetter hors du feu un tiers du gruyère, et n''incorporer le curry en poudre qu''en tout dernier, juste avant de napper : longuement cuit il tourne à l''amer et grise, jeté au dernier moment il garde son parfum entier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler une louche de sauce au fond du plat beurré, ranger les bouquets serrés et tête vers le bas afin que la sauce s''infiltre entre les fleurettes, puis napper du reste de sauce jusqu''à recouvrir les sommets.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répartir le gruyère restant sur toute la surface et enfourner trente minutes à mi-hauteur. Si le dessus manque de couleur, terminer cinq minutes sous le gril en surveillant. Laisser reposer le plat cinq minutes avant de servir, le temps que la sauce se raffermisse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-041-D2', 'recipe_family', 'Gratin de chou-fleur au curry',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-041-D2', 'missing_required_count', v_missing), 'open');
  END IF;

