    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-041-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('180a356acf85331a0dd6cf9bb36cfc2f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":1,"pungency":2,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["lacté crémeux","curry doux","légume crucifère doux"],"aroma_families":["lacté","épices douces","curcuma et coriandre"],"target_textures":["bouquets fondants","sauce nappante","croûte gratinée"],"signature_ingredients":["Chou-fleur frais","Gruyère râpé","Lait entier","Curry en poudre"],"identity_guardrails":["Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.","Le curry se fouette hors du feu et au dernier moment : cuit avec la sauce il devient amer et la sauce grise.","La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
