  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir un chou-fleur entier d''environ 1,2 kg chez le primeur : une fois les grosses feuilles retirées et le trognon éliminé, il reste à peu près les 650 g de bouquets utiles. Détacher ces bouquets à la main en gardant une taille régulière, de la grosseur d''une grosse noix, puis les rincer à l''eau froide et les laisser s''égoutter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Plonger les bouquets dans un grand volume d''eau salée en pleine ébullition et les laisser huit à dix minutes. La pointe d''un couteau doit traverser la tige sans résistance mais le bouquet doit rester ferme : trop cuit, il s''affaissera au four. Égoutter aussitôt et laisser reposer dans la passoire, bouquets retournés, le temps que l''eau s''écoule complètement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Allumer le four à 200 °C en chaleur tournante. Prélever une noisette sur le beurre pour graisser généreusement le fond et les bords d''un plat à gratin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le reste du beurre à feu doux dans une casserole et y laisser blondir l''oignon jaune finement émincé huit à dix minutes, en remuant : il doit devenir translucide puis prendre juste une teinte de miel, sans jamais brunir, faute de quoi la sauce entière tirerait sur l''amer. Verser alors la farine d''un coup et remuer une bonne minute jusqu''à ce que le mélange mousse. Retirer du feu quelques secondes, puis incorporer le lait tiédi en trois fois, en fouettant à chaque ajout pour éviter les grumeaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Remettre sur feu doux et laisser épaissir cinq à six minutes en fouettant sans arrêt, jusqu''à ce que la sauce nappe la spatule. Détendre avec la crème, saler, poivrer, râper la muscade, puis fouetter hors du feu un tiers du gruyère pour qu''il fonde dans la sauce encore chaude.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Étaler une louche de sauce au fond du plat beurré, ranger les bouquets serrés et tête vers le bas afin que la sauce s''infiltre entre les fleurettes, puis napper du reste de sauce jusqu''à recouvrir les sommets.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Répartir le gruyère restant sur toute la surface et enfourner trente minutes à mi-hauteur. Si le dessus manque de couleur, terminer cinq minutes sous le gril en surveillant. Laisser reposer le plat cinq minutes avant de servir, le temps que la sauce se raffermisse.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-041-D3', 'recipe_family', 'Gratin de chou-fleur à l''oignon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-041-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-041-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-041-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('a6fd2efe7a73c8800d001b96388b94d7'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":0,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["lacté crémeux","oignon fondu","fromage affiné"],"aroma_families":["lacté","alliacé","épices douces"],"target_textures":["bouquets fondants","sauce nappante piquée d''oignon","croûte gratinée"],"signature_ingredients":["Chou-fleur frais","Gruyère râpé","Lait entier"],"identity_guardrails":["Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.","L''oignon doit blondir et non brunir : coloré trop loin, il emporte toute la sauce vers l''amer et annule le bénéfice de la variante.","La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Gratin de chou-fleur aux noix', 'gratin de chou fleur aux noix', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Gratin de chou-fleur aux noix', 'Chou-fleur blanchi dans une béchamel crémeuse avec des noix concassées, gratiné', ds.id, 'SRC-041-D4',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '2b55e4ecbf3b5f8e52d567850ff3b959',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":2,"umami":3,"heat":0,"pungency":1,"richness":5,"freshness":1,"intensity":3}'::jsonb, ARRAY['lacté crémeux','fromage affiné','noix grillée']::text[],
    ARRAY['lacté','beurré','fruit à coque torréfié']::text[], ARRAY['bouquets fondants','sauce nappante','éclats de noix craquants']::text[],
    ARRAY['Chou-fleur frais','Gruyère râpé','Lait entier']::text[], ARRAY['Les bouquets de chou-fleur doivent rester entiers et identifiables sous la sauce : réduits en purée, le plat devient un flan de légume et non un gratin.','Les noix n''entrent au four que pour les cinq dernières minutes : enfournées d''emblée, leur huile brûle et l''amertume gagne tout le plat.','La couche de fromage gratinée en surface est obligatoire : sans croûte dorée, il ne reste qu''un chou-fleur à la béchamel.']::text[],
    ARRAY['blanchiment','gratinage']::text[], ARRAY[]::text[], ARRAY['gluten','lait','fruits à coque']::text[],
    'Se conserve trois jours au réfrigérateur entre 0 et 4 °C, plat couvert d''un film une fois refroidi. Réchauffer vingt minutes à 160 °C plutôt qu''au micro-ondes ; les noix, elles, ne retrouveront pas leur croquant et auront ramolli dans la sauce — mieux vaut en garder une part à concasser au moment de la seconde table. La congélation est déconseillée : le chou-fleur relâche son eau, la béchamel tranche à la décongélation et les noix deviennent pâteuses.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-041'), '{"variant_label":"Version croquante : parsemer une poignée de noix grossièrement concassées avec le fromage du dessus, à ajouter en fin de cuisson pour qu''elles ne brûlent pas.","rationale":"Les noix donnent au gratin le contraste de texture qui lui manque, tout en fondu et en croûte molle, et leur amertume légère répond bien au gruyère. Elles ajoutent en revanche cinquante grammes d''un aliment à près de sept cents kilocalories aux cent grammes, ce qui pèse davantage que la poignée ne le laisse croire. Elles imposent aussi de fractionner la cuisson au four et interdisent le réchauffage prolongé, qui les ramollit sans retour.","operations":[{"op":"add","form":"Noix","quantity":50,"unit":"g","role":"garniture croquante","optional":false}],"steps":[{"op":"replace","n":7,"instruction":"Répartir le gruyère restant sur toute la surface et enfourner vingt-cinq minutes à mi-hauteur. Concasser pendant ce temps les noix grossièrement au couteau, en gros éclats plutôt qu''en poudre, les parsemer sur le gratin et remettre au four cinq minutes seulement : au-delà leur huile chauffe et elles tournent à l''amer. Si le dessus manque de couleur, terminer deux minutes sous le gril en surveillant, puis laisser reposer cinq minutes avant de servir."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
