DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Lentilles au lard à l''huile d''olive', 'lentilles au lard a l huile d olive', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Lentilles au lard à l''huile d''olive', 'Lentilles vertes et lardons cuits à l''huile d''olive, assaisonnés au poivre noir en finition', ds.id, 'SRC-042-D3',
    'Myko', 'editorial', 4, 20, 40, 'facile',
    NULL, NULL,
    'B', 'candidate', '4bd3b2b9d3ec41b329b94b500b5bed75',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['fumé','terreux','huile d''olive fruitée']::text[],
    ARRAY['fumé','herbacé sec','végétal cuit']::text[], ARRAY['lentille fondante restée entière','lardon doré aux arêtes croustillantes','jus court et lustré']::text[],
    ARRAY['Lentille verte sèche, crue','Lardon fumé cru','Thym séché']::text[], ARRAY['Sans lardon fumé, il ne reste que des lentilles mijotées : le fumé du porc est la moitié du nom du plat','Les grains doivent tenir entiers ; passés au mixeur, le plat bascule en velouté et change d''identité','L''huile de finition se verse hors du feu et à cru : chauffée, elle ne lustre plus rien et le plat perd le seul relief qui remplace la crème']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte fermée ; les lentilles boivent leur jus en refroidissant, rallonger d''un fond d''eau à la réchauffe douce. Refaire le filet d''huile crue et le persil à l''assiette : ceux de la veille ont perdu leur parfum dans le froid. Sans crème, la congélation ne pose aucun problème — deux mois sans que rien ne tranche au dégel.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-042'), '{"variant_label":"Sans crème, simplement lustrée d''un filet d''huile d''olive crue et relevée de persil et d''un tour de moulin","rationale":"Sans crème, le jus reste court et franc : le fumé du lard et le terreux de la lentille passent devant, sans le voile lacté qui les arrondissait. Les douze grammes d''huile crue versés hors du feu lustrent les grains et portent les arômes, mais ne lient rien — le plat est plus liquide, et il faut le servir dans une assiette creuse. Le persil cesse d''être facultatif : c''est lui, avec le poivre, qui apporte la fraîcheur que la crème donnait autrement.","operations":[{"op":"remove","form":"Crème fraîche liquide entière"},{"op":"set","form":"Huile d''olive vierge extra","quantity":40,"role":"matière grasse"},{"op":"set","form":"Persil frais","quantity":15,"role":"herbe","optional":false},{"op":"set","form":"Poivre noir moulu","quantity":2,"role":"assaisonnement","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Remettre la cocotte sur feu moyen avec 28 g de l''huile d''olive, les 12 g restants étant tenus de côté pour la fin, et y faire fondre carotte, oignon et échalote sans les brunir, une bonne poignée de minutes, jusqu''à ce qu''ils deviennent translucides. Ajouter l''ail haché et poursuivre trente secondes, le temps qu''il embaume."},{"op":"replace","n":7,"instruction":"Goûter un grain : il doit céder sous la dent tout en gardant sa forme. Retirer alors le laurier et les clous de girofle, saler enfin et donner un tour de moulin franc. Verser hors du feu l''huile d''olive réservée, à cru, en remuant une seule fois : chauffée, elle perdrait le fruité qui fait tout l''intérêt du geste. Parsemer largement de persil ciselé au moment de porter à table."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
