  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Compter 3 kg de moules en coquille chez le poissonnier pour obtenir les 900 g de chair de la recette. Les trier une à une : écarter les coquilles brisées et celles qui restent béantes après une pression du doigt.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Arracher le byssus de chaque moule en tirant vers la charnière, gratter au couteau les concrétions accrochées à la coquille, puis laver en deux eaux froides successives en frottant les moules entre les paumes. Égoutter et réserver au réfrigérateur jusqu''à la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Peler et ciseler finement l''oignon. Écraser les gousses d''ail sous une lame plate puis les hacher. Tailler le céleri en dés minuscules. Laver le persil, l''effeuiller et le hacher grossièrement ; le garder de côté.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le beurre à feu doux dans une grande marmite. Y laisser fondre l''oignon, l''ail et le céleri pendant 4 à 5 minutes en remuant, sans jamais leur laisser prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mouiller avec le cidre brut, pousser le feu et laisser bouillonner trois minutes à découvert, une de plus qu''à l''ordinaire : le cidre porte toujours un reste de sucre qu''il faut cuire, sans quoi le bouillon garderait un goût de pomme crue au lieu du fond rond que l''on cherche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Verser toutes les moules d''un seul coup dans le liquide en pleine ébullition, couvrir aussitôt et laisser 5 à 7 minutes à feu vif. Soulever le couvercle deux ou trois fois pour retourner délicatement les coquilles à l''écumoire, sans arracher la chair de sa nacre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu dès que la quasi-totalité des coquilles est ouverte : une minute de trop rétracte et durcit la chair. Retirer les rares moules restées closes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Disperser le persil haché, donner un tour de poivre et mélanger une dernière fois avec précaution. Goûter le jus avant d''ajouter du sel : l''eau de mer rendue par les moules suffit le plus souvent, et comme le cidre a posé sa douceur sur l''ensemble, c''est plutôt un second tour de poivre qui remet le jus d''aplomb.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Servir sans attendre, directement dans la marmite ou réparti en assiettes creuses, en arrosant chaque part de son jus de cuisson brûlant.');

