    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-044-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('68b7efdabe1f3f6b08259f46193ea1a3'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":2,"salty":4,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":3,"freshness":3,"intensity":3},"dominant_flavors":["iodé","cidre fruité","aillé","beurré"],"aroma_families":["marin","alliacé","herbacé","pomme"],"target_textures":["chair tendre et charnue","jus court et fluide"],"signature_ingredients":["Moule commune crue","Cidre brut","Persil frais"],"identity_guardrails":["Sans moules fraîches cuites dans leur coquille, le plat n''existe plus : la chair préparée à part ou décoquillée à l''avance perd le jus qui fait la marinière","Le mouillement doit rester un cidre brut, jamais un cidre doux ni un jus de pomme : le sucre d''un cidre demi-sec confit le jus et le fait basculer du côté du dessert","Le jus ne se sale pas d''avance : l''eau de mer relâchée par les coquillages est l''assaisonnement principal","Le persil s''ajoute cru en fin de cuisson, jamais cuit avec les aromates"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
