  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Demander au boucher quatre tranches de jarret de veau d''environ 280 g pièce, coupées épais et gardées sur l''os : cela représente à peu près 1,1 kg sur la balance, pour environ 800 g de viande une fois l''os central déduit. Éponger les tranches, puis entailler en trois ou quatre endroits la membrane qui les ceinture, sans quoi elles se recroquevillent à la chaleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Saler et poivrer les deux faces, puis les rouler dans la farine et tapoter pour ne garder qu''un voile. Faire chauffer l''huile d''olive avec le beurre dans une cocotte à fond épais et y coucher les tranches à plat, sans qu''elles se touchent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Colorer à feu moyen deux à trois minutes par face, jusqu''à une croûte franchement dorée, puis débarrasser sur une assiette en posant les morceaux os vers le haut pour que la moelle reste en place.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Détailler en petits dés réguliers les trois légumes aromatiques — carotte, céleri, puis oignon — et les verser dans la cocotte encore grasse avec l''ail écrasé. Les laisser fondre huit minutes à feu doux en raclant le fond pour décoller les sucs, sans chercher à les colorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser le vin blanc, remonter le feu et laisser bouillonner jusqu''à ce que l''odeur d''alcool ait disparu et que le liquide ait diminué de moitié.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Écraser les tomates pelées à la fourchette et les ajouter avec leur jus, puis le concentré, le bouillon, le thym et les feuilles de laurier. Remettre les tranches à plat dans la cocotte, os vers le haut, et les arroser : le liquide doit affleurer la viande sans la noyer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Pendant que la cocotte prend son frémissement, parer le pied terreux des champignons et les essuyer au linge humide plutôt que de les passer sous l''eau, qu''ils boiraient pour la rendre ensuite dans la sauce. Les émincer en lamelles d''environ trois millimètres et les réserver à couvert.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Couvrir, régler sur un frémissement à peine visible et compter une heure et demie. Retourner les tranches à mi-parcours et ajouter un fond d''eau chaude si la sauce attache. Vingt minutes avant la fin, glisser les lamelles de champignon autour de la viande et remettre le couvercle : ce délai leur suffit pour rendre leur eau et prendre le goût du jus, là où une heure entière les réduirait en filaments. La viande est prête lorsqu''une fourchette la sépare de l''os sans effort.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Pendant ce temps, hacher très finement le persil avec une gousse d''ail réservée et le zeste de citron, puis garder ce mélange cru et à couvert jusqu''au service.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Retirer les tranches et les tenir au chaud, ôter le laurier et les branches de thym, puis faire réduire la sauce à découvert quelques minutes si elle reste trop fluide. Goûter, rectifier le sel, napper la viande et parsemer la gremolata au tout dernier moment, hors du feu.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-045-D4', 'recipe_family', 'Osso buco aux champignons',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-045-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-045-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-045-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f188207013aaccf58fcd89d686086a7d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["veau braisé","tomate cuite longuement","vin blanc réduit","zeste de citron"],"aroma_families":["agrume","aromates séchés","légumes racines fondus"],"target_textures":["viande fondante se détachant de l''os","sauce nappante","moelle onctueuse"],"signature_ingredients":["Jarret de veau cru, en tranches avec os","Vin blanc sec","Tomate entière pelée en conserve","Zeste de citron"],"identity_guardrails":["Le veau doit rester en tranches épaisses avec l''os et sa moelle : désossé, ou remplacé par un autre morceau, ce n''est plus un osso buco.","Le mouillement se fait au vin blanc sec et jamais au vin rouge, sinon la sauce vire au ragoût et perd son acidité claire.","La gremolata, persil et ail et zeste de citron hachés, s''ajoute crue au moment de servir : cuite, elle disparaît et le plat perd son relief.","La cuisson est longue, à couvert et à frémissement : un feu vif raccourcit le temps mais laisse la viande ferme et attachée à l''os."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Parmigiana bianca d''aubergines', 'parmigiana bianca d aubergines', 'Italie', 'Italie',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Parmigiana bianca d''aubergines', 'Aubergines panées et saisies, montées sans tomate avec mozzarella, parmesan et basilic', ds.id, 'SRC-046-D1',
    'Myko', 'editorial', 4, 25, 45, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '0c36181be4e2c151ccb9c2a2cfebfbc8',
    '{"sweet":1,"salty":4,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":2,"intensity":3}'::jsonb, ARRAY['fromage affiné','aubergine dorée','ail et basilic à l''huile']::text[],
    ARRAY['herbacé','lacté','végétal grillé']::text[], ARRAY['fondant','filant','croûte gratinée']::text[],
    ARRAY['Aubergine fraîche','Mozzarella','Parmesan affiné','Basilic frais']::text[], ARRAY['Les aubergines doivent être dégorgées puis dorées avant montage : montées crues, le plat rend de l''eau et cesse d''être une parmigiana.','Le duo mozzarella fondante et parmesan affiné est obligatoire ; un seul fromage, ou un fromage à gratin neutre, casse l''identité du plat.','Ni béchamel ni pâtes : sans sauce, la structure ne repose plus que sur les tranches d''aubergine tassées et sur le fromage fondu, et toute crème ajoutée pour « lier » ferait un gratin dauphinois d''aubergines.','L''huile d''ail et de basilic est le seul assaisonnement des étages : elle se goûte et se corrige avant montage, car rien ne la rattrape au four.']::text[],
    ARRAY['dégorgement','panure','saisie','montage en couches','gratinage']::text[], ARRAY[]::text[], ARRAY['lait','gluten','œuf']::text[],
    'Se garde 3 jours au réfrigérateur à 4 °C dans son plat filmé, et gagne même en tenue le lendemain ; réchauffer 20 minutes à 160 °C plutôt qu''au micro-ondes. La congélation est possible une fois le plat cuit et refroidi, jusqu''à 2 mois, mais la mozzarella relâche de l''eau à la décongélation et la croûte de chapelure ramollit : repasser sous le gril quelques minutes. Ne jamais recongeler une part déjà décongelée.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-046'), '{"variant_label":"Parmigiana bianca : on supprime la tomate et on monte les aubergines dorées avec seulement les deux fromages et le basilic.","rationale":"Privée de sauce, la parmigiana perd son acidité et son liant : ce sont les fromages qui doivent tenir les étages, d''où la mozzarella portée de 250 à 400 g et le parmesan de 50 à 90 g, et une huile d''ail et de basilic qui remplace la sauce dans le rôle de porteuse de goût. L''oignon et le laurier, qui n''existaient que pour la sauce, disparaissent avec elle. On s''épargne la demi-heure de réduction de la pulpe, mais elle se menait de front avec la friture des tranches : le temps de cuisson ne baisse que de cinq minutes. Le plat devient franchement plus riche et plus court en bouche : rien n''y relance le palais d''une bouchée à l''autre, et il faut saler et poivrer l''huile parfumée plus nettement qu''on ne salait la sauce.","operations":[{"op":"remove","form":"Tomate fraîche mûre"},{"op":"remove","form":"Oignon jaune cru"},{"op":"remove","form":"Feuille de laurier séchée"},{"op":"set","form":"Mozzarella","quantity":400},{"op":"set","form":"Parmesan affiné","quantity":90},{"op":"set","form":"Basilic frais","quantity":20}],"steps":[{"op":"remove","n":3},{"op":"replace","n":4,"instruction":"Pendant ce temps, pelez et dégermez l''ail, hachez-le au plus fin et mêlez-le dans un bol à la moitié du basilic ciselé, à un tiers de l''huile d''olive, une pincée de sel et un tour de poivre. Cette huile parfumée tient ici le rôle que tenait la sauce : c''est elle seule qui portera le goût entre les étages, alors goûtez-la et corrigez-la maintenant, rien ne viendra la rattraper au four."},{"op":"replace","n":7,"instruction":"Préchauffez le four à 190 °C. Huilez le fond d''un plat à gratin au pinceau, couchez une première rangée de tranches côte à côte, arrosez-les d''un filet d''huile au basilic, puis parsemez de mozzarella coupée en dés et d''un peu de parmesan râpé. Répétez l''opération en croisant le sens des tranches à chaque étage, jusqu''à épuisement, en tassant légèrement de la paume : sans liquide entre les couches, c''est la pression qui fait tenir le plat."},{"op":"replace","n":8,"instruction":"Terminez par le reste de mozzarella, le reste du parmesan et la chapelure réservée, puis enfournez 30 à 35 minutes. Sans pulpe pour humidifier le dessus, la surface colore beaucoup plus vite : surveillez-la dès la vingtième minute et couvrez d''aluminium dès qu''elle est prise."},{"op":"replace","n":9,"instruction":"Sortez le plat et laissez-le reposer au moins 15 minutes avant de le découper, le temps que le fromage cesse de couler et que les étages se ressoudent. Parsemez le basilic restant, ciselé au dernier instant, pour garder son parfum."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

