  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Les 400 g indiqués sont du grain net, prêt à cuire. Avec des pois surgelés, sortez simplement le sachet du congélateur : nul besoin de les décongeler. Si vous partez de pois frais, prévoyez environ 1,1 kg de cosses à l''achat, le rendement en grains tournant autour de 35 %, et écossez-les juste avant de cuisiner.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Débarrassez deux petites laitues d''environ 300 g pièce de leurs feuilles extérieures flétries et de leur pied dur : il doit vous rester à peu près 200 g de feuilles nettes. Rincez-les à l''eau froide, essorez-les soigneusement puis taillez-les en larges rubans.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pelez l''oignon blanc et débitez-le en lamelles très fines. Dégermez la gousse d''ail et hachez-la menu. Ciselez le cerfeuil et réservez-le à couvert, il n''interviendra qu''à la toute fin.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Épongez les cuisses de poulet avec un papier absorbant et salez la peau. Posez-les côté peau dans une poêle bien chaude, sans matière grasse ajoutée : elles en portent assez pour se suffire. Laissez-les six à sept minutes sans y toucher, jusqu''à ce que la peau soit dorée et se détache seule du fond. Réservez-les et versez la graisse rendue dans la cocotte, où elle remplacera une part du beurre du départ.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faites tiédir un tiers du beurre dans une cocotte à fond épais, à feu très doux. Jetez-y les lardons et laissez-les rendre leur graisse cinq minutes sans qu''ils prennent couleur, puis ajoutez l''oignon et l''ail et prolongez cinq minutes : l''oignon doit devenir translucide, jamais doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Versez les petits pois encore glacés par-dessus, puis les rubans de laitue, le sucre, le sel et le poivre blanc. Couchez les morceaux de volaille sur ce lit, peau vers le haut, en les enfonçant à peine — s''ils s''immergent, la peau que vous venez de colorer se détrempe. Mouillez de 15 cl d''eau, à peine plus que dans la version en légume seul : la cuisson est deux fois plus longue, mais la viande rendra son propre jus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couvrez, ramenez à léger frémissement et laissez aller cinquante minutes à petit feu, en secouant la cocotte par son anse toutes les dix minutes plutôt qu''en remuant. La chair doit se détacher de l''os sans résistance quand on la pousse du dos d''une cuillère. Les pois auront alors largement dépassé le fondant : c''est le prix du plat unique, et il ne sert à rien de raccourcir, une volaille à l''os ne se négocie pas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Sortez les morceaux de volaille et tenez-les au chaud sous une feuille d''aluminium. Découvrez et montez le feu deux à trois minutes pour faire partir l''excédent de liquide, plus abondant qu''à l''ordinaire, jusqu''à ce qu''il ne reste qu''un fond sirupeux au niveau des légumes. Coupez le feu et incorporez le beurre restant, très froid et coupé en dés, en imprimant à la cocotte un mouvement circulaire : le jus s''épaissit et se met à napper.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Rectifiez le sel — le jus de volaille en a concentré une partie, goûtez avant d''en remettre —, reposez la viande sur les légumes, parsemez le cerfeuil ciselé au dernier moment et servez aussitôt dans un plat creux, une part de volaille par assiette avec sa portion de légumes et tout le jus par-dessus.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-047-D4', 'recipe_family', 'Poulet aux petits pois à la française',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-047-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-047-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-047-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('4349ce5bdf018f1b2a3563f4da79d053'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"fresh_herbal","scores":{"sweet":3,"salty":2,"acidic":0,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2},"dominant_flavors":["douceur végétale du petit pois","beurre frais","oignon fondu"],"aroma_families":["végétal frais","lacté beurré","herbacé anisé"],"target_textures":["petit pois fondant qui garde sa peau","laitue tombée et soyeuse","jus court et nappant"],"signature_ingredients":["Petit pois surgelé","Laitue fraîche","Beurre doux"],"identity_guardrails":["Sans la laitue braisée avec les pois, ce ne sont plus des petits pois à la française mais de simples petits pois au beurre.","Le mouillement doit rester un fond d''eau réduit en jus court et monté au beurre : noyer les légumes dans du bouillon fait perdre au plat sa concentration sucrée.","Ni crème ni farine : la liaison vient uniquement du beurre froid incorporé hors du feu."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Piperade au jambon de Bayonne', 'piperade au jambon de bayonne', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Piperade au jambon de Bayonne', 'Compotée de poivrons et tomates au piment d''Espelette avec œufs brouillés et jambon de Bayonne', ds.id, 'SRC-048-D1',
    'Myko', 'editorial', 4, 25, 32, 'facile',
    NULL, NULL,
    'B', 'candidate', '56fb9141f10b95ba5221674a851cf49a',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['poivron doux confit','tomate mûre','ail','piment doux']::text[],
    ARRAY['végétal cuit','fruité','épicé doux']::text[], ARRAY['fondant','nappant','moelleux']::text[],
    ARRAY['Poivron rouge frais','Tomate râpée','Piment d''Espelette moulu']::text[], ARRAY['Le poivron rouge fondu longuement à l''huile d''olive est la base du plat : sans lui il ne reste qu''une sauce tomate aux œufs.','Le piment d''Espelette signe l''origine basque ; le remplacer par un piment fort ou par du paprika déplace le plat hors de son identité.','Les légumes doivent être menés jusqu''à la fondue, ni laissés croquants ni réduits en purée mixée.','Les œufs sont brouillés dans les légumes et restent crémeux : cuits en omelette prise à part, ce n''est plus une piperade.']::text[],
    ARRAY['mijotage','réduction']::text[], ARRAY[]::text[], ARRAY['œuf']::text[],
    'La fondue de légumes seule se garde 4 jours au réfrigérateur à 4 °C dans un contenant fermé et se congèle très bien 3 mois, sa texture ne souffrant pas de la décongélation. Une fois les œufs incorporés, en revanche, consommez dans les 24 heures et ne congelez pas : les œufs brouillés rendent leur eau et deviennent granuleux. Réchauffez la fondue à feu doux avant d''y lier des œufs frais.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-048'), '{"variant_label":"Piperade au jambon de Bayonne : deux tranches par personne poêlées à part puis coupées en lanières et mêlées à la fondue juste avant les œufs — saler alors la préparation d''une main très légère, le jambon étant déjà salé. La forme n''existe pas au catalogue Myko, l''ajout reste hors nomenclature.","rationale":"Le jambon poêlé apporte du sel, du gras fondu et une note séchée qui tire la fondue vers le salé-umami, là où la base restait dans le végétal doux. C''est aussi ce qui oblige à couper le sel de moitié : ajouté à la dose d''origine, l''ensemble deviendrait immangeable. La contrepartie est un plat sensiblement plus riche et plus lourd, et une fenêtre de cuisson étroite pour le jambon — trente secondes par face suffisent, au-delà il durcit et devient cassant au lieu de fondre dans les légumes.","operations":[{"op":"add","form":"Jambon de Bayonne","quantity":160,"unit":"g","role":"charcuterie","optional":false},{"op":"set","form":"Sel fin","quantity":3,"role":"assaisonnement"}],"steps":[{"op":"replace","n":6,"instruction":"Incorporez la pulpe de tomate râpée, l''ail haché, le thym, les feuilles de laurier et le piment d''Espelette. Salez d''une main très légère — la moitié de ce que réclamerait la fondue seule, car la charcuterie qui la rejoindra tout à l''heure en apporte largement pour deux — et donnez un tour de poivre. Découvrez et laissez réduire vingt minutes à petits bouillons, en raclant régulièrement le fond à la spatule."},{"op":"insert","after":7,"instruction":"Chauffez une poêle sèche à feu vif et saisissez-y les tranches de jambon de Bayonne trente secondes par face, le temps qu''elles se raidissent et lâchent un peu de leur gras. N''allez pas plus loin : une seconde de trop et elles durcissent en copeaux cassants. Débitez-les en lanières d''un bon centimètre, jetez-les dans la fondue avec le gras resté au fond de la poêle et mélangez."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivron rouge frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivron rouge frais', 500, 'g', 'required',
     'légume principal', false, 1);

