      LIMIT 1),
     'Feuille de laurier séchée', 2, 'feuille', 'optional',
     'aromate', true, 11);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sucre semoule' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sucre semoule', 10, 'g', 'optional',
     'correcteur d''acidité', true, 12);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoyez environ 600 g de poivrons rouges entiers à l''étal pour arriver aux 500 g de chair utile de la liste. Débarrassez chacun de sa queue, de ses pépins et des membranes claires qui tapissent l''intérieur, puis débitez la chair en lanières d''un bon centimètre de large.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Comptez à l''achat deux gros oignons, soit près de 290 g bruts, pour 250 g une fois pelés. Détaillez-les en demi-lunes fines. Écrasez trois à quatre gousses d''ail sous le plat de la lame, retirez la peau et hachez la pulpe : vous obtenez les 12 g attendus.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pour les 500 g de pulpe, partez de 700 g environ de tomates bien mûres. Coupez-les en deux à l''équateur et frottez la face ouverte sur une râpe à gros trous, la peau restant entière dans votre main : la chair tombe râpée dans le bol et vous évitez l''ébouillantage.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Versez l''huile d''olive dans une sauteuse large et posez sur feu doux. Jetez-y les oignons et laissez-les s''attendrir sept à huit minutes en remuant : ils doivent devenir translucides et souples, sans jamais prendre de couleur blonde.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Ajoutez les lanières de poivron, mélangez pour les enrober de gras, couvrez et poursuivez à feu modéré une dizaine de minutes. Remuez deux ou trois fois pendant ce temps : les lanières perdent leur raideur et commencent à se coucher au fond.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Incorporez la pulpe de tomate râpée, l''ail haché, le thym, les feuilles de laurier et le piment d''Espelette. Salez et donnez un tour de poivre. Découvrez et laissez réduire vingt minutes à petits bouillons, en raclant régulièrement le fond à la spatule.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'La préparation est prête quand elle a perdu son eau et qu''un sillon tracé à la spatule tient quelques secondes avant de se refermer. Goûtez : si la tomate mord trop, corrigez avec le sucre semoule, par petites pincées seulement. Retirez les feuilles de laurier.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Ne battez rien cette fois. Creusez quatre nids bien espacés dans la fondue réduite, du dos d''une cuillère, en poussant les légumes vers les bords jusqu''à voir le fond de la sauteuse. Sans ce creux, le blanc s''étalerait en nappe sur toute la surface au lieu de prendre en place, et vous n''auriez ni œuf poché ni œuf brouillé. Baissez le feu au minimum avant de continuer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Cassez un œuf de calibre moyen dans chaque nid — quatre œufs, soit les 200 g de contenu attendus une fois les coquilles écartées —, salez les blancs d''une pincée, couvrez et comptez cinq minutes exactement. Le blanc doit être entièrement pris quand le jaune tremble encore sous le doigt : une minute de plus et il tourne au sableux. Servez sans attendre, une part de fondue et son œuf par assiette, avec du pain de campagne pour le jaune.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-048-D4', 'recipe_family', 'Piperade aux œufs pochés',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-048-D4', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-048-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-048-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('6ea2a082d0f5ad53243054a1dbe1e54d'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":3,"salty":2,"acidic":3,"bitter":0,"umami":3,"heat":2,"pungency":2,"richness":3,"freshness":1,"intensity":3},"dominant_flavors":["poivron doux confit","tomate mûre","jaune d''œuf coulant","piment doux"],"aroma_families":["végétal cuit","fruité","épicé doux"],"target_textures":["fondant","blanc juste pris","jaune coulant"],"signature_ingredients":["Poivron rouge frais","Tomate râpée","Piment d''Espelette moulu"],"identity_guardrails":["Le poivron rouge fondu longuement à l''huile d''olive est la base du plat : sans lui il ne reste qu''une sauce tomate aux œufs.","Le piment d''Espelette signe l''origine basque ; le remplacer par un piment fort ou par du paprika déplace le plat hors de son identité.","Les légumes doivent être menés jusqu''à la fondue, ni laissés croquants ni réduits en purée mixée.","Les œufs pochent entiers dans la préparation et n''y sont jamais mélangés : dès qu''on remue, on retombe sur la piperade brouillée, qui est un autre plat."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pommes de terre sarladaises à l''oignon', 'pommes de terre sarladaises a l oignon', 'France', 'France',
     'meal', 'accompagnement', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pommes de terre sarladaises à l''oignon', 'Pommes de terre rissolées dans la graisse de canard avec ail, persil et oignons fondus', ds.id, 'SRC-049-D1',
    'Myko', 'editorial', 4, 25, 38, 'facile',
    NULL, NULL,
    'B', 'candidate', '7574024b1ea2b375f734bcf2c23ed74e',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":3}'::jsonb, ARRAY['ail','canard confit','persil']::text[],
    ARRAY['alliacé','herbacé','gras rôti']::text[], ARRAY['rondelles croustillantes en surface','cœur fondant','chair de canard effilochée']::text[],
    ARRAY['Pomme de terre cuite','Confit de canard cuit','Ail cru']::text[], ARRAY['La persillade ail-persil s''ajoute dans les toutes dernières minutes : cuite dès le départ, elle noircit et le plat perd son parfum caractéristique.','La cuisson se fait dans un gras de canard ou d''oie, ici celui du confit ; à l''huile, ce sont des pommes de terre sautées ordinaires, plus des sarladaises.','Les rondelles doivent être parfaitement essuyées avant la poêle, faute de quoi elles rendent leur eau et tournent à la purée.']::text[],
    ARRAY['saisie','étuvée','hachage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte hermétique. Réchauffage à la poêle bien chaude pour retrouver le croustillant, jamais au micro-ondes. Congélation déconseillée : la pomme de terre déjà cuite rend son eau et devient farineuse à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-049'), '{"variant_label":"Avec oignon : un oignon émincé fondu dans le gras avant les pommes de terre, version relevée par une seule des sources.","rationale":"L''oignon fondu dans la graisse de canard avant les rondelles y laisse ses sucres et donne au plat une douceur de fond que la persillade seule n''apportait pas. Il coûte cependant deux choses : de l''eau, qui gêne la prise de croûte des premières rondelles, et une surveillance supplémentaire, puisqu''il brûlerait pendant les douze minutes de coloration s''il restait dans la poêle — il faut le sortir puis le remettre. Le plat en ressort moins tranchant, plus rond, et un peu moins croustillant.","operations":[{"op":"add","form":"Oignon jaune cru","quantity":150,"unit":"g","role":"aromate","optional":false}],"steps":[{"op":"replace","n":4,"instruction":"Faites frémir ce gras dans une poêle à fond épais ou une sauteuse large et jetez-y l''oignon émincé. Laissez-le fondre sept à huit minutes à feu doux, jusqu''à ce qu''il soit translucide et souple, puis réservez-le dans un bol : laissé au fond pendant que les rondelles colorent, il noircirait bien avant elles. Montez alors le feu, versez les rondelles en couche pas trop haute et patientez deux à trois minutes sans y toucher, le temps que la première face accroche une croûte."},{"op":"replace","n":7,"instruction":"Hachez finement l''ail dégermé avec le persil. Découvrez, remettez l''oignon fondu, dispersez cette persillade et la chair de confit effilochée, remontez le feu deux minutes tout au plus pour réveiller les parfums sans brûler l''ail, et servez aussitôt. L''oignon a suffisamment cuit : il ne revient à la poêle que pour se réchauffer et se mêler au reste."},{"op":"insert","after":2,"instruction":"Pelez l''oignon jaune et détaillez-le en demi-lunes fines et régulières. Trop épaisses, elles resteraient croquantes au milieu de rondelles fondantes et trahiraient l''ajout à chaque bouchée ; on veut ici une présence sucrée, pas des morceaux."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pomme de terre cuite' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pomme de terre cuite', 800, 'g', 'required',
     'féculent', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'confit de canard cuit' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Confit de canard cuit', 75, 'g', 'required',
     'protéine', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru', 10, 'g', 'required',
     'aromate', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'persil frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Persil frais', 30, 'g', 'required',
     'herbe', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'optional',
     'assaisonnement', true, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 6);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oignon jaune cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oignon jaune cru', 150, 'g', 'required',
     'aromate', false, 7);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Partez d''environ 1 kg de pommes de terre à chair ferme achetées avec leur peau : une fois pelées et parées, il en reste à peu près les 800 g comestibles de la liste. Détaillez-les en rondelles régulières de 5 mm, ni transparentes ni trop épaisses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rincez rapidement les rondelles à l''eau froide pour retirer l''amidon de surface, puis séchez-les longuement dans un linge propre. Une rondelle encore humide s''étuve au lieu de colorer : c''est le point qui décide de la réussite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Pelez l''oignon jaune et détaillez-le en demi-lunes fines et régulières. Trop épaisses, elles resteraient croquantes au milieu de rondelles fondantes et trahiraient l''ajout à chaque bouchée ; on veut ici une présence sucrée, pas des morceaux.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Prenez une cuisse de confit d''environ 220 g avec son os et son gras, qui donnera les 75 g de chair annoncés. Tiédissez-la à feu doux pour que la graisse se détache, effilochez la viande et réservez-la, en gardant trois bonnes cuillerées de gras fondu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faites frémir ce gras dans une poêle à fond épais ou une sauteuse large et jetez-y l''oignon émincé. Laissez-le fondre sept à huit minutes à feu doux, jusqu''à ce qu''il soit translucide et souple, puis réservez-le dans un bol : laissé au fond pendant que les rondelles colorent, il noircirait bien avant elles. Montez alors le feu, versez les rondelles en couche pas trop haute et patientez deux à trois minutes sans y toucher, le temps que la première face accroche une croûte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Salez, poivrez, puis faites-les sauter d''un mouvement de poignet toutes les deux minutes pendant une douzaine de minutes, jusqu''à obtenir une coloration dorée assez régulière sur l''ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couvrez, baissez le feu et laissez le cœur devenir moelleux une dizaine de minutes, en secouant la poêle de temps à autre. Évitez la cuillère à ce stade, elle écraserait les rondelles ramollies.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Hachez finement l''ail dégermé avec le persil. Découvrez, remettez l''oignon fondu, dispersez cette persillade et la chair de confit effilochée, remontez le feu deux minutes tout au plus pour réveiller les parfums sans brûler l''ail, et servez aussitôt. L''oignon a suffisamment cuit : il ne revient à la poêle que pour se réchauffer et se mêler au reste.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-049-D1', 'recipe_family', 'Pommes de terre sarladaises à l''oignon',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-049-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-049-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-049-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('7574024b1ea2b375f734bcf2c23ed74e'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":3,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["ail","canard confit","persil"],"aroma_families":["alliacé","herbacé","gras rôti"],"target_textures":["rondelles croustillantes en surface","cœur fondant","chair de canard effilochée"],"signature_ingredients":["Pomme de terre cuite","Confit de canard cuit","Ail cru"],"identity_guardrails":["La persillade ail-persil s''ajoute dans les toutes dernières minutes : cuite dès le départ, elle noircit et le plat perd son parfum caractéristique.","La cuisson se fait dans un gras de canard ou d''oie, ici celui du confit ; à l''huile, ce sont des pommes de terre sautées ordinaires, plus des sarladaises.","Les rondelles doivent être parfaitement essuyées avant la poêle, faute de quoi elles rendent leur eau et tournent à la purée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Potée au chou blanc', 'potee au chou blanc', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Potée au chou blanc', 'Chou blanc mijoté avec saucisses de Morteau et Montbéliard, pommes de terre et légumes racines', ds.id, 'SRC-050-D1',
    'Myko', 'editorial', 6, 30, 101, 'facile',
    NULL, NULL,
    'B', 'candidate', '3fa9b4ddaac6d86bef10faddc0225f5f',
    '{"sweet":2,"salty":4,"acidic":0,"bitter":1,"umami":4,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":3}'::jsonb, ARRAY['porc fumé','chou braisé','bouillon salé','légume-racine sucré']::text[],
    ARRAY['fumé','épices chaudes','végétal cuit']::text[], ARRAY['légumes fondants','pomme de terre farineuse','saucisse ferme et juteuse','bouillon clair']::text[],
    ARRAY['Chou blanc frais','Saucisse de Morteau','Saucisse de Montbéliard','Pomme de terre cuite']::text[], ARRAY['Sans chou, ce n''est plus une potée : c''est lui qui structure le plat et parfume le bouillon en retour.','La charcuterie doit être fumée et pochée entière ; remplacer Morteau et Montbéliard par une viande fraîche non fumée efface le goût de cochonnaille qui fait le plat.','Les légumes cuisent dans le bouillon des viandes, jamais dans une eau neuve : c''est cet échange qui distingue la potée d''un simple pot-au-feu de légumes.','Pas de liaison ni de crème : le bouillon reste clair et se sert tel quel.']::text[],
    ARRAY['blanchiment','pochage','mijotage','écumage']::text[], ARRAY[]::text[], ARRAY['sulfites']::text[],
    'Trois jours au réfrigérateur à 4 °C, viandes et légumes conservés immergés dans leur bouillon pour ne pas sécher ; réchauffer à frémissement doux, jamais à gros bouillons. Le goût s''améliore au deuxième jour. Congélation possible deux mois pour les saucisses et le bouillon dans des boîtes séparées, mais retirer d''abord les pommes de terre, qui deviennent farineuses et grumeleuses, et le chou, qui se défait en filaments à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-050'), '{"variant_label":"Potée au chou blanc : substituer un chou blanc au chou vert, en allongeant le blanchiment d''une minute car ses feuilles sont plus fermes.","rationale":"Le chou blanc tient mieux la longue cuisson que le vert et sort du bouillon en quartiers encore dessinés, là où le vert se relâche en feuilles molles. Il est aussi plus doux et plus sucré, ce qui adoucit d''autant le contraste avec la charcuterie fumée — on y perd l''amertume franche qui, chez certains, fait la potée. Ses feuilles serrées et cireuses laissent l''eau entrer plus lentement : une minute de blanchiment supplémentaire est nécessaire, faute de quoi la côte reste crue au cœur du quartier.","operations":[{"op":"substitute","form":"Chou vert frais","with":"Chou blanc frais","quantity":800,"unit":"g","role":"légume"}],"steps":[{"op":"replace","n":1,"instruction":"Parer le chou blanc : d''une pomme achetée entière d''environ 1,1 kg, jeter les feuilles extérieures fatiguées et creuser le trognon à la pointe du couteau, ce qui laisse à peu près 800 g de feuilles utilisables. Fendre en quartiers en gardant un peu de trognon à chacun pour qu''il ne se démonte pas, dégager la côte centrale — plus épaisse et plus coriace que celle de la variété verte — et rincer à grande eau."},{"op":"replace","n":2,"instruction":"Immerger les quartiers dans un grand volume d''eau bouillante non salée et compter trois à quatre minutes dès que l''ébullition repart, soit une bonne minute de plus qu''il n''en faudrait autrement : les feuilles serrées et cireuses de cette variété laissent l''eau pénétrer lentement. Les cueillir à l''écumoire, les rafraîchir sous le robinet froid et les laisser s''égoutter, côte vers le bas. Ce passage arrondit l''amertume, déjà modérée ici, et rend le plat plus digeste."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

