  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Ratatouille aux olives noires', 'Ratatouille provençale enrichie d''olives noires ajoutées en cours de cuisson', ds.id, 'SRC-051-D3',
    'Myko', 'editorial', 4, 30, 55, 'facile',
    NULL, NULL,
    'B', 'candidate', 'e3e71a2cb46d5902706824dfef7ca227',
    '{"sweet":3,"salty":2,"acidic":2,"bitter":1,"umami":3,"heat":0,"pungency":1,"richness":3,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','poivron confit','ail','huile d''olive']::text[],
    ARRAY['herbacé méditerranéen','végétal grillé','aillé']::text[], ARRAY['dés fondants gardant leur forme','sauce courte et nappante']::text[],
    ARRAY['Aubergine fraîche','Courgette fraîche','Poivron rouge frais','Tomate fraîche mûre','Huile d''olive vierge extra']::text[], ARRAY['Les quatre légumes d''été — aubergine, courgette, poivron, tomate — sont indissociables : en retirer un fait sortir du plat.','L''huile d''olive est le seul corps gras admis ; beurre ou crème déplacent la recette vers une autre famille.','Aucun bouillon ni liquide ajouté : la liaison vient de l''eau et des sucs rendus par les légumes eux-mêmes.','Ni viande ni féculent dans la cocotte, sous peine de basculer vers un ragoût ou une poêlée composée.']::text[],
    ARRAY['saisie','mijotage','réduction']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois à quatre jours au réfrigérateur à 4 °C dans un contenant hermétique ; le goût se raffermit après une nuit de repos. Se congèle jusqu''à trois mois, mais les courgettes relâchent beaucoup d''eau à la décongélation : réchauffer à découvert pour faire évaporer le surplus avant de servir.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-051'), '{"variant_label":"Ajout d''olives noires dénoyautées et tranchées dans les dix dernières minutes de cuisson.","rationale":"Quatre-vingts grammes d''olives noires apportent une amertume saline et un fond légèrement fermenté que la ratatouille de base n''a pas, et qui tire le plat du côté de la caponata. Elles obligent à revoir le sel : ajoutées en fin de mijotage, elles rendent encore assez de saumure pour qu''un assaisonnement mené à l''aveugle passe le plat au salé. Elles ferment aussi la porte au service froid le lendemain, où leur amertume s''installe.","operations":[{"op":"add","form":"Olive noire dénoyautée","quantity":80,"unit":"g","role":"garniture","optional":false}],"steps":[{"op":"replace","n":9,"instruction":"Remettre tous les légumes réservés dans la sauteuse avec le jus qu''ils ont rendu, mélanger avec précaution pour ne pas les écraser, couvrir et laisser mijoter à tout petit feu une vingtaine de minutes. Dix minutes avant la fin, semer les olives noires dénoyautées et taillées en rondelles, puis découvrir pour laisser le fond réduire : jetées plus tôt, elles rendraient toute leur saumure dans la sauce et le plat serait salé sans retour possible."},{"op":"replace","n":10,"instruction":"Retirer les feuilles de laurier et goûter avant de saler : les olives ont déjà porté leur part et il en faut souvent moins que prévu. Laisser reposer hors du feu au moins un quart d''heure ; cette ratatouille se sert tiède, ou réchauffée le lendemain, jamais brûlante."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

