DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise aux pignons et à l''échalote', 'salade landaise aux pignons et a l echalote', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade landaise aux pignons et à l''échalote', 'Salade au confit de canard avec pignons de pin torréfiés et échalotes en vinaigrette', ds.id, 'SRC-054-D2',
    'Myko', 'editorial', 4, 20, 12, 'facile',
    NULL, NULL,
    'B', 'candidate', 'c4f489c3cc4193adc3b8d2f90886ffdd',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['gras de canard confit','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','végétal frais','acidulé']::text[], ARRAY['peau de canard croustillante','chair effilochée fondante','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, aucune autre viande ne le remplace.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras ; une sauce crémée efface l''identité gasconne.','Le canard se pose tiède sur une base froide et non assaisonnée à l''avance : tout réchauffer ou tout laisser refroidir transforme le plat en autre chose.']::text[],
    ARRAY['saisie','émulsion','torréfaction']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites','fruits à coque']::text[],
    'À manger dans la foulée du dressage. Les éléments se gardent séparément : chair de canard désossée trois jours à 4 °C recouverte de sa graisse, vinaigrette une semaine au réfrigérateur en bocal fermé, pulpe de tomate le jour même. Une fois assaisonnée, la salade s''affaisse en moins d''une heure. Ne se congèle pas : la tomate râpée rend toute son eau à la décongélation et la peau croustillante devient molle ; seul le confit non désossé supporte le congélateur, trois mois sous graisse.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Parsemer de pignons torréfiés à sec et glisser une échalote ciselée dans la vinaigrette.","rationale":"Deux ajouts modestes qui travaillent chacun à un bout du plat : quarante grammes de pignons torréfiés opposent un croquant sec à la chair effilochée, et trente grammes d''échalote fondus dans le vinaigre donnent à la sauce un mordant aromatique que la moutarde seule ne fournit pas. L''échalote demande un temps de dégorgement dans le vinaigre, sans quoi elle reste agressive et remonte longtemps après le repas. Les pignons introduisent l''allergène fruits à coque dans une recette qui n''en portait aucun, et perdent leur croquant dès qu''ils touchent la vinaigrette : ils se sèment au tout dernier geste.","operations":[{"op":"add","form":"Pignon de pin","quantity":40,"unit":"g","role":"garniture croquante","optional":false},{"op":"add","form":"Échalote crue","quantity":30,"unit":"g","role":"aromate","optional":false}],"steps":[{"op":"insert","after":4,"instruction":"Verser les pignons de pin dans une petite poêle froide, sans matière grasse, et les faire blondir à feu moyen environ trois minutes en les remuant sans cesse. Les débarrasser dans une assiette froide dès qu''ils sentent la résine : leur propre huile les fait passer du doré à l''amer en quelques secondes de trop, et la poêle chaude continue de les cuire hors du feu."},{"op":"replace","n":6,"instruction":"Éplucher l''échalote et la ciseler le plus finement possible, puis la laisser dégorger cinq minutes dans le vinaigre avec une pincée de sel prise sur les 3 g : l''acide mange son mordant et elle ne remontera plus en bouche longtemps après le repas. Délayer ensuite la moutarde dans ce vinaigre parfumé, donner un tour de moulin à poivre, puis incorporer l''huile en mince filet sans cesser de fouetter, jusqu''à obtenir une sauce lisse qui nappe le dos d''une cuillère."},{"op":"replace","n":7,"instruction":"Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède et les éclats de peau, parsemer des pignons torréfiés, napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : les pignons perdent leur croquant dès qu''ils trempent dans la sauce, et le contraste tiède contre frais s''efface en quelques minutes."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
