  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-054-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c4f489c3cc4193adc3b8d2f90886ffdd'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["gras de canard confit","acidité vinaigrée","moutarde"],"aroma_families":["rôti","végétal frais","acidulé"],"target_textures":["peau de canard croustillante","chair effilochée fondante","pulpe de tomate fraîche"],"signature_ingredients":["Confit de canard cuit","Moutarde de Dijon","Huile d''olive vierge extra"],"identity_guardrails":["Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, aucune autre viande ne le remplace.","La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras ; une sauce crémée efface l''identité gasconne.","Le canard se pose tiède sur une base froide et non assaisonnée à l''avance : tout réchauffer ou tout laisser refroidir transforme le plat en autre chose."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Soufflés au fromage individuels', 'souffles au fromage individuels', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Soufflés au fromage individuels', 'Soufflés au fromage de ménage cuits dans des ramequins individuels', ds.id, 'SRC-056-D1',
    'Myko', 'editorial', 6, 20, 19, 'moyenne',
    NULL, NULL,
    'B', 'candidate', 'c5772ac6dd108c00e9b8363d25fb8e65',
    '{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3}'::jsonb, ARRAY['fromage affiné','beurre','jaune d''œuf']::text[],
    ARRAY['lactée','beurrée','épicée douce']::text[], ARRAY['mousseux','aérien','croûte dorée généreuse','cœur crémeux réduit']::text[],
    ARRAY['Œuf cru','Gruyère râpé','Emmental râpé']::text[], ARRAY['Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.','Le fromage à pâte pressée cuite râpé, emmental et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.','La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.','Chaque ramequin se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson : sur un si petit volume, un appel d''air froid effondre la levée en quelques secondes.']::text[],
    ARRAY['béchamel','blancs en neige','cuisson au four']::text[], ARRAY[]::text[], ARRAY['lait','œuf','gluten']::text[],
    'Un soufflé se mange dans la minute où il sort du four : il commence à retomber en deux à trois minutes et ne se rattrape pas. Les restes se gardent couverts 48 heures au réfrigérateur à 4 °C et se réchauffent 10 minutes à 150 °C, en acceptant qu''ils restent plats et se rapprochent d''un flan au fromage. L''appareil cru ne se garde pas et ne s''anticipe pas, les blancs retombant en une quinzaine de minutes. La congélation est à proscrire, avant comme après cuisson : elle détruit la mousse et fait rendre son eau à la béchamel.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-056'), '{"variant_label":"Soufflés individuels : répartir l''appareil dans six ramequins beurrés et chemisés de gruyère, cuisson ramenée à 18-20 minutes.","rationale":"Le même appareil réparti en six petits volumes cuit en moins de vingt minutes, parce que la chaleur atteint presque aussitôt le cœur d''une masse aussi mince. Le rapport entre croûte et cœur bascule : beaucoup plus de surface dorée, beaucoup moins de crémeux au centre, ce qui déçoit qui vient chercher le fondant du grand soufflé. La retombée est plus brutale encore, une minute ou deux sur la table et la couronne est plate. Et le service devient tyrannique — six ramequins à enfourner et à sortir ensemble, six convives déjà assis.","operations":[],"steps":[{"op":"replace","n":2,"instruction":"Prélever une noix sur les 50 g de beurre doux et en enduire au pinceau six ramequins d''environ dix centimètres, en montant du fond vers le haut par traits verticaux. Chemiser chacun d''une pincée prise sur le gruyère râpé, tourner le ramequin pour en tapisser toute la paroi puis le retourner pour chasser l''excédent : cette paroi rugueuse donne prise à l''appareil qui grimpe. Ranger les ramequins sur une plaque, ils partiront et sortiront du four ensemble."},{"op":"replace","n":9,"instruction":"Répartir l''appareil dans les six ramequins en les remplissant aux deux tiers seulement, égaliser la surface à la petite spatule et passer le pouce dans une rainure le long de chaque paroi pour décoller l''appareil du bord. Sur un si petit diamètre, un ramequin trop plein déborde avant d''avoir levé et sa couronne se colle au bord au lieu de monter droit."},{"op":"replace","n":10,"instruction":"Enfourner la plaque entière pour dix-huit à vingt minutes, porte fermée pendant les douze premières : une petite masse chauffe vite et se trouve cuite bien avant un grand soufflé. Ils sont prêts lorsqu''ils dépassent le bord de deux bons centimètres, que le dessus est franchement doré et que le centre tremble encore quand on bouge la plaque. Passer directement du four à la table, ramequin brûlant posé sur assiette : à cette taille la retombée s''amorce en moins de deux minutes."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
