  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Sortir les œufs du froid une heure avant de commencer : des blancs à température ambiante prennent du volume plus vite et plus haut. Chauffer le four à 180 °C en chaleur tournante, grille placée au tiers bas.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Prélever une noix sur les 50 g de beurre doux et en enduire au pinceau six ramequins d''environ dix centimètres, en montant du fond vers le haut par traits verticaux. Chemiser chacun d''une pincée prise sur le gruyère râpé, tourner le ramequin pour en tapisser toute la paroi puis le retourner pour chasser l''excédent : cette paroi rugueuse donne prise à l''appareil qui grimpe. Ranger les ramequins sur une plaque, ils partiront et sortiront du four ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Compter quatre œufs moyens, soit près de 240 g sur la balance coquille comprise, pour les 200 g de matière utile de la recette. Les casser en séparant les blancs dans un grand saladier bien sec et les jaunes dans un bol.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le beurre restant à feu doux dans une casserole à fond épais, y verser la farine de blé T55 en pluie et travailler au fouet une bonne minute : le mélange doit gonfler légèrement et sentir le biscuit sec, sans jamais prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser d''un seul coup le lait entier préalablement tiédi sur ce roux, monter le feu et fouetter sans interruption. La sauce s''épaissit en deux ou trois minutes et nappe franchement le fouet dès les premiers bouillons : retirer aussitôt du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser retomber la chaleur cinq minutes, puis incorporer les jaunes un par un au fouet, en attendant que chacun disparaisse avant d''ajouter le suivant. Verser ensuite l''emmental râpé et le gruyère râpé restant en plusieurs fois, hors du feu, jusqu''à obtenir une base lisse et brillante. Râper la muscade moulue, poivrer, et saler d''une main légère seulement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Monter les blancs avec une pincée prise sur le sel fin, d''abord à vitesse moyenne puis en accélérant, jusqu''à ce qu''ils tiennent au fouet en formant une pointe qui s''incline à peine.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Détendre la base encore tiède avec un gros tiers des blancs travaillé sans ménagement, ce qui l''allège et la rend réceptive. Ajouter le reste en deux fois, à la maryse, en coupant la masse verticalement puis en la ramenant par-dessous en tournant le saladier : arrêter dès l''homogénéité, quelques traînées blanches valent mieux qu''un appareil retombé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Répartir l''appareil dans les six ramequins en les remplissant aux deux tiers seulement, égaliser la surface à la petite spatule et passer le pouce dans une rainure le long de chaque paroi pour décoller l''appareil du bord. Sur un si petit diamètre, un ramequin trop plein déborde avant d''avoir levé et sa couronne se colle au bord au lieu de monter droit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Enfourner la plaque entière pour dix-huit à vingt minutes, porte fermée pendant les douze premières : une petite masse chauffe vite et se trouve cuite bien avant un grand soufflé. Ils sont prêts lorsqu''ils dépassent le bord de deux bons centimètres, que le dessus est franchement doré et que le centre tremble encore quand on bouge la plaque. Passer directement du four à la table, ramequin brûlant posé sur assiette : à cette taille la retombée s''amorce en moins de deux minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-056-D1', 'recipe_family', 'Soufflés au fromage individuels',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-056-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-056-D1', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-056-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('c5772ac6dd108c00e9b8363d25fb8e65'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["fromage affiné","beurre","jaune d''œuf"],"aroma_families":["lactée","beurrée","épicée douce"],"target_textures":["mousseux","aérien","croûte dorée généreuse","cœur crémeux réduit"],"signature_ingredients":["Œuf cru","Gruyère râpé","Emmental râpé"],"identity_guardrails":["Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.","Le fromage à pâte pressée cuite râpé, emmental et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.","La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.","Chaque ramequin se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson : sur un si petit volume, un appel d''air froid effondre la levée en quelques secondes."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Soufflé au comté', 'souffle au comte', 'France', 'France',
     'meal', 'plat au four', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Soufflé au comté', 'Soufflé à la béchamel de gruyère et comté affiné pour une saveur plus prononcée', ds.id, 'SRC-056-D2',
    'Myko', 'editorial', 4, 20, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '310655e9bf024f338b3e035b78d16438',
    '{"sweet":1,"salty":4,"acidic":0,"bitter":0,"umami":5,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['comté affiné','noisette','beurre','jaune d''œuf']::text[],
    ARRAY['lactée','beurrée','épicée douce']::text[], ARRAY['mousseux','aérien','croûte dorée','cœur crémeux']::text[],
    ARRAY['Œuf cru','Gruyère râpé','Comté']::text[], ARRAY['Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.','Le fromage à pâte pressée cuite râpé, ici comté et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.','La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.','Le moule se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson, sinon la levée s''effondre.','Le comté s''incorpore hors du feu dans une base tiède : fondu à chaud, il se sépare et laisse un appareil huileux que les blancs ne rattrapent plus.']::text[],
    ARRAY['béchamel','blancs en neige','cuisson au four']::text[], ARRAY[]::text[], ARRAY['lait','œuf','gluten']::text[],
    'Un soufflé se mange dans la minute où il sort du four : il commence à retomber en deux à trois minutes et ne se rattrape pas. Les restes se gardent couverts 48 heures au réfrigérateur à 4 °C et se réchauffent 10 minutes à 150 °C, en acceptant qu''ils restent plats et se rapprochent d''un flan au fromage. L''appareil cru ne se garde pas et ne s''anticipe pas, les blancs retombant en une quinzaine de minutes. La congélation est à proscrire, avant comme après cuisson : elle détruit la mousse et fait rendre son eau à la béchamel.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-056'), '{"variant_label":"Fromage plus typé : remplacer tout ou partie de l''emmental par un comté vieux, ou ajouter une soixantaine de grammes de mimolette vieille comme le fait l''une des sources du dossier.","rationale":"L''emmental cède toute sa place au comté, à poids égal : le soufflé gagne une profondeur de noisette et de croûte, un salé fruité que l''emmental n''a jamais eu, et perd la douceur neutre qui le rendait consensuel. Le comté est plus salé et plus gras, il faut donc saler la base d''une main encore plus légère et accepter un appareil un peu plus lourd à monter. Il fond aussi moins docilement : versé dans une béchamel bouillante il rend son gras et grumelle au lieu de se fondre. La seconde branche de la variante, celle de la mimolette vieille, n''est pas écrite ici faute de forme au catalogue.","operations":[{"op":"substitute","form":"Emmental râpé","with":"Comté","quantity":105,"unit":"g","role":"fromage"}],"steps":[{"op":"replace","n":6,"instruction":"Laisser retomber la chaleur cinq minutes, puis incorporer les jaunes un par un au fouet, en attendant que chacun disparaisse avant d''ajouter le suivant. Verser ensuite le comté et le gruyère râpé restant en plusieurs fois, hors du feu et sur une base seulement tiède : jeté dans une béchamel encore bouillante, un fromage aussi gras rend son huile et grumelle au lieu de fondre. Râper la muscade moulue, poivrer, et saler d''une main plus légère encore que d''ordinaire, le comté apportant déjà son propre sel."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

