  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faire fondre le beurre restant à feu doux dans une casserole à fond épais, y verser la farine de blé T55 en pluie et travailler au fouet une bonne minute : le mélange doit gonfler légèrement et sentir le biscuit sec, sans jamais prendre de couleur.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Verser d''un seul coup le lait entier préalablement tiédi sur ce roux, monter le feu et fouetter sans interruption. La sauce s''épaissit en deux ou trois minutes et nappe franchement le fouet dès les premiers bouillons : retirer aussitôt du feu.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Laisser retomber la chaleur cinq minutes, puis incorporer les jaunes un par un au fouet, en attendant que chacun disparaisse avant d''ajouter le suivant. Ciseler la ciboulette fraîche au couteau bien aiguisé, en coupant net plutôt qu''en hachant : écrasée, elle noircit et rend une eau verte qui strie la base. L''ajouter à ce moment précis, dans un appareil encore tiède dont la chaleur libère le parfum sans le cuire. Verser ensuite l''emmental râpé et le gruyère râpé restant en plusieurs fois, hors du feu, jusqu''à obtenir une base lisse et brillante, puis râper la muscade moulue, poivrer et saler d''une main légère seulement.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Monter les blancs avec une pincée prise sur le sel fin, d''abord à vitesse moyenne puis en accélérant, jusqu''à ce qu''ils tiennent au fouet en formant une pointe qui s''incline à peine.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Détendre la base encore tiède avec un gros tiers des blancs travaillé sans ménagement, ce qui l''allège et la rend réceptive. Ajouter le reste en deux fois, à la maryse, en coupant la masse verticalement puis en la ramenant par-dessous en tournant le saladier : arrêter dès l''homogénéité, quelques traînées blanches valent mieux qu''un appareil retombé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Remplir le moule aux deux tiers de sa hauteur, jamais davantage, égaliser la surface et passer le pouce ou la pointe d''un couteau dans une rainure le long de la paroi pour décoller l''appareil du bord et l''aider à monter droit.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 10, 'Enfourner 35 minutes en gardant la porte fermée pendant les vingt premières : le soufflé est prêt lorsqu''il dépasse largement le moule, que le dessus est bien doré et que le cœur tremble encore très légèrement quand on remue le moule. Passer directement du four à la table, il commence à redescendre au bout de deux à trois minutes.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-056-D3', 'recipe_family', 'Soufflé au fromage et à la ciboulette',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-056-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-056-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-056-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('3ea1416d52586462525e0112cf4970ed'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["fromage affiné","ciboulette","beurre"],"aroma_families":["lactée","beurrée","alliacée fraîche"],"target_textures":["mousseux","aérien","croûte dorée piquée de vert","cœur crémeux"],"signature_ingredients":["Œuf cru","Gruyère râpé","Emmental râpé"],"identity_guardrails":["Les blancs doivent être montés à part et incorporés à la maryse en fin d''appareil : mélangés au batteur ou battus avec les jaunes, la préparation ne lève plus et devient une omelette au four.","Le fromage à pâte pressée cuite râpé, emmental et gruyère, porte tout le goût du plat : sans lui il ne reste qu''un soufflé nature.","La base doit être une béchamel épaisse au beurre et à la farine, seule assez ferme pour tenir les bulles d''air ; un liant à la fécule délayée donne une texture caoutchouteuse hors identité.","Le moule se remplit aux deux tiers au maximum et la porte du four reste fermée en début de cuisson, sinon la levée s''effondre.","La ciboulette reste une trace et non un ingrédient de poids : au-delà d''une cuillerée, l''appareil s''alourdit et le soufflé cesse de monter droit."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Tarte à l''oignon alsacienne', 'tarte a l oignon alsacienne', 'France', 'France',
     'meal', 'tarte salée', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Tarte à l''oignon alsacienne', 'Fond feuilleté garni d''oignons longuement fondus avec crème liée aux œufs à la muscade', ds.id, 'SRC-057-D1',
    'Myko', 'editorial', 6, 20, 48, 'facile',
    NULL, NULL,
    'B', 'candidate', '583b3ffeca609d6ca19b1fc8fdea7fb9',
    '{"sweet":3,"salty":2,"acidic":1,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2}'::jsonb, ARRAY['oignon compoté sucré','crème cuite','muscade']::text[],
    ARRAY['allium doux','lacté','épicée douce']::text[], ARRAY['feuilletage croustillant','appareil crémeux tout juste pris','oignons fondants']::text[],
    ARRAY['Oignon jaune cru','Crème fraîche liquide entière','Pâte feuilletée crue']::text[], ARRAY['Sans oignon jaune longuement compoté à feu doux jusqu''au blond, ce n''est plus une tarte à l''oignon mais une quiche quelconque.','L''appareil œuf-crème doit rester salé et prendre au four : le remplacer par du fromage fondu ou une sauce blanche change de plat.','La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza.','L''absence de lard n''est pas un oubli mais la définition même de cette version : y remettre des lardons la ramène à la tarte à l''oignon courante.']::text[],
    ARRAY['mijotage','réduction','cuisson au four']::text[], ARRAY[]::text[], ARRAY['gluten','lait','œuf']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C, filmée une fois complètement refroidie, et se réchauffe dix minutes à 160 °C pour que le feuilletage retrouve son croustillant. La congélation est possible sur la tarte cuite et refroidie, deux mois maximum, mais l''appareil œuf-crème relâche un peu d''eau à la décongélation et la pâte ramollit : la réchauffer alors directement à 180 °C sans décongélation préalable.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-057'), '{"variant_label":"Version alsacienne stricte : supprimer les lardons et râper un peu de muscade dans l''appareil œuf-crème.","rationale":"Privée de lardons, la tarte perd sa colonne salée et fumée : le sucre de l''oignon compoté et le lacté de la crème, jusque-là au second plan, passent devant, et la muscade vient occuper le vide aromatique laissé par le lard. Elle est aussi nettement moins riche et moins nourrissante — elle ne fait plus le plat à elle seule et réclame vraiment la salade à côté. La compotée doit en contrepartie aller quelques minutes plus loin, puisque c''est elle seule qui porte désormais le goût.","operations":[{"op":"remove","form":"Lardon fumé cru"},{"op":"add","form":"Muscade moulue","quantity":0.4,"unit":"g","role":"aromate","optional":false}],"steps":[{"op":"replace","n":3,"instruction":"Retirer le couvercle et poursuivre quinze minutes à feu moyen en remuant régulièrement, jusqu''à ce que toute l''humidité se soit évaporée et que les oignons soient blonds et translucides, sans jamais brunir. Rien ne vient plus saler ni graisser la compotée en cours de route : elle doit aller trois bonnes minutes plus loin que dans la version courante, jusqu''à ce que le sucre se devine nettement. Débarrasser dans un plat et laisser tiédir."},{"op":"replace","n":5,"instruction":"Casser deux gros œufs, soit environ cent dix grammes coquille comprise pour les cent grammes d''œuf de la liste, et les fouetter avec la crème jusqu''à obtenir un appareil homogène. Râper la muscade par-dessus, très peu, une dizaine d''allers-retours sur la râpe fine : elle doit se deviner derrière l''oignon sans jamais s''annoncer, une muscade trop généreuse assèche la bouche et tourne à l''amer. Saler un peu plus franchement qu''à l''ordinaire, poivrer, goûter."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oignon jaune cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Oignon jaune cru', 240, 'g', 'required',
     'légume principal', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pate feuilletee crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pâte feuilletée crue', 230, 'g', 'required',
     'base', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'creme fraiche liquide entiere' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Crème fraîche liquide entière', 200, 'g', 'required',
     'liant', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 100, 'g', 'required',
