     'assaisonnement', true, 8);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'muscade moulue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Muscade moulue', 0.4, 'g', 'required',
     'aromate', false, 9);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 270 g d''oignons entiers, c''est-à-dire trois beaux oignons tels qu''on les achète : une fois pelés et parés, il en reste les 240 g de chair nette utilisés ici. Les couper en deux dans la hauteur puis les émincer en demi-lunes fines et régulières.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire chauffer l''huile d''olive dans une large sauteuse, y jeter les oignons avec le miel et une petite pincée de sel, couvrir et laisser suer huit minutes à feu doux, le temps qu''ils rendent leur eau et s''affaissent.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Retirer le couvercle et poursuivre quinze minutes à feu moyen en remuant régulièrement, jusqu''à ce que toute l''humidité se soit évaporée et que les oignons soient blonds et translucides, sans jamais brunir. Rien ne vient plus saler ni graisser la compotée en cours de route : elle doit aller trois bonnes minutes plus loin que dans la version courante, jusqu''à ce que le sucre se devine nettement. Débarrasser dans un plat et laisser tiédir.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Porter le four à 200 °C. Étaler la pâte avec son papier au fond d''un moule de vingt-six centimètres, piquer le fond à la fourchette et plaquer les bords contre la paroi.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Casser deux gros œufs, soit environ cent dix grammes coquille comprise pour les cent grammes d''œuf de la liste, et les fouetter avec la crème jusqu''à obtenir un appareil homogène. Râper la muscade par-dessus, très peu, une dizaine d''allers-retours sur la râpe fine : elle doit se deviner derrière l''oignon sans jamais s''annoncer, une muscade trop généreuse assèche la bouche et tourne à l''amer. Saler un peu plus franchement qu''à l''ordinaire, poivrer, goûter.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Répartir la compotée tiède sur le fond de pâte en couche égale, verser l''appareil par-dessus pour qu''il s''insinue entre les oignons, puis enfourner trente minutes : la crème doit être prise au centre et le pourtour du feuilletage bien doré.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Sortir la tarte et la laisser reposer une dizaine de minutes sur une grille avant de la découper, le temps que la garniture se raffermisse et que le dessous du feuilletage sèche.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-057-D1', 'recipe_family', 'Tarte à l''oignon alsacienne',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-057-D1', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
