  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-057-D1', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('583b3ffeca609d6ca19b1fc8fdea7fb9'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":3,"salty":2,"acidic":1,"bitter":0,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":1,"intensity":2},"dominant_flavors":["oignon compoté sucré","crème cuite","muscade"],"aroma_families":["allium doux","lacté","épicée douce"],"target_textures":["feuilletage croustillant","appareil crémeux tout juste pris","oignons fondants"],"signature_ingredients":["Oignon jaune cru","Crème fraîche liquide entière","Pâte feuilletée crue"],"identity_guardrails":["Sans oignon jaune longuement compoté à feu doux jusqu''au blond, ce n''est plus une tarte à l''oignon mais une quiche quelconque.","L''appareil œuf-crème doit rester salé et prendre au four : le remplacer par du fromage fondu ou une sauce blanche change de plat.","La garniture doit reposer sur un fond de pâte cuit dans un moule, jamais sur une base de pain ou de pizza.","L''absence de lard n''est pas un oubli mais la définition même de cette version : y remettre des lardons la ramène à la tarte à l''oignon courante."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
