  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'oeuf cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Œuf cru', 2, 'u', 'required',
     'liant', false, 13);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 260 g de poivrons rouges entiers et autant de verts pour obtenir les 200 g de chair utiles de chaque couleur. Les fendre, arracher le pédoncule, secouer les graines, raser les cloisons blanches puis débiter la chair en lanières larges comme un doigt. Si le piment doux vert est de la partie, le fendre et le vider de la même façon.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Peler 230 g d''oignons pour en garder 200 g nets et les trancher en fines demi-lunes. Écraser puis hacher les gousses d''ail. Râper environ 450 g de tomates mûres, face coupée contre la grille moyenne, jusqu''à ce que la peau reste vide dans la paume : on récupère à peu près 350 g de pulpe.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Tiédir l''huile d''olive dans une sauteuse large, y verser les oignons et laisser fondre à feu modéré une bonne huitaine de minutes sans coloration, en raclant le fond de temps à autre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Verser les lanières de poivrons et le piment doux, remonter légèrement la flamme et poursuivre douze minutes à découvert : les bords doivent s''assouplir et prendre quelques marques dorées.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Incorporer l''ail haché, attendre une minute que le parfum monte, puis ajouter la pulpe de tomate, les herbes de Provence et le piment d''Espelette. Laisser réduire quinze minutes à petit frémissement, sans couvercle, jusqu''à ce que le jus nappe les légumes au lieu de baigner la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, ouvrir trois boîtes de thon au naturel de 185 g net, renverser leur contenu dans une passoire et presser du dos d''une cuillère : il reste environ 390 g de chair une fois le jus de conserve évacué. La séparer en gros pétales sans la réduire en miettes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Casser les deux œufs dans un bol et les battre à la fourchette juste assez pour mêler jaunes et blancs, sans les faire mousser. Baisser la flamme sous la piperade, verser les œufs en filet et remuer sans arrêt à la spatule en raclant le fond. Retirer du feu dès que le mélange épaissit et nappe la spatule, au bout d''une minute à peine : poussé plus loin, l''œuf coagule en grumeaux et la liaison tourne en brouillade.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Étaler la piperade liée dans un plat creux ou la répartir directement dans quatre assiettes, puis coucher les pétales de thon par-dessus sans les enfouir. Le poisson reste ainsi identifiable sous la fourchette et ne subit pas une seconde chauffe dans une masse brûlante, où ses fibres se dessécheraient.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Goûter la piperade seule avant de rectifier avec le sel fin et le poivre noir : la saumure du thon a déjà salé le plat, mais l''œuf, lui, réclame son sel. Servir sans attendre, tant que la liaison est encore souple — elle se raffermit en quelques minutes et ne revient pas en arrière.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-059-D2', 'recipe_family', 'Thon sur piperade liée à l''œuf',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-059-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-059-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-059-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('048c880d732ea3ab3b2b91278e736036'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":3,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","poivron confit","œuf lié"],"aroma_families":["végétal cuit","fruité olive","piment doux"],"target_textures":["légumes fondants","liaison crémeuse à l''œuf","pétales de thon effeuillés"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Poivron rouge frais","Piment d''Espelette moulu"],"identity_guardrails":["L''œuf entre hors ébullition et se retire dès qu''il nappe la spatule : poussé plus loin il grumelle, et la piperade liée n''est plus qu''une brouillade aux légumes.","Le thon se couche sur la piperade et ne s''y mélange jamais : incorporé, il se délite dans la masse et le plat perd la lecture en deux couches qui le définit.","Le piment d''Espelette est l''épice d''ancrage régional ; le poivre seul ou le piment fort le remplacent mal."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Thon à la basquaise gratiné', 'thon a la basquaise gratine', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'savory_tomato',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Thon à la basquaise gratiné', 'Thon à la basquaise terminé sous le gril avec une couche de fromage gratinée', ds.id, 'SRC-059-D3',
    'Myko', 'editorial', 4, 25, 38, 'facile',
    NULL, NULL,
    'B', 'candidate', 'fc3be59f91d3974ddfcb6d37761a0bfb',
    '{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":2,"intensity":3}'::jsonb, ARRAY['tomate cuite','poivron confit','thon salé']::text[],
    ARRAY['végétal cuit','fruité olive','piment doux']::text[], ARRAY['légumes fondants','pétales de thon effeuillés','sauce nappante']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Poivron rouge frais','Piment d''Espelette moulu']::text[], ARRAY['Sans le duo de poivrons rouge et vert fondus dans la tomate, il ne reste qu''un thon à la sauce tomate et le caractère basquaise disparaît.','Le thon doit rester en pétales entiers ajoutés hors du feu : mijoté avec les légumes, il se délite en rillettes et le plat change de nature.','Le piment d''Espelette est l''épice d''ancrage régional ; le poivre seul ou le piment fort le remplacent mal.']::text[],
    ARRAY['mijotage','réduction','gratinage']::text[], ARRAY[]::text[], ARRAY['poisson']::text[],
    'Se garde trois jours au réfrigérateur entre 0 et 4 °C dans une boîte fermée, et gagne même en rondeur le lendemain. Réchauffer en douceur à couvert, jamais à gros bouillon. La congélation est déconseillée : la chair de thon en conserve devient cotonneuse et les poivrons rendent leur eau à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-059'), '{"variant_label":"Étendre la piperade dans un plat, coucher le thon par-dessus et passer trois minutes sous le gril pour une version tiède gratinée.","rationale":"Rien ne bouge dans la liste, tout se joue dans les trois dernières minutes : au lieu d''être enrobé hors du feu, le thon est couché sur la piperade étalée et passé sous le gril. Les bords des pétales sèchent et se colorent, ce qui donne un contraste que la version mélangée n''a jamais, et le plat arrive à table dans son récipient de cuisson. En contrepartie le gril déshydrate la surface du poisson, exactement ce que la base cherchait à éviter, et l''assaisonnement doit être arrêté avant d''enfourner puisqu''on ne remue plus rien ensuite.","operations":[],"steps":[{"op":"replace","n":7,"instruction":"Préchauffer le gril du four. Étaler la piperade brûlante dans un plat à four en l''égalisant à la spatule, puis coucher les pétales de thon par-dessus en une seule couche, à plat et sans les enfouir : c''est la face exposée qui prendra la couleur, une pièce à demi enterrée ne dorera jamais."},{"op":"replace","n":8,"instruction":"Rectifier le sel fin et le poivre noir maintenant, avant la chaleur, en se souvenant que la saumure du thon a déjà salé le plat : une fois gratiné, plus rien ne se mélange et l''assaisonnement reste où il est tombé. Glisser le plat à mi-hauteur sous le gril trois minutes, pas davantage — on cherche des bords dorés sur les pétales, pas une cuisson. Laisser reposer cinq minutes hors du four et servir tiède, avec un riz blanc."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
