  VALUES (v_version, 5, 'Incorporer l''ail haché, attendre une minute que le parfum monte, puis ajouter la pulpe de tomate, les herbes de Provence et le piment d''Espelette. Laisser réduire quinze minutes à petit frémissement, sans couvercle, jusqu''à ce que le jus nappe les légumes au lieu de baigner la sauteuse.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Pendant ce temps, ouvrir trois boîtes de thon au naturel de 185 g net, renverser leur contenu dans une passoire et presser du dos d''une cuillère : il reste environ 390 g de chair une fois le jus de conserve évacué. La séparer en gros pétales sans la réduire en miettes.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Préchauffer le gril du four. Étaler la piperade brûlante dans un plat à four en l''égalisant à la spatule, puis coucher les pétales de thon par-dessus en une seule couche, à plat et sans les enfouir : c''est la face exposée qui prendra la couleur, une pièce à demi enterrée ne dorera jamais.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Rectifier le sel fin et le poivre noir maintenant, avant la chaleur, en se souvenant que la saumure du thon a déjà salé le plat : une fois gratiné, plus rien ne se mélange et l''assaisonnement reste où il est tombé. Glisser le plat à mi-hauteur sous le gril trois minutes, pas davantage — on cherche des bords dorés sur les pétales, pas une cuisson. Laisser reposer cinq minutes hors du four et servir tiède, avec un riz blanc.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-059-D3', 'recipe_family', 'Thon à la basquaise gratiné',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-059-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-059-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-059-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('fc3be59f91d3974ddfcb6d37761a0bfb'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_tomato","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":3,"heat":1,"pungency":2,"richness":2,"freshness":2,"intensity":3},"dominant_flavors":["tomate cuite","poivron confit","thon salé"],"aroma_families":["végétal cuit","fruité olive","piment doux"],"target_textures":["légumes fondants","pétales de thon effeuillés","sauce nappante"],"signature_ingredients":["Thon au naturel en conserve, égoutté","Poivron rouge frais","Piment d''Espelette moulu"],"identity_guardrails":["Sans le duo de poivrons rouge et vert fondus dans la tomate, il ne reste qu''un thon à la sauce tomate et le caractère basquaise disparaît.","Le thon doit rester en pétales entiers ajoutés hors du feu : mijoté avec les légumes, il se délite en rillettes et le plat change de nature.","Le piment d''Espelette est l''épice d''ancrage régional ; le poivre seul ou le piment fort le remplacent mal."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Truite aux amandes grillées à sec', 'truite aux amandes grillees a sec', 'France', 'France',
     'meal', 'plat de poisson', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Truite aux amandes grillées à sec', 'Truite meunière avec amandes effilées torréfiées à sec au beurre, sans déglacage', ds.id, 'SRC-060-D1',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f81aa6b4536c52a33f388adb7cde1c31',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":3,"freshness":3,"intensity":3}'::jsonb, ARRAY['amande torréfiée','citron','beurre fondu']::text[],
    ARRAY['fruit à coque torréfié','agrume','lacté']::text[], ARRAY['chair floconneuse','amandes sèches et cassantes','surface farinée dorée']::text[],
    ARRAY['Truite crue','Amande effilée','Beurre doux']::text[], ARRAY['Les amandes sont grillées à sec et semées au dernier moment : versées dans la sauce, elles s''imbibent en quelques secondes et le croquant sec que vise cette version disparaît.','Le beurre reste la matière grasse de la sauce, même réduit à dix grammes : sans lui le jus de citron ne se lie pas et le plat n''est plus qu''un poisson fariné arrosé d''acide.','La truite est farinée puis saisie à la poêle, peau comprise ; pochée, fumée ou gratinée, elle sort de l''identité du plat.']::text[],
    ARRAY['saisie','déglaçage','torréfaction à sec']::text[], ARRAY[]::text[], ARRAY['poisson','fruits à coque','lait','gluten']::text[],
    'Se mange immédiatement, la sauce et les amandes perdant leur croquant en quelques minutes. Les restes se gardent 24 h à 4 °C dans une boîte hermétique, amandes séparées du poisson si possible, et se réchauffent doucement à la poêle ou se mangent froids. La truite cuite supporte mal la congélation (chair qui rend son eau) et les amandes blondies ramollissent au dégel : ne pas congeler le plat monté.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-060'), '{"variant_label":"Amandes blondies à sec dans une poêle sans matière grasse, puis parsemées au dernier moment sur les truites : sauce plus légère, croquant plus sec.","rationale":"Les amandes blondissent dans une poêle nue et cessent d''être le prétexte à fondre le reste du beurre : celui-ci tombe de 50 à 30 g, dont dix seulement pour la sauce. Le croquant est plus sec et tient plus longtemps, puisque les amandes ne s''imbibent plus de gras avant d''être posées, et la part perd une bonne part de sa matière grasse. Ce qui disparaît, c''est le beurre noisette lui-même : il portait le goût de la sauce, et le jus de citron à peine lié qui le remplace est plus vif mais beaucoup plus court. Il faut aussi surveiller davantage — sans beurre pour tempérer la fonte, les amandes passent du blond au brûlé en quelques secondes.","operations":[{"op":"set","form":"Beurre doux","quantity":30}],"steps":[{"op":"replace","n":3,"instruction":"Faire chauffer l''huile d''olive avec les deux tiers du beurre dans une grande poêle sur feu moyen-vif, en gardant le dernier tiers de côté pour la sauce. Déposer les truites côté peau et les laisser prendre couleur environ cinq minutes sans y toucher, puis les retourner deux à trois minutes côté chair. La chair doit se détacher en lamelles opaques sous la pointe d''un couteau. Réserver au chaud sur le plat de service."},{"op":"replace","n":4,"instruction":"Verser les amandes effilées dans une petite poêle parfaitement sèche, sans une trace de gras, et les blondir sur feu moyen quatre à cinq minutes en secouant sans arrêt. Elles colorent plus lentement qu''au beurre et plus régulièrement, mais rien ne les protège : dès que l''odeur de noisette monte, les faire glisser sur une assiette froide, car la fonte continue de les cuire longtemps après le feu coupé."},{"op":"replace","n":5,"instruction":"Essuyer la poêle des truites avec du papier absorbant, la remettre sur feu doux et y faire fondre le reste du beurre, puis retirer du feu et verser le jus de citron en faisant tourner la poêle. Napper les poissons de ce jus à peine lié, puis semer les amandes par-dessus au tout dernier moment : posées sur une sauce courte au lieu d''y baigner, elles gardent un croquant net et cassant jusqu''à l''assiette."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'truite crue' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Truite crue', 520, 'g', 'required',
     'protéine', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'amande effilee' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Amande effilée', 65, 'g', 'required',
     'garniture', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'beurre doux' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Beurre doux', 30, 'g', 'required',
     'matière grasse', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
