    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-060-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('68b2024ed905608db350fc1e642d7a35'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"warm_aromatic","scores":{"sweet":1,"salty":3,"acidic":2,"bitter":1,"umami":2,"heat":0,"pungency":0,"richness":4,"freshness":2,"intensity":3},"dominant_flavors":["beurre noisette","amande grillée","citron"],"aroma_families":["lacté","fruit à coque torréfié","agrume"],"target_textures":["chair floconneuse","amandes croquantes","surface farinée dorée"],"signature_ingredients":["Truite crue","Amande effilée","Beurre doux"],"identity_guardrails":["L''amande doit être effilée et blondie juste avant le service : réduite en poudre, mixée en crème ou laissée crue, le plat perd le croquant qui le nomme.","Le beurre est la matière grasse de la sauce ; remplacé par une crème ou une sauce montée à l''huile seule, ce n''est plus une truite aux amandes.","Le filet reste fariné et saisi à la poêle : c''est ce que la découpe ne change pas, et sans cet enrobage doré il ne reste qu''un poisson poêlé nappé de beurre."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
