DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade de riz niçoise au riz complet', 'salade de riz nicoise au riz complet', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'bright_acidic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade de riz niçoise au riz complet', 'Riz complet froid avec thon, œufs, tomates et poivron vert en vinaigrette', ds.id, 'SRC-024-D2',
    'Myko', 'editorial', 4, 20, 22, 'facile',
    NULL, NULL,
    'B', 'candidate', '19e0ae824d08cae4f785b8da6078a0c0',
    '{"sweet":1,"salty":2,"acidic":3,"bitter":1,"umami":2,"heat":0,"pungency":1,"richness":3,"freshness":4,"intensity":2}'::jsonb, ARRAY['tomate','huile d''olive','poivron vert']::text[],
    ARRAY['végétal','fruité']::text[], ARRAY['grains de riz détachés','dés de poivron croquants','enrobage huileux léger']::text[],
    ARRAY['Thon au naturel en conserve, égoutté','Riz cru','Huile d''olive vierge extra']::text[], ARRAY['Sans thon ni œuf dur, ce n''est plus une salade niçoise mais une salade de riz aux crudités.','Le riz est refroidi avant d''être assaisonné : tiède, il boit l''huile et devient pâteux.','Les légumes restent crus et taillés à la main ; cuits, la salade perd son mordant.']::text[],
    ARRAY['pochage','marinade','émulsion']::text[], ARRAY[]::text[], ARRAY['poisson','œuf']::text[],
    'Se conserve 24 à 48 heures au réfrigérateur entre 0 et 4 °C dans un contenant hermétique ; sortir le saladier un quart d''heure avant le service pour réveiller le fruité de l''huile, qui fige au froid. Ne supporte pas la congélation : le riz devient farineux et les légumes crus rendent toute leur eau à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-024'), '{"variant_label":"Remplacer un tiers du riz blanc par du riz complet pour un grain plus mordant, en allongeant la cuisson de cinq à sept minutes.","rationale":"Un tiers du riz blanc passe au complet, quarante-cinq grammes sur cent trente : le grain garde son son, donc du mordant et un fond de noisette que le riz blanc n''a pas. Le prix est une organisation en deux temps — un trempage d''une nuit à lancer la veille, puis le riz complet jeté seul sept minutes avant le blanc, de sorte que la casserole totalise vingt-deux minutes sans que le blanc dépasse les quinze qui lui conviennent. La texture n''est plus homogène et ne cherche pas à l''être : deux grains cohabitent, l''un tendre, l''autre ferme sous la dent. Il faut aussi porter le repos au froid à une heure, le son freinant l''absorption de l''assaisonnement à la tomate.","operations":[{"op":"set","form":"Riz cru","quantity":85,"role":"féculent","optional":false},{"op":"add","form":"Riz complet cru","quantity":45,"unit":"g","role":"féculent","optional":false}],"steps":[{"op":"replace","n":1,"instruction":"Rincer le riz complet cru à l''eau froide et le laisser tremper une nuit entière, ou quatre heures au minimum : le son qui enveloppe le grain freine l''eau, et sans trempage il demanderait trois quarts d''heure de casserole là où le riz blanc en réclame quinze minutes. Une heure ne lui ferait gagner qu''une dizaine de minutes ; pour qu''il cède en vingt-deux, il doit entrer dans la casserole déjà gorgé d''eau. L''égoutter, porter un grand volume d''eau salée à ébullition et y jeter en pluie le riz complet seul. Le laisser sept minutes à découvert et à frémissement, puis ajouter le riz blanc en pluie et poursuivre quinze minutes : le complet cuit ainsi vingt-deux minutes en tout et le blanc ses quinze, chacun cédant sous la dent en gardant un cœur ferme, au lieu que l''un se défasse pendant que l''autre reste dur."},{"op":"replace","n":3,"instruction":"Verser les deux riz ensemble dans une passoire, les rincer sous un filet d''eau froide en remuant à la main jusqu''à ce qu''ils ne soient plus tièdes du tout, puis les laisser s''égoutter un bon quart d''heure : le son du grain complet retient l''eau plus longtemps que l''amidon nu du blanc, et un riz mal égoutté délaye l''assaisonnement à la tomate."},{"op":"replace","n":7,"instruction":"Goûter, rectifier en sel et en poivre, couvrir puis réserver une heure au réfrigérateur plutôt qu''une demi-heure : protégé par son son, le grain complet boit l''assaisonnement à la tomate bien plus lentement que le blanc, et une salade goûtée trop tôt paraît sèche sur un tiers de ses grains. Remuer une dernière fois juste avant de servir bien frais."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

