  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Prévoir environ 1,2 kg de calamars entiers chez le poissonnier pour obtenir les 800 g de chair nettoyée de la recette. Tirer la tête et les viscères hors du manteau, retirer la plume transparente, faire glisser la membrane violacée sous un filet d''eau froide, puis sectionner les tentacules juste au-dessus des yeux en éliminant le bec corné. Détailler les corps en anneaux d''environ un centimètre et demi et éponger le tout longuement dans un linge : une chair humide bout au lieu de dorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Faire fumer l''huile d''olive dans une cocotte à fond épais et y jeter les anneaux et les tentacules en deux fournées, sans jamais tasser le fond. Laisser accrocher deux à trois minutes par fournée en remuant peu, le temps que les bords se marquent. Débarrasser au fur et à mesure dans une passoire posée sur un bol et conserver le jus qui s''y écoule.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Baisser sous la cocotte, y verser l''oignon jaune et l''échalote finement ciselés et les laisser suer une bonne huitaine de minutes en grattant les sucs, jusqu''à transparence et sans qu''ils blondissent. Jeter alors les champignons de Paris émincés épais et remonter le feu : ils rendent d''abord toute leur eau, qu''il faut laisser s''évaporer sans couvrir, puis se colorent en cinq à six minutes — émincés trop fin ou étouffés sous un couvercle, ils se réduiraient à rien dans la sauce. Ajouter l''ail haché seulement dans la dernière minute pour qu''il reste parfumé plutôt qu''amer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Remettre les calamars et leur jus dans la cocotte, monter le feu, verser le Cognac et l''enflammer en écartant le visage et en éteignant la hotte. Attendre que la flamme retombe d''elle-même, puis racler le fond à la cuillère en bois pour décoller ce qui a caramélisé.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Mouiller avec le vin blanc sec, gratter le fond une dernière fois et laisser réduire de moitié à découvert : rien ne portera la sauce ici qu''elle-même, et c''est cette réduction seule qui lui donnera du corps. Écraser les pistils de safran entre les doigts, les jeter dans le liquide chaud et couper le feu deux minutes le temps qu''ils s''ouvrent — dans un liquide froid ils ne rendent rien, à gros bouillons ils rendent leur couleur sans leur parfum. Saler, poivrer, et ne poudrer le piment de Cayenne qu''à la pointe du couteau si l''on y tient : le safran s''efface derrière le piquant.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrir et maintenir un frémissement paresseux douze minutes, pas davantage. Le calamar n''a que deux points de tendreté : avant un quart d''heure, quand il est encore ferme et juteux, et après une heure de mijotage, quand le collagène a cédé. Entre les deux il se raidit. Goûter donc à la dixième minute et trancher franchement : soit on sert tout de suite, soit on rallonge d''une heure — s''arrêter à la demi-heure donnerait la seule texture que personne ne cherche.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couper le feu, verser la crème fraîche liquide entière en filet et la lier à la sauce safranée sans jamais la ramener à ébullition, sous peine de la voir se dissocier en grains autour des anneaux. Parsemer du persil haché, rectifier le sel, laisser reposer cinq minutes hors du feu pour que le safran finisse de se diffuser — c''est au repos qu''il prend sa couleur, pas à la cuisson — puis servir avec un riz blanc long, qui se teintera dans l''assiette.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-034-D3', 'recipe_family', 'Calamars à la crème et au safran',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-034-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-034-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-034-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f405f8af26ad45af12c9d1425a1f9763'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"creamy_savory","scores":{"sweet":2,"salty":3,"acidic":2,"bitter":0,"umami":4,"heat":1,"pungency":2,"richness":4,"freshness":1,"intensity":3},"dominant_flavors":["safran","iodé","crème","vin blanc"],"aroma_families":["marin","safrané","lacté","vineux"],"target_textures":["anneaux fermes et juteux","sauce nappante","champignons colorés"],"signature_ingredients":["Calamar cru nettoyé","Safran","Crème fraîche liquide entière","Vin blanc sec"],"identity_guardrails":["Sans calamar, il n''y a plus de plat : c''est le mollusque qui porte l''identité, la crème et le safran ne font que l''habiller.","Le safran doit rester lisible sans dominer : les 0,2 g de la liste, soit la dose courante du commerce pour quatre, sont un plafond et non un point de départ — au-delà il vire au métallique et écrase l''iode.","La cuisson est courte ou elle est longue, jamais moyenne : douze minutes laissent l''anneau ferme, une heure le détend, la demi-heure le rend coriace.","Cette version abandonne la tomate et sort du registre de l''armoricaine : elle ne peut pas en revendiquer le nom, seulement la parenté."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Coquilles Saint-Jacques aux morilles', 'coquilles saint jacques aux morilles', 'France', 'France',
     'meal', 'gratin', 'documented_variation', 'creamy_savory',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Coquilles Saint-Jacques aux morilles', 'Noix de Saint-Jacques avec champignons morilles réhydratés dans une sauce crème, gratinées', ds.id, 'SRC-039-D3',
    'Myko', 'editorial', 4, 40, 35, 'moyenne',
    NULL, NULL,
    'B', 'candidate', '66c71bca769ade4684d93a66be0faf62',
    '{"sweet":1,"salty":2,"acidic":2,"bitter":0,"umami":4,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['iodé','morille','crémeux beurré','ail']::text[],
    ARRAY['marin','sous-bois','lacté','alliacé']::text[], ARRAY['chair nacrée et moelleuse','appareil pris comme un flan','croûte de chapelure croustillante']::text[],
    ARRAY['Noix de Saint-Jacques crue','Morille crue','Crème fraîche liquide entière','Chapelure de blé']::text[], ARRAY['Sans noix de Saint-Jacques, ce n''est pas le plat : un autre poisson blanc en fait une simple coquille de poisson à la crème.','Les noix se saisissent très vite, une minute par face au plus : au-delà elles se rétractent et deviennent caoutchouteuses.','La morille passe obligatoirement à la poêle avant le four : ni crue ni simplement réchauffée, elle reste indigeste.','L''appareil aux œufs entiers ne se cuit pas sur le feu, il prend au four : chauffé en casserole, il graine et la variante n''a plus de sauce.']::text[],
    ARRAY['réhydratation','saisie','sauté','réduction','déglaçage','appareil à crème prise','gratinage']::text[], ARRAY[]::text[], ARRAY['mollusques','poisson','lait','œuf','gluten','sulfites']::text[],
    'Monté, le plat n''attend pas comme celui de la base : l''appareil cru rend son eau au contact de la chair et détrempe la coquille par le fond, deux heures à 4 °C sous film sont un maximum. Cuit, il se garde 24 h au réfrigérateur et se réchauffe 8 minutes à 160 °C, jamais plus chaud — un appareil pris qui recuit se rétracte et rend son eau. Le trempage des morilles ne se conserve pas : réhydratées, elles sont à cuire dans la journée. Congélation déconseillée pour le plat monté ou cuit ; les morilles séchées, elles, se gardent un an au sec.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-039'), '{"variant_label":"Version aux morilles réhydratées poêlées à l''ail, avec un appareil crème-œufs versé directement sur la chair avant chapelure.","rationale":"La morille apporte un fond de sous-bois qui n''existait pas dans la base et son eau de trempage renforce la réduction ; en échange, l''appareil crème-œufs versé cru remplace la sauce liée au roux, ce qui donne une texture de flan salé au lieu d''une sauce nappante. On perd donc le contrôle qu''offrait la casserole : l''appareil prend au four ou il graine, d''où les 190 °C à mi-hauteur au lieu des 210 °C du haut du four, et un quart d''heure au lieu de huit minutes. Le coût est aussi celui du produit sec, une vingtaine de grammes de morilles séchées, et une demi-heure de trempage à prévoir avant tout le reste.","operations":[{"op":"remove","form":"Farine de blé T55"},{"op":"add","form":"Morille crue","quantity":180,"unit":"g","role":"champignon","optional":false},{"op":"add","form":"Ail cru","quantity":6,"unit":"g","role":"aromate","optional":false},{"op":"set","form":"Œuf cru","quantity":3,"unit":"u","role":"appareil"}],"steps":[{"op":"insert","after":1,"instruction":"Commencer par les morilles, qui demandent une demi-heure d''avance. Peser 20 g de morilles séchées — c''est le poids d''achat, elles reprendront huit à dix fois leur poids en eau et donneront les 180 g de la liste — les couvrir d''eau à peine frémissante et les laisser gonfler trente minutes. Les sortir à la main sans presser le bol, puis les rincer une par une sous un filet d''eau froide en écartant les alvéoles, où le sable se loge et ne part pas tout seul. Filtrer le jus de trempage au linge fin et le réserver : il porte tout ce que l''eau a pris au champignon, et le jeter serait perdre la moitié de l''intérêt du produit."},{"op":"replace","n":4,"instruction":"Ciseler les échalotes menu et les faire suer deux minutes dans 10 g de beurre sans les colorer. Mouiller avec le vin blanc, ajouter le jus rendu par la chair et le jus de trempage filtré, puis laisser réduire à feu moyen jusqu''à ce qu''il ne reste que deux ou trois cuillerées sirupeuses. Le trempage a doublé le volume à évaporer : compter cinq minutes de plus qu''à l''ordinaire et ne pas abréger, c''est cette réduction qui remplacera le liant de la version gratinée."},{"op":"insert","after":5,"instruction":"Éponger les morilles dans un linge et les faire sauter à feu vif dans 25 g de beurre, cinq à six minutes, jusqu''à ce qu''elles cessent de rendre de l''eau et sentent la noisette. Ajouter l''ail haché fin pour la dernière minute seulement, saler d''une pincée et débarrasser hors du feu. Cette poêlée n''est pas facultative : la morille ne se mange ni crue ni juste tiédie, il lui faut une cuisson franche, et l''ail brûlé couvrirait le seul parfum du plat qui soit fragile."},{"op":"replace","n":5,"instruction":"Casser les œufs entiers dans un saladier et les battre juste ce qu''il faut pour rompre les jaunes, sans les faire mousser. Verser la crème dessus en filet en fouettant, puis incorporer la réduction passée au tamis, tiède et surtout pas bouillante : versée brûlante elle prendrait les œufs en fils. L''appareil doit rester franchement liquide et ne nappe pas la cuillère — il n''y a rien ici pour l''épaissir sur le feu, c''est le four qui le fera prendre."},{"op":"replace","n":6,"instruction":"Poivrer l''appareil, y ciseler le persil, goûter et n''ajuster le sel qu''après : la réduction en apporte déjà beaucoup. Ne pas céder à la tentation de le chauffer pour l''épaissir — un mélange d''œufs entiers et de crème coagule vers 80 °C et grainerait dans la casserole avant même d''atteindre la coquille. On le monte froid, on l''enfourne aussitôt."},{"op":"replace","n":7,"instruction":"Trancher les grosses pièces de chair en deux dans l''épaisseur et les répartir dans les coquilles creuses posées sur une plaque. Distribuer les morilles sautées par-dessus, puis verser l''appareil directement sur la chair, jusqu''aux deux tiers de la hauteur seulement : il gonfle un peu au four et déborderait d''une coquille remplie à ras. Saupoudrer de chapelure et parsemer des 5 g de beurre restants en tout petits éclats."},{"op":"replace","n":8,"instruction":"Enfourner à mi-hauteur d''un four préchauffé à 190 °C pour 14 à 16 minutes : l''appareil doit prendre comme un flan, à peine tremblant au centre, et la chapelure dorer sans plus. Plus chaud ou plus haut dans le four, il boursoufle puis retombe en rendant de l''eau autour de la chair, qui se rétracte du même coup. Servir sans attendre, les coquilles calées sur un lit de gros sel."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
