  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Partez d''environ 1 kg de pommes de terre à chair ferme achetées avec leur peau : une fois pelées et parées, il en reste à peu près les 800 g comestibles de la liste. Détaillez-les en rondelles régulières de 5 mm, ni transparentes ni trop épaisses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rincez rapidement les rondelles à l''eau froide pour retirer l''amidon de surface, puis séchez-les longuement dans un linge propre. Une rondelle encore humide s''étuve au lieu de colorer : c''est le point qui décide de la réussite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Nettoyez les cèpes à sec, sans jamais les passer sous le robinet : gorgé d''eau, un champignon ne rissole plus, il bouillonne. Grattez la terre du pied à la pointe du couteau, essuyez les chapeaux au linge à peine humide, puis détaillez pieds et chapeaux en tranches d''un demi-centimètre pour qu''ils cuisent au même rythme. Des girolles rendraient le même service au même poids, à ceci près qu''on se contente de parer leur base, de les garder entières si elles tiennent dans le pouce et de fendre en deux celles qui dépassent. Comptez un bon quart d''heure pour ce travail : c''est lui qui allonge la recette, pas la cuisson.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Prenez une cuisse de confit d''environ 220 g avec son os et son gras, qui donnera les 75 g de chair annoncés. Tiédissez-la à feu doux pour que la graisse se détache, effilochez la viande et réservez-la, en gardant cette fois quatre bonnes cuillerées de gras fondu : trois pour les rondelles, la quatrième mise de côté pour les cèpes, qui doivent rissoler dans le même gras et non dans du beurre.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Faites frémir ce gras dans une poêle à fond épais ou une sauteuse large, versez-y les rondelles en couche pas trop haute et patientez deux à trois minutes sans y toucher, le temps que la première face accroche une croûte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Salez, poivrez, puis faites-les sauter d''un mouvement de poignet toutes les deux minutes pendant une douzaine de minutes, jusqu''à obtenir une coloration dorée assez régulière sur l''ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Couvrez, baissez le feu et laissez le cœur devenir moelleux une dizaine de minutes, en secouant la poêle de temps à autre. Évitez la cuillère à ce stade, elle écraserait les rondelles ramollies.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 8, 'Profitez des dix minutes où les pommes de terre s''attendrissent à couvert pour faire chauffer la quatrième cuillerée de gras dans une seconde poêle, assez large pour recevoir les tranches en une seule couche : entassés, les cèpes s''étuvent au lieu de rissoler. Laissez-les rendre leur eau deux à trois minutes sans y toucher, puis montez le feu et sautez-les cinq à six minutes de plus, jusqu''à ce que le liquide ait entièrement disparu et que les tranches accrochent une couleur noisette. Ne salez qu''à cet instant : le sel donné plus tôt les aurait fait pleurer et les aurait empêchés de colorer.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 9, 'Hachez finement l''ail dégermé avec le persil. Découvrez, dispersez cette persillade, la chair de confit effilochée et les cèpes rissolés, remontez le feu deux minutes tout au plus pour réveiller les parfums sans brûler l''ail, et servez aussitôt. Les cèpes arrivent déjà cuits : ils ne font que se mêler aux rondelles, et un séjour plus long leur ferait relâcher dans la poêle l''eau qu''on vient de leur faire perdre.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-049-D2', 'recipe_family', 'Pommes de terre sarladaises aux cèpes',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-049-D2', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-049-D2', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-049-D2', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('08dbc0223b85666879d64c10f76533bd'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":3,"acidic":0,"bitter":0,"umami":4,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":4},"dominant_flavors":["ail","canard confit","cèpe rissolé","persil"],"aroma_families":["alliacé","herbacé","gras rôti","sous-bois"],"target_textures":["rondelles croustillantes en surface","cœur fondant","cèpes fermes et colorés","chair de canard effilochée"],"signature_ingredients":["Pomme de terre cuite","Confit de canard cuit","Cèpe cru"],"identity_guardrails":["La persillade ail-persil s''ajoute dans les toutes dernières minutes : cuite dès le départ, elle noircit et le plat perd son parfum caractéristique.","Les cèpes se rissolent dans une poêle à part et n''arrivent qu''à la fin : versés crus sur les rondelles, ils y rendent leur eau et défont le croustillant.","La cuisson se fait dans un gras de canard ou d''oie, ici celui du confit ; à l''huile, ce sont des pommes de terre sautées ordinaires, plus des sarladaises.","Les rondelles doivent être parfaitement essuyées avant la poêle, faute de quoi elles rendent leur eau et tournent à la purée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Pommes de terre sarladaises à la graisse d''oie', 'pommes de terre sarladaises a la graisse d oie', 'France', 'France',
     'meal', 'accompagnement', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Pommes de terre sarladaises à la graisse d''oie', 'Pommes de terre rissolées dans de la graisse d''oie pure avec ail et persil', ds.id, 'SRC-049-D3',
    'Myko', 'editorial', 4, 15, 28, 'facile',
    NULL, NULL,
    'B', 'candidate', 'f8d074fc6d3cd2c9b56f012709a9742f',
    '{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":2}'::jsonb, ARRAY['ail','graisse d''oie','persil']::text[],
    ARRAY['alliacé','herbacé','gras rôti']::text[], ARRAY['rondelles croustillantes en surface','cœur fondant']::text[],
    ARRAY['Pomme de terre cuite','Graisse d''oie','Ail cru']::text[], ARRAY['La persillade ail-persil s''ajoute dans les toutes dernières minutes : cuite dès le départ, elle noircit et le plat perd son parfum caractéristique.','La graisse d''oie est ici la seule matière grasse et le seul goût de palmipède du plat : remplacée par une huile ou par du beurre, ce ne sont plus que des pommes de terre sautées.','Le plat n''a plus de protéine : il se sert contre une viande rôtie ou poêlée, jamais seul en plat principal.','Les rondelles doivent être parfaitement essuyées avant la poêle, faute de quoi elles rendent leur eau et tournent à la purée.']::text[],
    ARRAY['saisie','étuvée','hachage']::text[], ARRAY[]::text[], ARRAY[]::text[],
    'Trois jours au réfrigérateur à 4 °C dans une boîte hermétique. Réchauffage à la poêle bien chaude pour retrouver le croustillant, jamais au micro-ondes. Congélation déconseillée : la pomme de terre déjà cuite rend son eau et devient farineuse à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-049'), '{"variant_label":"Sans confit : simple accompagnement cuit à la graisse d''oie, servi avec un magret ou une volaille rôtie.","rationale":"Le confit sort et la graisse d''oie prend sa place comme matière grasse déclarée : soixante grammes, soit les trois cuillerées que la cuisse fournissait auparavant, mais achetées en pot au lieu d''être récupérées sur la viande. Le plat reste une sarladaise — le gras de palmipède et la persillade en font l''identité, la chair de canard n''en était qu''un supplément — mais il perd sa protéine et redevient ce que l''étiquette annonce : un accompagnement, qui se sert contre un magret poêlé ou une volaille rôtie. Ce que cela coûte est du goût : soixante-quinze grammes de chair salée et de collagène disparaissent, l''umami et la longueur en bouche avec eux, et il ne reste plus que l''ail, le persil et le gras pour tenir le plat. Ce que cela fait gagner est du temps et de la simplicité, la cuisse à tiédir et à effilocher étant le poste le plus fastidieux de la recette.","operations":[{"op":"substitute","form":"Confit de canard cuit","with":"Graisse d''oie","quantity":60,"unit":"g","role":"matière grasse"}],"steps":[{"op":"replace","n":3,"instruction":"Prélevez trois bonnes cuillerées de graisse d''oie dans son pot, soit les 60 g annoncés, et laissez-les attendre à température ambiante le temps de finir les rondelles : sortie du réfrigérateur, la graisse est dure comme du beurre et met une éternité à s''étaler dans la poêle. C''est elle seule qui porte désormais le goût du plat, il n''y a plus de viande pour le faire à sa place — ne la remplacez ni par de l''huile ni par du beurre, ce ne seraient plus des sarladaises."},{"op":"replace","n":7,"instruction":"Hachez finement l''ail dégermé avec le persil. Découvrez, dispersez cette persillade, remontez le feu deux minutes tout au plus pour réveiller les parfums sans brûler l''ail, et servez aussitôt en accompagnement d''un magret poêlé ou d''une volaille rôtie, dont le jus tiendra lieu de sauce. Sans viande dans la poêle, la persillade et la graisse d''oie sont tout ce qui distingue ces rondelles de pommes de terre sautées ordinaires : ne les comptez pas à l''économie."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'pomme de terre cuite' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Pomme de terre cuite', 800, 'g', 'required',
     'féculent', false, 1);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'graisse d oie' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Graisse d''oie', 60, 'g', 'required',
     'matière grasse', false, 2);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'ail cru' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Ail cru', 10, 'g', 'required',
     'aromate', false, 3);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'persil frais' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Persil frais', 30, 'g', 'required',
     'herbe', false, 4);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'sel fin' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Sel fin', 6, 'g', 'optional',
     'assaisonnement', true, 5);

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
     source_name, quantity, unit, strictness, culinary_role, is_optional, position)
  VALUES
    (v_version, v_component, 'exact_form',
     (SELECT ff.id FROM catalog.food_forms ff
      WHERE ff.canonical_name_normalized = 'poivre noir moulu' AND ff.status <> 'rejected'
      ORDER BY CASE ff.status WHEN 'published' THEN 0 ELSE 1 END, ff.confidence_level
      LIMIT 1),
     'Poivre noir moulu', 2, 'g', 'optional',
     'assaisonnement', true, 6);

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 1, 'Partez d''environ 1 kg de pommes de terre à chair ferme achetées avec leur peau : une fois pelées et parées, il en reste à peu près les 800 g comestibles de la liste. Détaillez-les en rondelles régulières de 5 mm, ni transparentes ni trop épaisses.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 2, 'Rincez rapidement les rondelles à l''eau froide pour retirer l''amidon de surface, puis séchez-les longuement dans un linge propre. Une rondelle encore humide s''étuve au lieu de colorer : c''est le point qui décide de la réussite.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 3, 'Prélevez trois bonnes cuillerées de graisse d''oie dans son pot, soit les 60 g annoncés, et laissez-les attendre à température ambiante le temps de finir les rondelles : sortie du réfrigérateur, la graisse est dure comme du beurre et met une éternité à s''étaler dans la poêle. C''est elle seule qui porte désormais le goût du plat, il n''y a plus de viande pour le faire à sa place — ne la remplacez ni par de l''huile ni par du beurre, ce ne seraient plus des sarladaises.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 4, 'Faites frémir ce gras dans une poêle à fond épais ou une sauteuse large, versez-y les rondelles en couche pas trop haute et patientez deux à trois minutes sans y toucher, le temps que la première face accroche une croûte.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 5, 'Salez, poivrez, puis faites-les sauter d''un mouvement de poignet toutes les deux minutes pendant une douzaine de minutes, jusqu''à obtenir une coloration dorée assez régulière sur l''ensemble.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 6, 'Couvrez, baissez le feu et laissez le cœur devenir moelleux une dizaine de minutes, en secouant la poêle de temps à autre. Évitez la cuillère à ce stade, elle écraserait les rondelles ramollies.');

  INSERT INTO culinary.recipe_steps (recipe_version_id, step_number, instruction)
  VALUES (v_version, 7, 'Hachez finement l''ail dégermé avec le persil. Découvrez, dispersez cette persillade, remontez le feu deux minutes tout au plus pour réveiller les parfums sans brûler l''ail, et servez aussitôt en accompagnement d''un magret poêlé ou d''une volaille rôtie, dont le jus tiendra lieu de sauce. Sans viande dans la poêle, la persillade et la graisse d''oie sont tout ce qui distingue ces rondelles de pommes de terre sautées ordinaires : ne les comptez pas à l''économie.');

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  SELECT 'recipe_ingredient_requirement', req.id, 'missing_food_form',
         CASE WHEN req.strictness = 'required' THEN 1 ELSE 4 END,
         ARRAY['exact_form_not_in_catalog'],
         jsonb_build_object('recipe_code', 'SRC-049-D3', 'recipe_family', 'Pommes de terre sarladaises à la graisse d''oie',
                            'position', req.position, 'strictness', req.strictness),
         'open'
  FROM culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version AND req.preferred_food_form_id IS NULL;

  SELECT count(*) INTO v_missing
  FROM culinary.recipe_ingredient_requirements
  WHERE recipe_version_id = v_version
    AND strictness = 'required'
    AND preferred_food_form_id IS NULL;

  UPDATE culinary.recipe_versions
  SET planning_eligible = v_static_eligible AND v_missing = 0,
      eligibility_issues = CASE WHEN v_missing = 0
        THEN '[]'::jsonb
        ELSE jsonb_build_array(jsonb_build_object('code', 'unresolved_required_forms', 'count', v_missing))
      END
  WHERE id = v_version;

  IF v_missing > 0 THEN
    INSERT INTO quality.review_tasks
      (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
    VALUES
      ('recipe_version', v_version, 'unresolved_required_ingredient', 1,
       ARRAY['blocking_form_missing'],
       jsonb_build_object('recipe_code', 'SRC-049-D3', 'missing_required_count', v_missing), 'open');
  END IF;

  INSERT INTO quality.review_tasks
    (entity_type, entity_id, task_type, priority, reason_codes, proposed_changes, status)
  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-049-D3', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-049-D3', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('f8d074fc6d3cd2c9b56f012709a9742f'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":1,"salty":2,"acidic":0,"bitter":0,"umami":1,"heat":0,"pungency":3,"richness":4,"freshness":2,"intensity":2},"dominant_flavors":["ail","graisse d''oie","persil"],"aroma_families":["alliacé","herbacé","gras rôti"],"target_textures":["rondelles croustillantes en surface","cœur fondant"],"signature_ingredients":["Pomme de terre cuite","Graisse d''oie","Ail cru"],"identity_guardrails":["La persillade ail-persil s''ajoute dans les toutes dernières minutes : cuite dès le départ, elle noircit et le plat perd son parfum caractéristique.","La graisse d''oie est ici la seule matière grasse et le seul goût de palmipède du plat : remplacée par une huile ou par du beurre, ce ne sont plus que des pommes de terre sautées.","Le plat n''a plus de protéine : il se sert contre une viande rôtie ou poêlée, jamais seul en plat principal.","Les rondelles doivent être parfaitement essuyées avant la poêle, faute de quoi elles rendent leur eau et tournent à la purée."]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Potée auvergnate au jambonneau', 'potee auvergnate au jambonneau', 'France', 'France',
     'meal', 'plat mijoté', 'documented_variation', 'warm_aromatic',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Potée auvergnate au jambonneau', 'Potée traditionnelle avec jambonneau et saucisses fumées, chou et légumes d''hiver', ds.id, 'SRC-050-D3',
    'Myko', 'editorial', 6, 40, 160, 'facile',
    NULL, NULL,
    'B', 'candidate', 'ca68a29a8fc62d3d9bc4c31f5868ccd8',
    '{"sweet":2,"salty":4,"acidic":0,"bitter":1,"umami":5,"heat":0,"pungency":1,"richness":4,"freshness":1,"intensity":4}'::jsonb, ARRAY['porc fumé','jarret demi-sel','chou braisé','bouillon salé']::text[],
    ARRAY['fumé','épices chaudes','végétal cuit']::text[], ARRAY['légumes fondants','chair de jarret qui se défait à la fourchette','saucisse ferme et juteuse','bouillon corsé']::text[],
    ARRAY['Chou vert frais','Jambonneau cuit','Saucisse de Morteau','Saucisse de Montbéliard']::text[], ARRAY['Sans chou, ce n''est plus une potée : c''est lui qui structure le plat et parfume le bouillon en retour.','Le jambonneau s''ajoute aux deux saucisses fumées, il ne les remplace pas : c''est leur fumé qui fait le goût de cochonnaille, le jarret n''apporte que du fondant, du collagène et du sel.','Le dessalage de deux heures n''est pas négociable : un jambonneau demi-sel mis au bouillon sans dessaler rend le liquide impropre à être servi, et le bouillon est la moitié du plat.','Les légumes cuisent dans le bouillon des viandes, jamais dans une eau neuve : c''est cet échange qui distingue la potée d''un simple pot-au-feu de légumes.','Pas de liaison ni de crème : le corps du bouillon vient du jarret et de rien d''autre.']::text[],
    ARRAY['blanchiment','pochage','mijotage','écumage']::text[], ARRAY[]::text[], ARRAY['sulfites']::text[],
    'Trois jours au réfrigérateur à 4 °C, viandes et légumes conservés immergés dans leur bouillon pour ne pas sécher ; réchauffer à frémissement doux, jamais à gros bouillons. Le goût s''améliore au deuxième jour. Congélation possible deux mois pour les saucisses et le bouillon dans des boîtes séparées, mais retirer d''abord les pommes de terre, qui deviennent farineuses et grumeleuses, et le chou, qui se défait en filaments à la décongélation.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-050'), '{"variant_label":"Version charcutière complète : ajouter un jambonneau demi-sel dessalé deux heures à l''eau froide courante, mis à pocher une heure avant les saucisses.","rationale":"Un jambonneau demi-sel entre au bouillon une heure avant les saucisses et donne six cents grammes de chair qui se défait à la fourchette, soit une troisième charcuterie et un plat qui nourrit franchement six couverts. Le bouillon y gagne aussi : le jarret relâche son collagène, le liquide prend du corps sans qu''on le lie, et les légumes cuisent ensuite dans quelque chose de plus dense. Le prix est double. Il est en temps d''abord — deux heures de dessalage sous l''eau froide avant même de commencer, puis soixante minutes de pochage en tête de cuisson, ce qui porte la casserole à deux heures quarante. Il est en sel ensuite : même dessalé, le jarret continue de saler le bouillon pendant toute la cuisson, de sorte que les dix grammes de sel fin de la base descendent à cinq et ne seront le plus souvent pas employés du tout. Un dessalage écourté rend le plat entier trop salé, et rien, à ce stade, ne permet de le corriger.","operations":[{"op":"add","form":"Jambonneau cuit","quantity":600,"unit":"g","role":"protéine","optional":false},{"op":"set","form":"Sel fin","quantity":5,"optional":true}],"steps":[{"op":"insert","after":0,"instruction":"Commencer deux heures à l''avance par le dessalage du jambonneau. Prévoir une pièce demi-sel d''environ 1,1 kg avec son os, qui laissera les 600 g de chair annoncés une fois pochée et détachée. La déposer dans une bassine sous un mince filet d''eau froide courante, ou à défaut dans un grand volume d''eau froide renouvelé quatre ou cinq fois, et l''y laisser deux heures pleines. C''est ce trempage qui décide du sel du plat entier : le bouillon prendra tout ce que la viande relâchera, et plus rien ensuite ne pourra le lui retirer."},{"op":"replace","n":5,"instruction":"Coucher le jambonneau dessalé et égoutté au fond d''une grande cocotte et le recouvrir de quatre bons doigts d''eau froide — il faut voir plus large que pour les seules saucisses, puisqu''elles viendront s''y ajouter en cours de route. Ajouter l''oignon clouté, l''oignon fendu et l''ail, puis monter tout doucement en température."},{"op":"replace","n":6,"instruction":"Dès que la surface frissonne, cueillir la mousse grise à la louche jusqu''à ce que le bouillon redevienne net, puis maintenir un frémissement paresseux, couvercle posé de biais, pendant une heure : le jarret est le morceau le plus long du plat et prend cette avance sur tout le reste. Coucher alors les saucisses de Morteau et de Montbéliard entières dans le bouillon, sans jamais les piquer, écumer une seconde fois si besoin et poursuivre quarante-cinq minutes au même frémissement — une ébullition franche ferait éclater la peau des saucisses et troublerait le liquide. Ne rien saler à ce stade : entre les deux fumées et le jarret demi-sel, le bouillon se sale tout seul."},{"op":"replace","n":8,"instruction":"Goûter le bouillon avant toute correction. Avec trois charcuteries salées au lieu de deux, les 5 g de sel fin prévus seront le plus souvent de trop, et il n''est pas rare de n''en verser aucun : les incorporer par petites pincées successives en regoûtant chaque fois, ou les laisser dans la boîte. Donner un tour de moulin de poivre noir moulu et couper le feu."},{"op":"replace","n":9,"instruction":"Sortir les viandes du bouillon. Trancher les saucisses en rondelles épaisses ; dégager le jambonneau de son os et le détacher en gros morceaux à la fourchette plutôt qu''au couteau, car une chair restée près de trois heures au bouillon se défait d''elle-même et s''écraserait sous la lame. Disposer le tout au centre d''un plat creux bien chaud, ranger les légumes autour par familles, mouiller de trois ou quatre louches de bouillon brûlant et servir aussitôt, le reste du bouillon en soupière à côté."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
