  VALUES
    ('recipe_version', v_version, 'variant_enrichment', 6,
     ARRAY['variant_not_yet_sourced'],
     jsonb_build_object('recipe_code', 'SRC-053-D4', 'policy', 'source_or_test_required'), 'open');

  DELETE FROM ops.field_provenance
  WHERE entity_schema = 'culinary' AND entity_table = 'recipe_versions'
    AND entity_id = v_version AND field_name IN ('content', 'sensory_contract');
  INSERT INTO ops.field_provenance
    (entity_schema, entity_table, entity_id, field_name, source_dataset_id,
     source_record_key, normalized_value, transformation_rule, import_run_id, selected)
  SELECT 'culinary', 'recipe_versions', v_version, field_name, ds.id,
         'v3:SRC-053-D4', field_value, transformation_rule, run.id, true
  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('e7555565df1cb10e1d416ef30c9a31d0'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":3,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":4,"intensity":3},"dominant_flavors":["chèvre lactique","acidité vinaigrée","miel","tomate sucrée","fumé"],"aroma_families":["lactée","herbacée","toastée"],"target_textures":["fromage fondant","pain croustillant","feuilles croquantes","demi-tomates juteuses","éclats de noix"],"signature_ingredients":["Fromage de chèvre bûche","Pain de campagne","Miel"],"identity_guardrails":["Le chèvre doit arriver chaud et coulant sur l''assiette : servi froid ou émietté à cru, le plat perd son nom","Le pain de campagne grillé sous le fromage est le socle du plat, pas une garniture — sans lui il ne reste qu''une salade au fromage","Les tomates cerises se posent coupées, jamais entières : entières elles roulent, ne prennent pas la vinaigrette et éclatent en bouche au mauvais moment","La vinaigrette reste franchement acidulée pour trancher la richesse du fromage et le sucre des tomates cerises"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade de chèvre chaud à la poire', 'salade de chevre chaud a la poire', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade de chèvre chaud à la poire', 'Salade verte avec chèvre gratiné sur croûton et lamelles de poire fraîche', ds.id, 'SRC-053-D5',
    'Myko', 'editorial', 4, 25, 10, 'facile',
    NULL, NULL,
    'B', 'candidate', '74e272347c7041a4df0c6c54aa90a8cb',
    '{"sweet":4,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3}'::jsonb, ARRAY['chèvre lactique','poire sucrée','acidité vinaigrée','miel','fumé']::text[],
    ARRAY['lactée','fruitée','toastée']::text[], ARRAY['fromage fondant','pain croustillant','feuilles croquantes','lamelles de poire fondantes','éclats de noix']::text[],
    ARRAY['Fromage de chèvre bûche','Pain de campagne','Miel']::text[], ARRAY['Le chèvre doit arriver chaud et coulant sur l''assiette : servi froid ou émietté à cru, le plat perd son nom','Le pain de campagne grillé sous le fromage est le socle du plat, pas une garniture — sans lui il ne reste qu''une salade au fromage','La poire se pose crue, en lamelles et à l''écart du toast : cuite ou réchauffée elle rend son eau et délave la vinaigrette','La vinaigrette reste franchement acidulée : avec le miel et la poire, deux sources de sucre pèsent désormais sur l''assiette']::text[],
    ARRAY['gratinage','émulsion','saisie']::text[], ARRAY[]::text[], ARRAY['gluten','lait','fruits à coque','moutarde','sulfites']::text[],
    'La vinaigrette se garde cinq jours en bocal fermé à 4 °C et les lardons cuits deux jours au réfrigérateur. Les toasts gratinés se mangent dans la minute : réchauffés, le fromage se dessèche et le pain devient cassant. La salade assaisonnée ne se conserve pas, les feuilles tombent en une heure. Rien dans ce plat ne supporte la congélation, ni le chèvre frais qui rend son eau à la décongélation, ni la laitue.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-053'), '{"variant_label":"Ajouter de fines lamelles de poire ou quelques feuilles de basilic frais pour une note sucrée et parfumée","rationale":"L''étiquette offrait deux finitions et seule celle au basilic avait pu être écrite, le vocabulaire ne portant alors aucune poire européenne ; la voici. Deux belles poires pelées, deux cent soixante grammes de chair taillée en lamelles, apportent le sucre et le grain fondant là où le basilic n''apportait qu''un parfum. Le miel du toast n''est plus seul à sucrer et la vinaigrette doit être goûtée avec attention : trop sage, elle laisse l''assiette glisser vers le dessert. Le fruit coûte cinq minutes de parage, il brunit dans le quart d''heure si on ne l''acidule pas dès la coupe, et il ne supporte pas d''être glissé sous le toast brûlant, où il rend son eau et se défait.","operations":[{"op":"add","form":"Poire fraîche","quantity":260,"unit":"g","role":"fruit","optional":false}],"steps":[{"op":"insert","after":3,"instruction":"Peler deux belles poires mûres mais encore fermes, les couper en quartiers, ôter le cœur et les pépins, puis les tailler en lamelles de deux à trois millimètres — assez fines pour plier sous la fourchette, assez épaisses pour ne pas tourner en compote au contact du toast. Les arroser aussitôt d''une cuillerée de vinaigrette prise sur la réserve : sans cet acide, la chair coupée brunit en un quart d''heure et le fruit arrive gris sur la table."},{"op":"replace","n":7,"instruction":"Pendant le gratinage, laver et essorer la laitue, la répartir en dômes dans quatre assiettes, semer la tomate râpée, les lardons égouttés et les éclats de noix, puis coucher les lamelles de poire en éventail d''un côté de l''assiette, à l''écart du toast. Napper de vinaigrette au dernier moment, poser le toast brûlant et servir sans attendre : glissée dessous, la poire chauffe, rend son eau et devient molle en deux minutes."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

