  FROM ops.source_datasets ds
  JOIN LATERAL (
    VALUES
      ('content', to_jsonb('74e272347c7041a4df0c6c54aa90a8cb'::text), 'myko_v3_canonical_recipe'),
      ('sensory_contract', '{"profile":"savory_crisp","scores":{"sweet":4,"salty":3,"acidic":3,"bitter":1,"umami":3,"heat":0,"pungency":2,"richness":4,"freshness":3,"intensity":3},"dominant_flavors":["chèvre lactique","poire sucrée","acidité vinaigrée","miel","fumé"],"aroma_families":["lactée","fruitée","toastée"],"target_textures":["fromage fondant","pain croustillant","feuilles croquantes","lamelles de poire fondantes","éclats de noix"],"signature_ingredients":["Fromage de chèvre bûche","Pain de campagne","Miel"],"identity_guardrails":["Le chèvre doit arriver chaud et coulant sur l''assiette : servi froid ou émietté à cru, le plat perd son nom","Le pain de campagne grillé sous le fromage est le socle du plat, pas une garniture — sans lui il ne reste qu''une salade au fromage","La poire se pose crue, en lamelles et à l''écart du toast : cuite ou réchauffée elle rend son eau et délave la vinaigrette","La vinaigrette reste franchement acidulée : avec le miel et la poire, deux sources de sucre pèsent désormais sur l''assiette"]}'::jsonb, 'myko_v3_sensory_contract')
  ) AS provenance(field_name, field_value, transformation_rule) ON true
  JOIN LATERAL (
    SELECT id FROM ops.import_runs WHERE configuration_hash = 'c7079d1c46b93d646cfcc278ffe90609' LIMIT 1
  ) run ON true
  WHERE ds.code = 'myko_editorial_v3';
END
$recipe$;

DO $recipe$
DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise aux gésiers et au magret fumé', 'salade landaise aux gesiers et au magret fume', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade landaise aux gésiers et au magret fumé', 'Salade avec confit de canard, gésiers confits et magret de canard fumé en vinaigrette', ds.id, 'SRC-054-D3',
    'Myko', 'editorial', 4, 20, 15, 'facile',
    NULL, NULL,
    'B', 'candidate', 'd90c94f34199e9ab2e5a7d7285596305',
    '{"sweet":1,"salty":4,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":4,"freshness":2,"intensity":4}'::jsonb, ARRAY['gras de canard confit','fumé du magret','abat ferme','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','fumée','acidulé']::text[], ARRAY['peau de canard croustillante','chair effilochée fondante','gésier ferme sous la dent','tranche de magret souple','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Magret de canard fumé','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Sans canard confit, ce n''est plus une salade landaise : le gras de canard tiédi est le cœur du plat, et les gésiers comme le magret s''ajoutent à lui sans le remplacer.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras du confit et celui du magret fumé, qui portent à eux deux presque tout le gras de l''assiette ; une sauce crémée efface l''identité gasconne.','Le magret fumé se pose froid et cru sur le bord de l''assiette, jamais sur la viande chaude : passé à la poêle ou seulement tiédi, il rend son gras et perd le fumé qui le justifie.','Les gésiers se servent chauds et en gros morceaux : froids ou coupés en dés, ils deviennent caoutchouteux et disparaissent dans la salade.']::text[],
    ARRAY['saisie','émulsion']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites']::text[],
    'À manger dans la foulée du dressage. Les éléments se gardent séparément : chair de canard désossée trois jours à 4 °C recouverte de sa graisse, gésiers poêlés deux jours au réfrigérateur, vinaigrette une semaine en bocal fermé, pulpe de tomate le jour même. Le magret fumé entamé tient cinq jours serré dans son film, mais tranché il sèche en quelques heures : il se coupe au dernier moment. Ne se congèle pas monté : la tomate râpée rend toute son eau à la décongélation, la peau croustillante devient molle et le magret fumé perd son gras ; seuls le confit non désossé et les gésiers sous graisse supportent le congélateur, trois mois.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Ajouter des gésiers confits réchauffés à la poêle, taillés en morceaux, et deux tranches de magret fumé par personne.","rationale":"Deux abats et une charcuterie de plus, et la salade change de catégorie : de garniture de tomate au canard effiloché, elle devient l''assiette de charcuterie gasconne complète. Les gésiers apportent une mâche ferme et un goût d''abat franc que la chair effilochée n''a pas — débarrassés de leur graisse comme les veut la poêle, ils sont la pièce la plus maigre de l''assiette, deux grammes de lipides aux cent grammes contre dix-neuf pour le confit ; le magret fumé arrive en tranche froide, salée et fumée qui répond au gras tiède du confit, et c''est lui, à trente-deux grammes aux cent, qui apporte presque tout le gras ajouté. Le coût est d''abord de poids : trois cent vingt grammes de canard s''ajoutent aux deux cents de la base, soit cent trente grammes de viande par personne, et la vinaigrette de la base suffit tout juste à trancher autant de gras. Le coût le moins visible est le sel : gésiers et magret sont deux salaisons, l''assiette passe d''environ un gramme et demi de sel par part à plus de trois, et la pincée prise sur les 3 g pour la vinaigrette est désormais tout ce qu''on peut ajouter. Le coût est enfin de température : le magret fumé ne doit pas tiédir, son gras fond à rien et perd son parfum, alors que les gésiers doivent être chauds — deux exigences contraires dans la même assiette.","operations":[{"op":"add","form":"Gésier de canard confit","quantity":200,"unit":"g","role":"protéine","optional":false},{"op":"add","form":"Magret de canard fumé","quantity":120,"unit":"g","role":"charcuterie","optional":false}],"steps":[{"op":"insert","after":6,"instruction":"Remettre la poêle du confit sur feu moyen sans la laver, une fois la vinaigrette montée et non avant : les gésiers doivent arriver chauds dans l''assiette et n''attendent pas. Y coucher les gésiers de canard confits, débarrassés à la main du gras figé qui les enrobe, et les laisser raffermir et grésiller trois à quatre minutes en les retournant une fois, jusqu''à ce que les arêtes brunissent — réchauffés trop doucement ils restent caoutchouteux, poussés trop loin ils durcissent d''un coup. Les tailler chacun en deux ou trois morceaux dans l''épaisseur, jamais en dés, et les garder dans la poêle hors du feu le temps de dresser : un gésier se mange en bouchées qui résistent."},{"op":"replace","n":7,"instruction":"Détailler le magret de canard fumé en tranches très fines, deux par personne et une trentaine de grammes par assiette : plus épaisses, elles mâchent au lieu de fondre. Étaler la pulpe de tomate au fond de chaque assiette, répartir dessus la chair de canard encore tiède, les éclats de peau et les morceaux de gésier chauds, puis poser les tranches de magret en éventail sur le bord de l''assiette, là où rien ne les réchauffera. Napper d''un filet de vinaigrette au tout dernier moment et porter à table aussitôt : le gras du magret fumé fond dès qu''il tiédit et emporte son parfum avec lui."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
