DECLARE
  v_family uuid;
  v_version uuid;
  v_component uuid;
  v_missing integer;
  v_static_eligible boolean := true;
BEGIN
  INSERT INTO culinary.recipe_families
    (canonical_name, canonical_name_normalized, culinary_origin, cuisine_origin,
     meal_role, dish_structure, identity_level, sensory_profile,
     status, confidence_level)
  VALUES
    ('Salade landaise au foie gras', 'salade landaise au foie gras', 'France', 'France',
     'meal', 'salade composée', 'documented_variation', 'savory_crisp',
     'candidate', 'B')
  ON CONFLICT (canonical_name_normalized) DO UPDATE SET
    canonical_name = EXCLUDED.canonical_name,
    culinary_origin = EXCLUDED.culinary_origin,
    cuisine_origin = EXCLUDED.cuisine_origin,
    dish_structure = EXCLUDED.dish_structure,
    identity_level = EXCLUDED.identity_level,
    sensory_profile = EXCLUDED.sensory_profile,
    confidence_level = EXCLUDED.confidence_level,
    updated_at = now()
  RETURNING id INTO v_family;

  INSERT INTO culinary.recipe_versions
    (recipe_family_id, version_number, title, short_description, source_dataset_id, source_record_key,
     author_name, source_license, servings, prep_minutes, cook_minutes, difficulty,
     yield_quantity, yield_unit,
     quality_level, publication_status, content_hash,
     sensory_scores, dominant_flavors, aroma_families, target_textures,
     signature_ingredients, identity_guardrails, techniques, variant_candidates,
     allergens, conservation_text, planning_eligible, eligibility_issues,
     derived_from_version_id, derivation)
  SELECT
    v_family, 3, 'Salade landaise au foie gras', 'Salade landaise avec tranche de foie gras de canard en plus du confit', ds.id, 'SRC-054-D4',
    'Myko', 'editorial', 4, 20, 12, 'facile',
    NULL, NULL,
    'B', 'candidate', '264bca0207997c7c04efecee7afc6002',
    '{"sweet":1,"salty":3,"acidic":3,"bitter":1,"umami":4,"heat":0,"pungency":2,"richness":5,"freshness":2,"intensity":4}'::jsonb, ARRAY['foie gras poêlé','gras de canard confit','acidité vinaigrée','moutarde']::text[],
    ARRAY['rôti','abats','acidulé']::text[], ARRAY['foie gras crémeux et tiède','peau de canard croustillante','chair effilochée fondante','pulpe de tomate fraîche']::text[],
    ARRAY['Confit de canard cuit','Foie gras de canard cru','Moutarde de Dijon','Huile d''olive vierge extra']::text[], ARRAY['Sans canard confit, ce n''est plus une salade landaise : le foie gras se pose sur le confit, il ne le remplace pas.','La sauce doit rester une vinaigrette moutardée et franchement acide, seule capable de trancher le gras du confit et celui du foie gras ; une sauce crémée efface l''identité gasconne.','L''escalope se saisit à sec, poêle très chaude et moins d''une minute par face : cuite plus longtemps ou lancée dans une matière grasse ajoutée, elle fond et il ne reste rien à poser au centre.','Le foie gras arrive brûlant sur une base froide et se sert dans la minute : refroidi, il fige et graisse le fond de l''assiette.']::text[],
    ARRAY['saisie','émulsion']::text[], ARRAY[]::text[], ARRAY['moutarde','sulfites']::text[],
    'À manger dans la foulée du dressage, et plus strictement encore que la base : une escalope de foie gras poêlée ne se réchauffe pas, elle refond et se vide de son gras. Le foie gras cru se garde deux jours au plus à 4 °C, serré dans un linge, et se tranche au dernier moment. Les autres éléments tiennent séparément : chair de canard désossée trois jours sous sa graisse, vinaigrette une semaine en bocal fermé, pulpe de tomate le jour même. Rien ne se congèle une fois l''assiette montée ; le foie gras cru entier supporte trois mois au congélateur, jamais tranché.', false, '[]'::jsonb,
    (SELECT base.id FROM culinary.recipe_versions base
       JOIN ops.source_datasets base_ds ON base_ds.id = base.source_dataset_id
      WHERE base_ds.code = 'myko_editorial_v3' AND base.source_record_key = 'SRC-054'), '{"variant_label":"Version festive : une tranche de foie gras de canard posée au centre juste avant de servir.","rationale":"Une escalope de cinquante grammes par assiette, saisie à sec et posée au centre au tout dernier geste : la salade cesse d''être une entrée de tous les jours et devient un plat de fête. Le foie gras n''ajoute pas un goût neuf — on reste dans le canard — mais une texture que rien d''autre ne donne, crémeuse et tiède au milieu de la chair effilochée. Le catalogue ne porte que le foie gras cru : la tranche est donc poêlée plutôt que découpée dans une terrine, ce qui est le choix de l''arbitrage et non un contournement, l''entrée cuite comptant déjà la graisse rendue à la cuisson. Ce que la variante coûte est franc : cinquante grammes de foie gras cru pèsent trois cents kilocalories, davantage à eux seuls que tout le reste de l''assiette réuni, la fenêtre de cuisson tient dans trente secondes de part et d''autre, et l''assiette ne se rattrape pas — refroidi, le foie gras fige et graisse le fond.","operations":[{"op":"add","form":"Foie gras de canard cru","quantity":200,"unit":"g","role":"protéine","optional":false}],"steps":[{"op":"insert","after":6,"instruction":"Sortir le foie gras du froid au dernier moment et le trancher en quatre escalopes d''un bon centimètre, la lame passée sous l''eau chaude et essuyée entre chaque coupe pour qu''elle glisse au lieu d''écraser. Chauffer une poêle à sec jusqu''à ce qu''elle commence à peine à fumer, assaisonner les escalopes des deux côtés d''une pincée prise sur le sel restant et d''un tour de moulin, puis les saisir trente à quarante secondes par face : le dessus doit être coloré et le centre encore crémeux. Les débarrasser aussitôt sur du papier absorbant — laissées dans la poêle, elles continuent de fondre et il ne reste qu''une flaque de graisse."},{"op":"replace","n":7,"instruction":"Étaler la pulpe de tomate au fond de chaque assiette, disposer la chair de canard tiède et les éclats de peau en couronne autour d''un creux laissé libre, napper d''un filet de vinaigrette, puis poser l''escalope de foie gras brûlante dans ce creux au tout dernier geste. Porter à table sans attendre : le foie gras poêlé continue de rendre son gras dans l''assiette et fige dès qu''il refroidit, et c''est la seule pièce du plat qu''on ne peut pas servir tiède."}]}'::jsonb
  FROM ops.source_datasets ds WHERE ds.code = 'myko_editorial_v3'
  ON CONFLICT (recipe_family_id, version_number) DO UPDATE SET
    title = EXCLUDED.title,
    short_description = EXCLUDED.short_description,
    source_dataset_id = EXCLUDED.source_dataset_id,
    source_record_key = EXCLUDED.source_record_key,
    servings = EXCLUDED.servings,
    prep_minutes = EXCLUDED.prep_minutes,
    cook_minutes = EXCLUDED.cook_minutes,
    difficulty = EXCLUDED.difficulty,
    yield_quantity = EXCLUDED.yield_quantity,
    yield_unit = EXCLUDED.yield_unit,
    quality_level = EXCLUDED.quality_level,
    publication_status = 'candidate',
    content_hash = EXCLUDED.content_hash,
    sensory_scores = EXCLUDED.sensory_scores,
    dominant_flavors = EXCLUDED.dominant_flavors,
    aroma_families = EXCLUDED.aroma_families,
    target_textures = EXCLUDED.target_textures,
    signature_ingredients = EXCLUDED.signature_ingredients,
    identity_guardrails = EXCLUDED.identity_guardrails,
    techniques = EXCLUDED.techniques,
    variant_candidates = EXCLUDED.variant_candidates,
    allergens = EXCLUDED.allergens,
    conservation_text = EXCLUDED.conservation_text,
    planning_eligible = false,
    eligibility_issues = '[]'::jsonb,
    derived_from_version_id = EXCLUDED.derived_from_version_id,
    derivation = EXCLUDED.derivation
  RETURNING id INTO v_version;

  DELETE FROM quality.review_tasks rt
  USING culinary.recipe_ingredient_requirements req
  WHERE req.recipe_version_id = v_version
    AND rt.entity_type = 'recipe_ingredient_requirement'
    AND rt.entity_id = req.id;
  DELETE FROM quality.review_tasks WHERE entity_type = 'recipe_version' AND entity_id = v_version;
  DELETE FROM culinary.recipe_steps WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_ingredient_requirements WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_instruction_branches WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_components WHERE recipe_version_id = v_version;
  DELETE FROM culinary.recipe_variation_axes WHERE recipe_family_id = v_family;

  INSERT INTO culinary.recipe_components (recipe_version_id, name, component_role, position)
  VALUES (v_version, 'plat', 'main', 1)
  RETURNING id INTO v_component;

  INSERT INTO culinary.recipe_ingredient_requirements
    (recipe_version_id, component_id, requirement_type, preferred_food_form_id,
